/* ─────────── Helpers globales ─────────── */

// Aplana NAV en una lista de items con label, ícono y parent
function flattenNav(nav) {
  const out = [];
  for (const item of nav) {
    out.push({ id: item.id, label: item.label, icon: item.icon, parent: null });
    if (item.children) {
      for (const c of item.children) {
        out.push({ id: c.id, label: c.label, icon: c.icon, parent: item.label });
      }
    }
  }
  return out;
}

// Smart polling: 60s en horario hábil (Lun–Vie 11:00–18:00 ART), 30 min fuera
function getRefreshIntervalMs() {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone: "America/Argentina/Buenos_Aires",
    weekday: "short",
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
  }).formatToParts(new Date());
  const wd = parts.find((p) => p.type === "weekday")?.value;
  const hh = parseInt(parts.find((p) => p.type === "hour")?.value || "0", 10);
  const mm = parseInt(parts.find((p) => p.type === "minute")?.value || "0", 10);
  const isWeekday = !["Sat", "Sun"].includes(wd);

  // BYMA opera:
  //   - Pre-apertura:        10:30 - 11:00 (precios se actualizan, pero
  //                          no se ejecutan órdenes hasta la apertura).
  //   - Negociación continua:11:00 - 17:00
  //   - Subasta de cierre:   17:00 - 17:05
  //
  // Como data912 publica precios desde la pre-apertura, consideramos
  // "mercado activo" desde 10:30 hasta 17:30 (margen post-cierre para
  // capturar últimas actualizaciones del feed).
  //
  // Usamos lógica de minutos para que 10:30 sea exacto y no 10:00.
  const nowMinutes = hh * 60 + mm;
  const START_MINUTES = 10 * 60 + 30; // 10:30
  const END_MINUTES = 17 * 60 + 30;   // 17:30
  const isMarketHours = nowMinutes >= START_MINUTES && nowMinutes < END_MINUTES;

  // Activo (lun a vie 10:30 a 17:30 ART): refresh cada 15 min.
  // Inactivo: cada 30 min.
  return isWeekday && isMarketHours ? 15 * 60_000 : 30 * 60_000;
}

function isActiveMarketWindow() {
  return getRefreshIntervalMs() === 15 * 60_000;
}

// Día hábil completo (lun-vie 00:00-23:59 ART). A diferencia de
// isActiveMarketWindow (que solo es true en horario de operación
// 10:30-17:30), esto cubre el día calendario entero, lo que permite
// que "P&L HOY" se siga mostrando hasta medianoche y se resetee a 0
// a las 00:00 del día siguiente.
function isWithinTradingDay() {
  const wd = new Intl.DateTimeFormat("en-US", {
    timeZone: "America/Argentina/Buenos_Aires",
    weekday: "short",
  }).formatToParts(new Date()).find((p) => p.type === "weekday")?.value;
  return !["Sat", "Sun"].includes(wd);
}

// Período donde "P&L HOY" tiene sentido: lun-vie ≥ 10:30 ART (apertura
// del mercado) hasta 23:59 ART (medianoche). Antes de 10:30 del día
// hábil → P&L HOY = 0 (el mercado todavía no abrió hoy, no hay nada que
// medir contra el cierre de ayer). Después de 23:59 → 0 hasta que vuelva
// a abrir el próximo día hábil. Fin de semana → 0 todo el día.
function isTradingDayAndMarketOpened() {
  // Mercado AR (BYMA/MERVAL): DÍA HÁBIL (lun-vie, NO feriado bursátil) y
  // 10:30 a 17:30 ART. Antes solo miraba lun-vie + horario → daba "abierto"
  // en feriados (ej 9 de Julio). Ahora usa isNonBusinessDay (BYMA_HOLIDAYS).
  const parts = new Intl.DateTimeFormat("en-CA", {
    timeZone: "America/Argentina/Buenos_Aires",
    year: "numeric", month: "2-digit", day: "2-digit",
    hour: "2-digit", minute: "2-digit", hourCycle: "h23",
  }).formatToParts(new Date());
  const g = (t) => parts.find((p) => p.type === t)?.value;
  const arDate = `${g("year")}-${g("month")}-${g("day")}`;
  if (isNonBusinessDay(arDate)) return false; // fin de semana o feriado BYMA
  const hh = parseInt(g("hour") || "0", 10);
  const mm = parseInt(g("minute") || "0", 10);
  const mins = hh * 60 + mm;
  return mins >= 10 * 60 + 30 && mins < 17 * 60 + 30; // 10:30–17:30 ART
}

// Ventana de visibilidad del "P&L de hoy". Distinta del horario de mercado:
// arranca con la apertura (10:30 ART, día hábil) pero se MANTIENE tras el
// cierre hasta las 23:30 ART, para revisar el resultado del día a la noche.
// A las 23:30 resetea a 0 y arranca limpio el día siguiente. NO usar
// isTradingDayAndMarketOpened para esto: esa marca el mercado realmente
// abierto (10:30-17:30) y la usan los indicadores de estado.
function isPnlHoyWindow() {
  const parts = new Intl.DateTimeFormat("en-CA", {
    timeZone: "America/Argentina/Buenos_Aires",
    year: "numeric", month: "2-digit", day: "2-digit",
    hour: "2-digit", minute: "2-digit", hourCycle: "h23",
  }).formatToParts(new Date());
  const g = (t) => parts.find((p) => p.type === t)?.value;
  const arDate = `${g("year")}-${g("month")}-${g("day")}`;
  if (isNonBusinessDay(arDate)) return false; // fin de semana o feriado BYMA
  const hh = parseInt(g("hour") || "0", 10);
  const mm = parseInt(g("minute") || "0", 10);
  const mins = hh * 60 + mm;
  return mins >= 10 * 60 + 30 && mins < 23 * 60 + 30; // 10:30 → 23:30 ART
}

// Formatters
const fmtARS = (n) =>
  n == null
    ? "—"
    : n.toLocaleString("es-AR", {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
      });

// Helpers de máscara para inputs de monto en formato AR.
// Acepta dígitos + UNA coma decimal. Separadores de miles "." se insertan
// automáticamente. Si el usuario tipea "." con intención de decimal, lo
// convertimos a "," (heurística: 1 punto, sin coma, menos de 3 dígitos después).
//
// Casos típicos:
//   "1000000"     → "1.000.000"
//   "1500,5"      → "1.500,5"
//   "1500."       → "1.500,"        (punto al final = decimal, lo convertimos)
//   "1500.5"      → "1.500,5"       (formato US, 1 punto + 1 dígito = decimal)
//   "1.500"       → "1.500"         (3 dígitos después = separador miles, se mantiene)
//   "1.500.000"   → "1.500.000"     (2+ puntos = separadores miles)
//   "1.234,56"    → "1.234,56"      (paste de formato AR completo)
//
// Uso:
//   <input value={simInputAmount} onChange={(e) => setSimInputAmount(formatAmountInput(e.target.value))} />
//   const amount = parseAmountString(simInputAmount);
function formatAmountInput(raw, decimals = 2) {
  if (raw == null) return "";
  let s = String(raw);
  // Heurística: si NO hay coma todavía y el ÚLTIMO punto tiene menos
  // de 3 dígitos después (incluyendo 0 dígitos = punto al final), es
  // intento de decimal. Convertimos ese último "." a ",". Los demás
  // puntos (si los hay) se eliminan abajo como separadores de miles.
  //
  // Casos manejados:
  //   "1500"            → sin punto, sin coma → no cambio
  //   "1500."           → último punto, 0 dígitos después → decimal
  //   "1500.5"          → último punto, 1 dígito (formato US) → decimal
  //   "1.500"           → último punto, 3 dígitos → AMBIGUO, asumir miles
  //   "1.500."          → último punto, 0 dígitos → decimal (el otro "." es miles)
  //   "100.000."        → último punto, 0 dígitos → decimal (los otros son miles)
  //   "1.500.000"       → último punto, 3 dígitos → miles
  //   "1.234,56"        → hay coma → ignorar puntos (todos son miles)
  if (!s.includes(",")) {
    const lastDot = s.lastIndexOf(".");
    if (lastDot !== -1) {
      const after = s.slice(lastDot + 1);
      // 0, 1 o 2 dígitos después del último punto = intento de decimal
      if (after.length < 3) {
        s = s.slice(0, lastDot) + "," + after;
      }
      // 3 dígitos = ambiguo, asumir separador de miles (no convertir)
      // 4+ dígitos = separador de miles raro, no convertir
    }
  }
  // Quitar puntos (separadores de miles que se recrearán al final)
  s = s.replace(/\./g, "");
  // Solo dígitos y comas
  s = s.replace(/[^\d,]/g, "");
  // Permitir SOLO UNA coma (la primera)
  const firstComma = s.indexOf(",");
  if (firstComma !== -1) {
    s = s.slice(0, firstComma + 1) + s.slice(firstComma + 1).replace(/,/g, "");
  }
  // Parte entera vs decimal
  const [intPartRaw = "", decPart = null] = s.split(",");
  // Quitar ceros leading (excepto si toda la cadena es "0")
  let intPart = intPartRaw.replace(/^0+/, "");
  if (intPart === "" && intPartRaw.length > 0) intPart = "0";
  // Aplicar separadores de miles
  intPart = intPart.replace(/\B(?=(\d{3})+(?!\d))/g, ".");
  // Limitar decimales al máximo pedido
  const dec = decPart != null ? decPart.slice(0, decimals) : null;
  if (decPart !== null) return `${intPart || "0"},${dec}`;
  return intPart;
}

function parseAmountString(str) {
  if (str == null || str === "") return 0;
  // "1.000.000,50" → quitar puntos (miles) → "1000000,50" → coma a punto → 1000000.50
  const cleaned = String(str).replace(/\./g, "").replace(",", ".");
  const n = parseFloat(cleaned);
  return Number.isFinite(n) ? n : 0;
}

// Cuenta caracteres "significativos" (dígitos y coma) antes de `pos`. Los puntos
// de miles NO cuentan → permite preservar el caret al reformatear en vivo.
function countSigChars(str, pos) {
  let c = 0;
  for (let i = 0; i < pos && i < str.length; i++) if (/[\d,]/.test(str[i])) c++;
  return c;
}
// Posición en `str` justo después del `sig`-ésimo carácter significativo.
function posFromSigChars(str, sig) {
  if (sig <= 0) return 0;
  let c = 0;
  for (let i = 0; i < str.length; i++) {
    if (/[\d,]/.test(str[i])) { c++; if (c >= sig) return i + 1; }
  }
  return str.length;
}
// number o JS-number-string ("1500000.75") → máscara AR "1.500.000,75".
function numStrToArMask(v, decimals = 2) {
  if (v == null || v === "") return "";
  let s = String(v).trim();
  const neg = s.startsWith("-"); if (neg) s = s.slice(1);
  const [ipRaw = "", dp] = s.split(".");
  const ip = ipRaw.replace(/^0+(?=\d)/, "");
  const intFmt = ip === "" ? "" : ip.replace(/\B(?=(\d{3})+(?!\d))/g, ".");
  const dec = dp != null ? dp.slice(0, decimals) : null;
  return (neg ? "-" : "") + intFmt + (dec != null ? "," + dec : "");
}

// Helpers de máscara para inputs de PORCENTAJE en formato AR.
// Como un porcentaje, NO necesitamos separadores de miles. Solo manejamos
// la conversión "." → "," (intento de decimal) y limitamos a 2 decimales.
// Permite el signo "-" al principio (para apreciación / valores negativos).
//
// Casos:
//   "3.46"   → "3,46"
//   "-5"     → "-5"
//   "0.5"    → "0,5"
//   ".5"     → ",5"
//   "1,234"  → "1,23" (decimales limitados)
//
// Uso:
//   <input value={x} onChange={(e) => setX(formatPercentInput(e.target.value))} />
//   const value = parsePercentString(x);
function formatPercentInput(raw) {
  if (raw == null) return "";
  let s = String(raw);
  // Reemplazar "." por "," (formato AR, sin separadores de miles)
  s = s.replace(/\./g, ",");
  // Preservar signo "-" si está al inicio
  const isNegative = s.startsWith("-");
  s = s.replace(/-/g, "");
  // Solo dígitos y coma
  s = s.replace(/[^\d,]/g, "");
  // Una sola coma
  const firstComma = s.indexOf(",");
  if (firstComma !== -1) {
    s = s.slice(0, firstComma + 1) + s.slice(firstComma + 1).replace(/,/g, "");
    // Limitar decimales a 2
    const [intPart, decPart = ""] = s.split(",");
    s = intPart + "," + decPart.slice(0, 2);
  }
  return (isNegative ? "-" : "") + s;
}

function parsePercentString(str) {
  if (str == null || str === "") return 0;
  const cleaned = String(str).replace(",", ".");
  const n = parseFloat(cleaned);
  return Number.isFinite(n) ? n : 0;
}

const fmtPct = (n) =>
  n == null ? "—" : `${n >= 0 ? "+" : ""}${n.toFixed(2)}%`;

// TEA cap: cuando un retorno corto se anualiza, puede dar números absurdos
// (ej: S29Y6 a 4 días con +2,1% absoluto = +573% TEA).
// Para evitar confusión visual, capeamos al ±99,9% con marca > o < y
// emoji de advertencia. El tooltip explica que la TEA no es realizable
// para horizontes cortos (necesitaría rolear infinitamente).
const TEA_CAP_THRESHOLD = 0.999; // 99,9%
function formatTeaWithCap(tea, opts = {}) {
  if (tea == null || !Number.isFinite(tea)) return { text: "—", isCapped: false, raw: null };
  const pct = tea * 100;
  if (tea > TEA_CAP_THRESHOLD) {
    return { text: ">+99%", isCapped: true, raw: pct, sign: 1 };
  }
  if (tea < -TEA_CAP_THRESHOLD) {
    return { text: "<-99%", isCapped: true, raw: pct, sign: -1 };
  }
  return { text: `${pct >= 0 ? "+" : ""}${pct.toFixed(2)}%`, isCapped: false, raw: pct };
}

function timeAgo(date, now) {
  if (!date) return "—";
  const seconds = Math.floor((now - date) / 1000);
  if (seconds < 60) return `hace ${seconds}s`;
  if (seconds < 3600) return `hace ${Math.floor(seconds / 60)}m`;
  if (seconds < 86400) return `hace ${Math.floor(seconds / 3600)}h`;
  return `hace ${Math.floor(seconds / 86400)}d`;
}

