function ManualLeadBond({ bond, customExitFx }) {
  if (!bond) return null;
  const roi = bond.roiUsdManual;
  const roiColor = roi == null ? C.muted : roi >= 0 ? C.green : C.red;

  return (
    <div style={{ backgroundColor: C.panel, borderTop: `2px solid ${C.cat.pink}`, padding: "20px 22px" }}>
      <CardHeader icon={Sigma} iconColor={C.cat.pink} label="Bono Líder con tu Escenario" />
      <div className="flex flex-wrap items-end justify-between gap-6 mt-3">
        <div className="flex flex-col">
          <span className="eco-display" style={{ fontSize: 32, fontWeight: 700, color: C.cat.pink, lineHeight: 1 }}>
            {bond.ticker}
          </span>
          <span style={{ fontSize: 11, color: C.muted, marginTop: 6 }}>
            {bond.type.toUpperCase()} · Vence {formatDate(bond.maturityDate)} · {bond.days}d
          </span>
        </div>
        <div className="flex flex-wrap gap-5">
          <Metric label="ROI USD" value={roi != null ? fmtPct(roi * 100) : "—"} color={roiColor} large />
          <Metric label="ROI ARS" value={fmtPct(bond.roiArs * 100)} color={C.text} large />
          <Metric label="Dólar salida" value={`$${fmtARS(customExitFx)}`} color={C.muted} />
        </div>
      </div>
    </div>
  );
}

/* ─────────── Sintético Dólar Module (bajo Analizadores) ───────────
 *
 * Herramienta observacional — no ejecuta órdenes. Vive bajo el grupo
 * "Analizadores" en el menú, al lado de Carry Trade y Futuros vs Caución.
 * El espacio "Bot Trading" queda reservado para agentes que sí operen.
 *
 * Estrategia: comprar un bono peso (Lecap/Boncap) y cubrirse con DLR
 * futuro (long) para fijar el tipo de cambio de salida. Combinás la
 * tasa peso del bono con el FX del futuro → te queda una TIR USD
 * conocida desde el día 0, independiente del spot al vencimiento.
 *
 * Matemática (asumiendo hedge perfecto K = X/(1000×F) contratos):
 *
 *   ARS_factor = M / P                   (gross return ARS sobre el holding period)
 *   USD_factor = ARS_factor × S_0 / F    (factor sintético en USD)
 *   TIR_USD    = USD_factor^(365/T) − 1  (TIR USD anualizada TEA)
 *
 * donde:
 *   - M       = pago al vencimiento del bono por 100 VN (dato fijo del prospecto)
 *   - P       = precio actual del bono (BYMA / data912, live)
 *   - T       = días al vencimiento del bono
 *   - S_0     = spot mayorista hoy (api/dolares)
 *   - F       = precio del DLR futuro matcheado a la maturity del bono
 *
 * Por qué pago al vencimiento y no TIR directa:
 *   Ni data912 ni MAE exponen TIR como campo del feed (sí precios crudos).
 *   El pago al vencimiento (M) es un DATO FIJO del bono — sale del prospecto
 *   del Tesoro y no cambia nunca. Con M + precio live + días → TIR live se
 *   recalcula sola. El usuario carga M una sola vez por bono.
 *
 * V1 es OBSERVACIONAL: muestra el ranking de combinaciones bono↔futuro
 * por TIR_USD. La idea es identificar cuándo el sintético paga más que
 * un bono USD directo (típicamente GD30 o AL30). En versiones siguientes
 * sumamos alertas y eventualmente ejecución vía IOL API.
 *
 * Tabs en v1:
 *   - "Universo": todos los Lecaps + Boncaps activos del BOND_REGISTRY
 *   - "Cartera": solo los bonos que tiene el usuario en sus posiciones
 *
 * FCI money market: queda para v2 (necesita período de tenencia explícito,
 * no maturity natural).
 * ─────────────────────────────────────────────────────────── */

const BOND_MATURITY_LS_KEY = "ecoflow:bondMaturityPayments";

/** Lee pagos al vencimiento por ticker desde localStorage. {} si no hay nada. */
function readStoredMaturityPayments() {
  if (typeof window === "undefined") return {};
  try {
    const raw = window.localStorage.getItem(BOND_MATURITY_LS_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch {
    return {};
  }
}

/** Persiste el map de pagos al vencimiento en localStorage. */
function writeStoredMaturityPayments(map) {
  if (typeof window === "undefined") return;
  try {
    window.localStorage.setItem(BOND_MATURITY_LS_KEY, JSON.stringify(map));
  } catch {
    console.warn("No pude persistir pagos al vencimiento en localStorage");
  }
}

/**
 * Computa la TIR del bono peso (TEA, compuesta anualmente) a partir del
 * precio actual y el pago al vencimiento por 100 VN. Modelo de pago único:
 * vale para Lecaps y Boncaps capitalizables (los que tiene el usuario).
 *
 *   tir_tea = (M / P)^(365/T) − 1
 *
 * donde M = pago al vencimiento, P = precio actual, T = días al vto.
 *
 * Devuelve null si faltan datos o si el resultado no es finito.
 */
function computeBondTirTea(maturityPayment, price, days) {
  if (!Number.isFinite(maturityPayment) || maturityPayment <= 0) return null;
  if (!Number.isFinite(price) || price <= 0) return null;
  if (!Number.isFinite(days) || days <= 0) return null;
  const arsFactor = maturityPayment / price;
  if (arsFactor <= 0) return null;
  return Math.pow(arsFactor, 365 / days) - 1;
}

/**
 * Computa TIR USD anualizada del sintético "bono peso + DLR futuro long".
 *
 * @param {number} arsFactor  Factor ARS gross sobre el holding period (M/P)
 * @param {number} days       Días al vencimiento del bono
 * @param {number} spot       Spot mayorista hoy (ARS por USD)
 * @param {number} future     Precio DLR futuro matcheado (ARS por USD)
 * @returns {number|null}     TIR USD anualizada TEA (decimal: 0.05 = 5%)
 *
 * MODELO DE CÁLCULO (operativa retail argentina):
 *   - USD inicial: el inversor vendió USD a MEP para entrar (operativa real).
 *   - USD final: al expiry, asumimos convergencia MEP ≈ mayorista ≈ futuro DLR.
 *     El usuario recompra MEP del momento, pero el sintético DLR le garantiza
 *     ese precio al expiry vía el hedge con futuros.
 *   - usdFactor = arsFactor × MEP / future
 *   - TIR = usdFactor^(365/days) - 1
 *
 * Si "spotMep" no está disponible (caso edge: feed dolarapi cae), se cae al
 * spot mayorista. En ese caso pierdes el "alfa del gap MEP/mayorista" en el
 * cálculo, lo cual subestima el rendimiento real del inversor retail.
 */
function computeSyntheticUsdReturn(arsFactor, days, spotMep, future) {
  if (!Number.isFinite(arsFactor) || arsFactor <= 0) return null;
  if (!Number.isFinite(days) || days <= 0) return null;
  if (!Number.isFinite(spotMep) || spotMep <= 0) return null;
  if (!Number.isFinite(future) || future <= 0) return null;
  const usdFactor = arsFactor * spotMep / future;
  return Math.pow(usdFactor, 365 / days) - 1;
}

/* ─────────── Helpers Multi-Horizonte (Fase 1) ─────────── */

/**
 * Interpolación lineal genérica. Asume xs ordenado ascendente.
 * Si x < xs[0] → devuelve ys[0]. Si x > xs[last] → devuelve ys[last].
 * Útil para construir curvas de TIR ARS a partir de los bonos del universo.
 */
function interpolateLinear(xs, ys, x) {
  if (!Array.isArray(xs) || !Array.isArray(ys) || xs.length === 0 || xs.length !== ys.length) return null;
  if (x <= xs[0]) return ys[0];
  if (x >= xs[xs.length - 1]) return ys[ys.length - 1];
  for (let i = 1; i < xs.length; i++) {
    if (x <= xs[i]) {
      const dx = xs[i] - xs[i - 1];
      if (dx === 0) return ys[i - 1];
      const t = (x - xs[i - 1]) / dx;
      return ys[i - 1] + t * (ys[i] - ys[i - 1]);
    }
  }
  return ys[ys.length - 1];
}

/**
 * Precio del bono peso en el momento "horizon" (H días desde hoy), asumiendo
 * que al bono le quedan daysRemainingAtHorizon días hasta el vencimiento y
 * descuentan a la TIR ARS proyectada.
 *
 * Formula: precio_H = M / (1 + tirArs)^(daysRemainingAtHorizon/365)
 *
 * @param {number} maturityPayment       Pago al vencimiento (M, por 100 VN)
 * @param {number} daysRemainingAtHorizon Días que le quedan al bono al día H
 * @param {number} tirArsAtHorizon       TIR ARS asumida en ese momento (decimal)
 */
function computeBondPriceAtHorizon(maturityPayment, daysRemainingAtHorizon, tirArsAtHorizon) {
  if (!Number.isFinite(maturityPayment) || maturityPayment <= 0) return null;
  if (!Number.isFinite(daysRemainingAtHorizon) || daysRemainingAtHorizon < 0) return null;
  if (!Number.isFinite(tirArsAtHorizon)) return null;
  if (daysRemainingAtHorizon === 0) return maturityPayment;
  return maturityPayment / Math.pow(1 + tirArsAtHorizon, daysRemainingAtHorizon / 365);
}

/**
 * Computa el FX de salida efectivo para una estrategia de rolling mensual
 * sobre H días.
 *
 * Hipotesis V1 (Fase 1):
 *   - Cada DLR mantiene su precio actual hasta expirar (no proyectamos curva).
 *   - El "FX efectivo" del rolling se aproxima como el promedio ponderado
 *     por días de cada DLR usado en el camino.
 *   - Si el horizonte excede el ultimo DLR disponible, usamos el ultimo
 *     (mismo principio de "matchIsApprox" del Single hedge).
 *
 * Esta es una aproximación honesta. La Fase 2 (curva implícita DLR completa)
 * va a refinar esto modelando el roll cost real basado en TNAs por contrato.
 *
 * @param {number}   spot          Spot mayorista hoy
 * @param {Array}    futuresList   Lista de {ticker, maturityDate, expiryDays, price}
 *                                 ordenada por expiryDays ascendente, ya filtrada
 *                                 a los DLRs vivos.
 * @param {number}   horizonDays   Cuántos días vamos a hedgear.
 * @returns {object|null}          { fxEffective, dlrPath } o null si no se puede armar.
 */
function computeRollingFxOut(spot, futuresList, horizonDays) {
  if (!Number.isFinite(spot) || spot <= 0) return null;
  if (!Array.isArray(futuresList) || futuresList.length === 0) return null;
  if (!Number.isFinite(horizonDays) || horizonDays <= 0) return null;

  // Armamos el "path": qué DLR usamos en qué tramo.
  // Tramo 0..d1: DLR_1 (el front-month vivo)
  // Tramo d1..d2: DLR_2 (el siguiente)
  // ... hasta cubrir horizonDays.
  // Si horizonDays excede el último DLR disponible, el último cubre el resto
  // (igual que matchIsApprox).
  const path = [];
  let covered = 0;
  for (let i = 0; i < futuresList.length; i++) {
    const f = futuresList[i];
    if (!Number.isFinite(f.price) || f.price <= 0) continue;
    const tramoStart = covered;
    const tramoEnd = Math.min(f.expiryDays, horizonDays);
    const tramoDays = tramoEnd - tramoStart;
    if (tramoDays <= 0) continue;
    path.push({ ticker: f.ticker, days: tramoDays, price: f.price, isApprox: false });
    covered = tramoEnd;
    if (covered >= horizonDays) break;
  }
  // Si quedó tramo sin cubrir, lo asignamos al último DLR (aprox).
  if (covered < horizonDays && path.length > 0) {
    const remaining = horizonDays - covered;
    const last = path[path.length - 1];
    // Sumamos los días extra al último tramo y marcamos aprox.
    last.days += remaining;
    last.isApprox = true;
  }
  if (path.length === 0) return null;

  // FX efectivo: promedio ponderado por días de cada tramo.
  // Justificación heurística: bajo hipótesis "el spot al expirar de cada
  // DLR es exactamente su precio actual" (lo que el contrato garantiza),
  // el costo promedio de hedgear es esa media ponderada.
  let sumWeighted = 0;
  let sumDays = 0;
  for (const seg of path) {
    sumWeighted += seg.price * seg.days;
    sumDays += seg.days;
  }
  const fxEffective = sumDays > 0 ? sumWeighted / sumDays : null;
  const hasApprox = path.some((s) => s.isApprox);
  return { fxEffective, dlrPath: path, isApprox: hasApprox };
}

/**
 * Encuentra el mejor DLR para Single hedge a un horizonte H.
 * - Si existe un DLR cuyo expiry >= H, usa el más cercano (cobertura limpia).
 * - Si no, usa el último DLR disponible (aprox, igual que matchIsApprox).
 *
 * @param {Array}  futuresList   Ordenada asc por expiryDays. Solo DLRs con precio.
 * @param {number} horizonDays   Cuántos días queremos cubrir.
 * @returns {object|null} { ticker, price, expiryDays, isApprox } o null.
 */
function findBestSingleHedgeForHorizon(futuresList, horizonDays) {
  if (!Array.isArray(futuresList) || futuresList.length === 0) return null;
  if (!Number.isFinite(horizonDays) || horizonDays <= 0) return null;
  const cover = futuresList.find((f) => f.expiryDays >= horizonDays);
  if (cover) {
    return { ticker: cover.ticker, price: cover.price, expiryDays: cover.expiryDays, isApprox: false };
  }
  const last = futuresList[futuresList.length - 1];
  return { ticker: last.ticker, price: last.price, expiryDays: last.expiryDays, isApprox: true };
}

/**
 * Construye la "curva DLR" con detector de basis.
 *
 * Toma la lista de futuros DLR vivos del feed y calcula, para cada uno,
 * cuánto DEBERÍA valer si la devaluación mensual fuera constante entre el
 * primer y el último DLR de la curva. La desviación (basis) entre precio
 * real y precio teórico señala oportunidades:
 *
 *   - basis negativo (real < teórico): el DLR está DESCONTADO → usarlo
 *     para hedgear es más barato que la "curva lisa". Verde.
 *   - basis positivo (real > teórico): el DLR tiene PRIMA → hedgear con
 *     este es más caro que la curva lisa. Rojo (evitar como hedge).
 *   - basis dentro de ±0.3%: neutro (gris).
 *
 * Las "anclas" (primer y último DLR) tienen basis = 0 por construcción.
 *
 * Metodología: tasa de devaluación DIARIA constante entre la primera y
 * última ancla. Es la curva exponencial limpia que un mercado eficiente
 * descontaría si pricara devaluación mensual estable.
 *
 *   factor_total = price_last / price_first
 *   days_anchor_to_anchor = expiryDays(last) - expiryDays(first)
 *   daily_rate = factor_total^(1/days_anchor_to_anchor) - 1
 *
 *   Para cada DLR intermedio i:
 *     days_from_first = expiryDays(i) - expiryDays(first)
 *     price_theoric_i = price_first × (1 + daily_rate)^days_from_first
 *     basis_i = (price_real_i - price_theoric_i) / price_theoric_i
 *
 * @param {Array} futuresList — array de futuros con {ticker, price, expiryDays}
 *                             ordenados por expiryDays ascendente.
 * @param {number} thresholdPct — umbral en decimal para marcar "barato" o
 *                                "caro" (default 0.003 = 0.3%).
 * @returns {Object|null} { points, anchorFirst, anchorLast, dailyDevRate,
 *                          monthlyDevRate, annualDevRate } o null si no hay
 *                          datos suficientes (necesita >= 2 DLRs con precio).
 */
function buildDlrCurve(futuresList, thresholdPct = 0.003, spotAnchor = null, remResolver = null, caucionRate = null) {
  if (!Array.isArray(futuresList) || futuresList.length < 2) return null;

  // Filtrar solo DLRs con precio válido y días al vto válidos.
  // Algunos DLR del feed pueden venir sin precio si Primary no respondió.
  const valid = futuresList.filter(
    (f) => Number.isFinite(f.price) && f.price > 0 &&
           Number.isFinite(f.expiryDays) && f.expiryDays > 0
  );
  if (valid.length < 2) return null;

  // Sort por días al vto ascendente (por las dudas)
  const sortedFutures = [...valid].sort((a, b) => a.expiryDays - b.expiryDays);

  // Ancla inicial: el SPOT mayorista (t=0) si está disponible. Es lo que vale
  // el dólar HOY, y desde ahí se forma la curva. Anclar en el primer futuro
  // (JUN26) sesga toda la curva si ese futuro está caro/barato, y además lo
  // deja con basis 0 ocultando su propio mispricing. Con el spot como ancla,
  // cada futuro (incluido el primero) tiene basis real vs la devaluación
  // implícita spot→último DLR. Sin spot, cae al comportamiento viejo.
  const useSpot =
    spotAnchor && Number.isFinite(spotAnchor.price) && spotAnchor.price > 0;
  const sorted = useSpot
    ? [{ ...spotAnchor, expiryDays: 0 }, ...sortedFutures]
    : sortedFutures;

  const anchorFirst = sorted[0];
  const anchorLast = sorted[sorted.length - 1];

  const daysSpan = anchorLast.expiryDays - anchorFirst.expiryDays;
  if (daysSpan <= 0) return null;

  const factorTotal = anchorLast.price / anchorFirst.price;
  if (!Number.isFinite(factorTotal) || factorTotal <= 0) return null;

  // Tasa diaria implícita constante entre primer y último DLR
  const dailyDevRate = Math.pow(factorTotal, 1 / daysSpan) - 1;
  const monthlyDevRate = Math.pow(1 + dailyDevRate, 30) - 1;
  const annualDevRate = Math.pow(1 + dailyDevRate, 365) - 1;

  // Calcular precio teórico y basis para cada DLR
  const points = sorted.map((f, idx) => {
    const isAnchorFirst = idx === 0;
    const isAnchorLast = idx === sorted.length - 1;
    const isAnchor = isAnchorFirst || isAnchorLast;

    const daysFromFirst = f.expiryDays - anchorFirst.expiryDays;
    const priceTheoric = anchorFirst.price * Math.pow(1 + dailyDevRate, daysFromFirst);
    const basis = isAnchor ? 0 : (f.price - priceTheoric) / priceTheoric;

    let status = "neutro";
    if (!isAnchor) {
      if (basis < -thresholdPct) status = "barato";
      else if (basis > thresholdPct) status = "caro";
    } else {
      status = "ancla";
    }

    // Benchmark externo: la curva REM (pronóstico de consultoras). A diferencia
    // del basis interno (vs la forma de la propia curva), acá "caro" = el
    // mercado pricea MÁS devaluación que el consenso REM; "barato" = menos.
    const priceRem = (!f.isSpot && f.maturityDate && remResolver) ? remResolver(f.maturityDate) : null;
    const basisRem = (priceRem != null && priceRem > 0) ? (f.price - priceRem) / priceRem : null;
    let statusRem = "neutro";
    if (basisRem != null) {
      if (basisRem < -thresholdPct) statusRem = "barato";
      else if (basisRem > thresholdPct) statusRem = "caro";
    }

    // TNA implícita (vs spot, simple) y comparación con la caución (cash-and-carry):
    // vsCaucion = caución − implícita. >0 → caución gana, futuro BARATO (rulo a favor);
    // <0 → implícita > caución, futuro CARO (lado short). Solo con ancla spot.
    // TNA (nominal proporcional) y TEA (efectiva compuesta) implícitas vía los
    // helpers canónicos de dlrContracts — MISMA convención que el widget
    // CarryDlrWidget y el Sintético DLR (una sola fuente de verdad, sin drift).
    const tnaImplicita = (useSpot && !f.isSpot && f.expiryDays > 0)
      ? implicitTNA(f.price, anchorFirst.price, f.expiryDays) : null;
    const tnaImplicitaPct = tnaImplicita != null ? tnaImplicita * 100 : null;
    const teaImplicita = (useSpot && !f.isSpot && f.expiryDays > 0)
      ? implicitTEA(f.price, anchorFirst.price, f.expiryDays) : null;
    const teaImplicitaPct = teaImplicita != null ? teaImplicita * 100 : null;
    const vsCaucion = (tnaImplicitaPct != null && Number.isFinite(caucionRate)) ? caucionRate - tnaImplicitaPct : null;
    let statusCaucion = "neutro";
    if (vsCaucion != null) {
      if (vsCaucion > 1) statusCaucion = "barato";       // caución > implícita → rulo a favor
      else if (vsCaucion < -1) statusCaucion = "caro";   // implícita > caución → futuro caro
    }

    return {
      ticker: f.ticker,
      shortTicker: f.shortTicker || f.ticker.replace(/^DLR/, ""), // "DLRJUN26" → "JUN26"
      expiryDays: f.expiryDays,
      price: f.price,
      priceTheoric,
      basis,
      basisPct: basis * 100,
      status,
      priceRem,
      basisRem,
      basisRemPct: basisRem != null ? basisRem * 100 : null,
      statusRem,
      tnaImplicita,
      tnaImplicitaPct,
      teaImplicita,
      teaImplicitaPct,
      vsCaucion,
      statusCaucion,
      isAnchor,
      isAnchorFirst,
      isAnchorLast,
      isSpot: !!f.isSpot,
    };
  });

  // Deval anual implícita del REM (spot → REM del futuro más largo), para
  // comparar de un vistazo contra la implícita del mercado.
  const lastRemPoint = [...points].reverse().find((p) => p.priceRem != null);
  const remAnnualDevRate = (useSpot && lastRemPoint && anchorFirst.price > 0 && lastRemPoint.expiryDays > 0)
    ? implicitTEA(lastRemPoint.priceRem, anchorFirst.price, lastRemPoint.expiryDays)
    : null;

  return {
    points,
    anchorFirst: points[0],
    anchorLast: points[points.length - 1],
    dailyDevRate,
    monthlyDevRate,
    annualDevRate,
    hasRem: points.some((p) => p.priceRem != null),
    remAnnualDevRate,
    caucionRate: Number.isFinite(caucionRate) ? caucionRate : null,
    hasCaucion: points.some((p) => p.vsCaucion != null),
    threshold: thresholdPct,
    // Helper para que la UI saque rápido un DLR de la curva por ticker
    byTicker: new Map(points.map((p) => [p.ticker, p])),
  };
}

/**
 * Helper que arma la curva DLR a partir de `futurePrices` (objeto crudo
 * indexado por ticker, como el que devuelve useFuturePrices).
 *
 * Replica la lógica de filtrado/sorting que estaba inline en SinteticoDolarModule:
 *   1. Filtrar DLR_REGISTRY por vivos (expiryDays > 0).
 *   2. Para cada uno, resolver precio (price > settlement como fallback).
 *   3. Filtrar los sin precio válido.
 *   4. Sort por expiryDays ascendente.
 *   5. Pasar a buildDlrCurve.
 *
 * Usado en DashboardOverview para mostrar la curva DLR como sección
 * standalone, sin necesidad de los useMemos pesados del SinteticoDolarModule.
 *
 * @param {Object} futurePrices — { ticker: { price, settlement, error, ... } }
 * @param {number} thresholdPct — umbral basis (default 0.003 = 0.3%)
 * @returns {Object|null} resultado de buildDlrCurve, o null si no hay datos
 */
function buildDlrCurveFromFuturePrices(futurePrices, thresholdPct = 0.003, spotPrice = null, remTc = null, remIpc = null, caucionRate = null) {
  if (!futurePrices || typeof futurePrices !== "object") return null;

  const futuresLive = DLR_REGISTRY
    .map((c) => ({ ...c, expiryDays: daysToExpiry(c.maturityDate) }))
    .filter((c) => c.expiryDays > 0)
    .map((f) => {
      const fp = futurePrices[f.ticker];
      let price = null;
      if (fp?.price > 0 && !fp.error) price = Number(fp.price);
      else if (fp?.settlement > 0 && !fp.error) price = Number(fp.settlement);
      return { ...f, price };
    })
    .filter((f) => Number.isFinite(f.price) && f.price > 0)
    .sort((a, b) => a.expiryDays - b.expiryDays);

  const spotAnchor =
    Number.isFinite(spotPrice) && spotPrice > 0
      ? { ticker: "SPOT", shortTicker: "SPOT", price: Number(spotPrice), isSpot: true }
      : null;

  const remResolver = (remTc && Object.keys(remTc).length > 0)
    ? (maturityDate) => projectREMTC(maturityDate, remTc, remIpc || {})
    : null;

  return buildDlrCurve(futuresLive, thresholdPct, spotAnchor, remResolver, caucionRate);
}

/**
 * Computa todas las TIR USD para un bono dado a multiples horizontes y
 * estrategias. Devuelve la matriz completa para que la UI elija qué mostrar.
 *
 * Variantes computadas (5 horizontes × 2 estrategias × 2 modelos = 20 valores):
 *   - Horizontes: 30, 60, 90, 180, vto
 *   - Estrategias: "single" (un DLR que cubra H), "rolling" (sucesion DLR mensual)
 *   - Modelos de precio futuro del bono: "const" (TIR ARS constante),
 *                                        "curve" (TIR ARS interpolada de la curva)
 *
 * Nota importante (post-fix del bug del Single a horizontes intermedios):
 *   Single hedge a horizonte H usa el DLR MÁS CERCANO A H (no el que cubre
 *   el vto del bono). Antes usaba siempre matchFuture del bono, lo que daba
 *   TIRs absurdas (-93%, -83%) para H < vto. Ahora "Single hedge a 30d"
 *   = compro el DLR que vence a ~30d (ej. DLRJUN26 para T30A7), no DLRABR27.
 *
 * @param {object} ctx  Contexto compartido
 *   - daysToBondMaturity: días hoy → vto del bono
 *   - maturityPayment: M (pago al vto)
 *   - bondPrice: P (precio actual del bono)
 *   - tirArsToday: TIR ARS computada hoy (constante baseline)
 *   - spot: spot mayorista
 *   - curveData: { xs: [días], ys: [tirArs] } curva ARS para interpolar
 *   - futuresList: lista ordenada asc por expiryDays (DLRs vivos con precio)
 *
 * @returns {object} { single: { const: {...horizons}, curve: {...} }, rolling: {...},
 *                     singleHedges: { horizonKey: {ticker, isApprox} },
 *                     rollingPaths: { horizonKey: {dlrPath, isApprox} } }
 */
function computeMultiHorizonTirUsd(ctx) {
  const { daysToBondMaturity, maturityPayment, bondPrice, tirArsToday, spot, spotMep,
          curveData, futuresList } = ctx;
  const HORIZONS = [30, 60, 90, 180, daysToBondMaturity];
  const result = {
    single: { const: {}, curve: {} },
    rolling: { const: {}, curve: {} },
    singleHedges: {}, // horizonKey → {ticker, price, isApprox}
    rollingPaths: {}, // horizonKey → {dlrPath, isApprox}
  };

  if (!Number.isFinite(maturityPayment) || maturityPayment <= 0 ||
      !Number.isFinite(bondPrice) || bondPrice <= 0 ||
      !Number.isFinite(spot) || spot <= 0 ||
      !Number.isFinite(daysToBondMaturity) || daysToBondMaturity <= 0) {
    return result;
  }

  // El "spot" para el cálculo del USD inicial es el MEP (operativa retail).
  // Si no tenemos MEP por algún motivo, caemos al mayorista (subestima
  // el rendimiento real del inversor retail, pero es mejor que nada).
  const fxEntry = (Number.isFinite(spotMep) && spotMep > 0) ? spotMep : spot;

  for (const h of HORIZONS) {
    if (!Number.isFinite(h) || h <= 0) continue;
    const effH = Math.min(h, daysToBondMaturity);
    const daysRemaining = daysToBondMaturity - effH;
    const horizonKey = h === daysToBondMaturity ? "vto" : String(h);

    // Precio del bono al horizonte H bajo los 2 modelos:
    const tirArsConst = Number.isFinite(tirArsToday) ? tirArsToday : null;
    const tirArsCurve = curveData
      ? interpolateLinear(curveData.xs, curveData.ys, daysRemaining)
      : null;

    const priceAtH_const = (effH === daysToBondMaturity)
      ? maturityPayment
      : computeBondPriceAtHorizon(maturityPayment, daysRemaining, tirArsConst);
    const priceAtH_curve = (effH === daysToBondMaturity)
      ? maturityPayment
      : computeBondPriceAtHorizon(maturityPayment, daysRemaining, tirArsCurve);

    // Factor ARS gross sobre el holding period (precio_H / P_hoy)
    const arsFactor_const = priceAtH_const ? priceAtH_const / bondPrice : null;
    const arsFactor_curve = priceAtH_curve ? priceAtH_curve / bondPrice : null;

    // ─── Single hedge ───
    // El DLR rolling sigue usando "spot" (mayorista) porque los futuros
    // convergen al mayorista, no al MEP. Pero el USD inicial se calcula
    // con MEP (fxEntry) para reflejar la operativa retail real.
    const bestSingle = findBestSingleHedgeForHorizon(futuresList, effH);
    if (bestSingle && Number.isFinite(bestSingle.price) && bestSingle.price > 0) {
      result.single.const[horizonKey] = arsFactor_const
        ? computeSyntheticUsdReturn(arsFactor_const, effH, fxEntry, bestSingle.price)
        : null;
      result.single.curve[horizonKey] = arsFactor_curve
        ? computeSyntheticUsdReturn(arsFactor_curve, effH, fxEntry, bestSingle.price)
        : null;
      result.singleHedges[horizonKey] = bestSingle;
    } else {
      result.single.const[horizonKey] = null;
      result.single.curve[horizonKey] = null;
      result.singleHedges[horizonKey] = null;
    }

    // ─── Rolling ───
    const rolling = computeRollingFxOut(spot, futuresList, effH);
    if (rolling && Number.isFinite(rolling.fxEffective) && rolling.fxEffective > 0) {
      result.rolling.const[horizonKey] = arsFactor_const
        ? computeSyntheticUsdReturn(arsFactor_const, effH, fxEntry, rolling.fxEffective)
        : null;
      result.rolling.curve[horizonKey] = arsFactor_curve
        ? computeSyntheticUsdReturn(arsFactor_curve, effH, fxEntry, rolling.fxEffective)
        : null;
      result.rollingPaths[horizonKey] = rolling;
    } else {
      result.rolling.const[horizonKey] = null;
      result.rolling.curve[horizonKey] = null;
      result.rollingPaths[horizonKey] = null;
    }
  }
  return result;
}

/**
 * Dada la matriz de TIR USD multi-horizonte, devuelve { horizon, tir } del
 * pico para una combinación estrategia/modelo. Se usa para la columna "Peak"
 * de la tabla principal.
 */
function findPeakTir(multiTir, strategy, model) {
  const block = multiTir?.[strategy]?.[model];
  if (!block) return null;
  let bestKey = null;
  let bestTir = -Infinity;
  for (const [k, v] of Object.entries(block)) {
    if (!Number.isFinite(v)) continue;
    if (v > bestTir) {
      bestTir = v;
      bestKey = k;
    }
  }
  if (bestKey == null) return null;
  return { horizon: bestKey, tir: bestTir };
}

/**
 * Hook que lee el catalogo de emisiones del Tesoro desde la tabla
 * bond_emissions de Supabase. Esa tabla la popula el worker
 * bond-emissions-sync (corre Mi/Ju, scrapea argentina.gob.ar) y trae
 * por cada Lecap/Boncap activo:
 *   - fecha_vencimiento (parseada del titulo de la fila)
 *   - pago_vencimiento (computado: PC × (1+TIREA)^años / 10)
 *   - tem_capitalizacion (sale del prospecto del Tesoro)
 *
 * Devuelve un Map<ticker, {ticker, type, maturityDate, pagoVencimiento,
 * temCapitalizacion, lastAuctionDate, lastSourceUrl}>.
 *
 * Si Supabase falla, devuelve emissions=null y error con el mensaje. El
 * componente que lo consume debe tener un fallback (en el caso del
 * Sintetico DLR: BOND_REGISTRY hardcoded + input manual del usuario).
 */
function useBondEmissions() {
  const [emissions, setEmissions] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const fetchEmissions = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const { data, error: qErr } = await supabase
        .from("bond_emissions")
        .select("ticker, type, fecha_vencimiento, pago_vencimiento, tem_capitalizacion, last_auction_date, last_source_url");
      if (qErr) throw qErr;
      const map = new Map();
      for (const row of data || []) {
        if (!row?.ticker) continue;
        map.set(row.ticker, {
          ticker: row.ticker,
          type: row.type,
          maturityDate: row.fecha_vencimiento, // ISO yyyy-mm-dd
          pagoVencimiento: Number(row.pago_vencimiento),
          temCapitalizacion: Number(row.tem_capitalizacion),
          lastAuctionDate: row.last_auction_date,
          lastSourceUrl: row.last_source_url,
        });
      }
      setEmissions(map);
    } catch (e) {
      console.warn("useBondEmissions: fetch fallo:", e);
      setError(e?.message || String(e));
      // No limpiamos emissions si ya teniamos data — preferimos data
      // stale a data nula. Solo seteamos null si nunca tuvimos nada.
      setEmissions((prev) => prev || null);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchEmissions();
  }, [fetchEmissions]);

  return { emissions, loading, error, refetch: fetchEmissions };
}

/**
 * Bonos Duales TAMAR (BONTAM) — catalogo hardcoded.
 *
 * Estos bonos pagan al vencimiento el MAX entre:
 *   (a) tasa fija capitalizada desde la emision (TEM fija conocida)
 *   (b) TAMAR mensual acumulada del periodo (variable, depende del
 *       camino real de la tasa)
 *
 * Como no podemos predecir TAMAR, computamos solo el rama (a) — el
 * PISO garantizado del pago. Si TAMAR > tasa fija promedio, el pago
 * real va a ser mayor; en cambio, si TAMAR queda por debajo, el bono
 * paga exactamente este floor.
 *
 * La idea: si la TIR USD del FLOOR ya es atractiva, el sintetico es
 * buena oportunidad casi sin importar el camino de TAMAR.
 *
 * Long-term: hay que extender el worker bond-emissions-sync para que
 * detecte BONTAMs en los articulos del Tesoro y los persista con
 * fecha de emision + tasa fija. Hoy lo hardcodeamos.
 *
 * Datos sacados del canje de ene-2025: bonos a marzo, junio, sept
 * y dic de 2026. Tasas fijas 2.25%, 2.19%, 2.17% y 2.14% TEM
 * respectivamente (fuente: comunicado de Secretaria de Finanzas
 * y notas de prensa de Cronista/Debursa/Bloomberg).
 */
const KNOWN_BONTAMS = {
  TTM26: { temFija: 0.0225, fechaEmision: "2025-01-29", maturityDate: "2026-03-16" },
  TTJ26: { temFija: 0.0219, fechaEmision: "2025-01-29", maturityDate: "2026-06-30" },
  TTS26: { temFija: 0.0217, fechaEmision: "2025-01-29", maturityDate: "2026-09-15" },
  TTD26: { temFija: 0.0214, fechaEmision: "2025-01-29", maturityDate: "2026-12-15" },
};

/**
 * Computa el pago al vto FLOOR de un BONTAM usando solo la rama de
 * tasa fija. Es el escenario "TAMAR queda por debajo de la fija en
 * todo el periodo" — el peor caso garantizado.
 *
 * Formula: 100 × (1 + temFija)^N_meses_desde_emision_a_vto
 */
function computeBontamFloor(temFija, fechaEmision, maturityDate) {
  const ms = new Date(maturityDate).getTime() - new Date(fechaEmision).getTime();
  if (!Number.isFinite(ms) || ms <= 0) return null;
  const meses = ms / (1000 * 60 * 60 * 24 * 30.4375);
  return 100 * Math.pow(1 + temFija, meses);
}

// ═══════════════════════════════════════════════════════════════════════
// DlrCurveSection: componente visual reusable de la Curva DLR + Basis.
//
// Recibe el objeto dlrCurve ya construido por buildDlrCurve(), el tema C,
// y un prop opcional `compact` para versión chica (sin tabla ni nota).
//
// Uso típico:
//   const dlrCurve = useMemo(() => buildDlrCurve(futuresLive, 0.003), [futuresLive]);
//   <DlrCurveSection dlrCurve={dlrCurve} C={C} />          // full (default)
//   <DlrCurveSection dlrCurve={dlrCurve} C={C} compact />   // compact
//
// Originalmente vivía inline en SinteticoDolarModule; se extrajo para
// poder reusar en el Dashboard (y otros lugares futuros).
// ═══════════════════════════════════════════════════════════════════════
function DlrCurveSection({ dlrCurve, C, compact = false, hideTitle = false }) {
  if (!dlrCurve || dlrCurve.points.length < 2) return null;

  // Constantes de layout del SVG. En compact: gráfico más chico, sin tabla.
  const SVG_W = compact ? 680 : 1100;
  const SVG_H = compact ? 220 : 320;
  const PAD_LEFT = compact ? 50 : 70;
  const PAD_RIGHT = compact ? 25 : 40;
  const PAD_TOP = compact ? 24 : 30;
  const PAD_BOTTOM = compact ? 42 : 55;
  const plotW = SVG_W - PAD_LEFT - PAD_RIGHT;
  const plotH = SVG_H - PAD_TOP - PAD_BOTTOM;

  const xMin = dlrCurve.points[0].expiryDays;
  const xMax = dlrCurve.points[dlrCurve.points.length - 1].expiryDays;
  const xSpan = xMax - xMin;

  const allPrices = dlrCurve.points.flatMap((p) => [p.price, p.priceTheoric, ...(p.priceRem != null ? [p.priceRem] : [])]);
  const yMin = Math.min(...allPrices) * 0.98;
  const yMax = Math.max(...allPrices) * 1.02;
  const ySpan = yMax - yMin;

  const xCoord = (days) => PAD_LEFT + ((days - xMin) / xSpan) * plotW;
  const yCoord = (price) => PAD_TOP + plotH - ((price - yMin) / ySpan) * plotH;

  const pathReal = dlrCurve.points
    .map((p, i) => `${i === 0 ? "M" : "L"} ${xCoord(p.expiryDays)} ${yCoord(p.price)}`)
    .join(" ");
  const pathTheoric = dlrCurve.points
    .map((p, i) => `${i === 0 ? "M" : "L"} ${xCoord(p.expiryDays)} ${yCoord(p.priceTheoric)}`)
    .join(" ");
  const remPts = dlrCurve.points.filter((p) => p.priceRem != null);
  const pathRem = remPts.map((p, i) => `${i === 0 ? "M" : "L"} ${xCoord(p.expiryDays)} ${yCoord(p.priceRem)}`).join(" ");

  const yTicks = [0, 0.25, 0.5, 0.75, 1].map((f) => yMin + ySpan * f);

  const colorForStatus = (s) => {
    if (s === "barato") return C.green;
    if (s === "caro") return C.red;
    if (s === "ancla") return C.accent;
    return C.muted;
  };

  const baratos = dlrCurve.points.filter((p) => p.status === "barato");
  const caros = dlrCurve.points.filter((p) => p.status === "caro");
  const carosRem = dlrCurve.points.filter((p) => p.statusRem === "caro");
  const baratosRem = dlrCurve.points.filter((p) => p.statusRem === "barato");
  const hasSpotAnchor = !!dlrCurve.points[0]?.isSpot;
  const anchorLabel = hasSpotAnchor ? "el spot mayorista y el último DLR" : "el primer y último DLR";

  return (
    <div style={{ marginTop: compact ? 0 : 24, padding: compact ? "10px 12px" : "18px 22px 16px 22px", background: compact ? "transparent" : C.panel, border: compact ? "none" : `1px solid ${C.border}` }}>
      {/* Header */}
      <div style={{ display: "flex", alignItems: "baseline", gap: compact ? 10 : 14, marginBottom: compact ? 8 : 14, flexWrap: "wrap" }}>
        {!hideTitle && (
          <h2 style={{ fontSize: compact ? 12 : 14, fontWeight: 600, color: C.text, margin: 0, letterSpacing: "0.05em", textTransform: "uppercase" }}>
            Curva DLR · Detector de basis
          </h2>
        )}
        <span style={{ fontSize: compact ? 10.5 : 11.5, color: C.muted }}>
          Devaluación implícita: <strong style={{ color: C.text }}>{(dlrCurve.monthlyDevRate * 100).toFixed(2)}%</strong> mensual / <strong style={{ color: C.text }}>{(dlrCurve.annualDevRate * 100).toFixed(2)}%</strong> anual
        </span>
        {dlrCurve.hasRem && dlrCurve.remAnnualDevRate != null && (
          <span style={{ fontSize: compact ? 10.5 : 11.5, color: C.cat.amber }}>
            REM (consenso): <strong>{(dlrCurve.remAnnualDevRate * 100).toFixed(1)}%</strong> anual
          </span>
        )}
        {dlrCurve.caucionRate != null && (
          <span style={{ fontSize: compact ? 10.5 : 11.5, color: C.cat.teal }}>
            Caución: <strong>{dlrCurve.caucionRate.toFixed(1)}%</strong>
          </span>
        )}
        {(baratos.length > 0 || caros.length > 0) && (
          <span style={{ fontSize: compact ? 10.5 : 11.5, color: C.muted, marginLeft: "auto" }}>
            {baratos.length > 0 && (
              <span style={{ color: C.green, fontWeight: 600 }}>
                ● {baratos.length} barato{baratos.length > 1 ? "s" : ""}: {baratos.map((p) => p.shortTicker).join(", ")}
              </span>
            )}
            {baratos.length > 0 && caros.length > 0 && <span style={{ color: C.dim, margin: "0 8px" }}>·</span>}
            {caros.length > 0 && (
              <span style={{ color: C.red, fontWeight: 600 }}>
                ● {caros.length} caro{caros.length > 1 ? "s" : ""}: {caros.map((p) => p.shortTicker).join(", ")}
              </span>
            )}
          </span>
        )}
      </div>

      {dlrCurve.hasRem && (carosRem.length > 0 || baratosRem.length > 0) && (
        <div style={{ fontSize: compact ? 10 : 11, color: C.muted, marginBottom: compact ? 8 : 12, marginTop: compact ? -2 : -6, lineHeight: 1.4 }}>
          <span style={{ color: C.cat.amber, fontWeight: 600 }}>vs REM (consenso):</span>{" "}
          {baratosRem.length > 0 && (
            <span style={{ color: C.green, fontWeight: 600 }}>barato (mercado pricea menos deval): {baratosRem.map((p) => p.shortTicker).join(", ")}</span>
          )}
          {baratosRem.length > 0 && carosRem.length > 0 && <span style={{ color: C.dim, margin: "0 8px" }}>·</span>}
          {carosRem.length > 0 && (
            <span style={{ color: C.red, fontWeight: 600 }}>caro (pricea más deval): {carosRem.map((p) => p.shortTicker).join(", ")}</span>
          )}
        </div>
      )}

      <div style={{ display: "flex", gap: 22, alignItems: "flex-start", flexWrap: "wrap" }}>
        {/* Gráfico SVG */}
        <div style={{ flex: compact ? "1 1 100%" : "1 1 700px", minWidth: compact ? 280 : 400 }}>
          <svg viewBox={`0 0 ${SVG_W} ${SVG_H}`} style={{ width: "100%", height: "auto", maxHeight: compact ? 260 : 380 }}>
            {/* Grid horizontal */}
            {yTicks.map((tick, i) => (
              <g key={`yt-${i}`}>
                <line
                  x1={PAD_LEFT}
                  y1={yCoord(tick)}
                  x2={SVG_W - PAD_RIGHT}
                  y2={yCoord(tick)}
                  stroke={C.border}
                  strokeWidth="1"
                  strokeDasharray="2,4"
                />
                <text
                  x={PAD_LEFT - 10}
                  y={yCoord(tick) + 4}
                  textAnchor="end"
                  fontSize={compact ? 9.5 : 11}
                  fill={C.dim}
                  fontFamily="'Roboto Mono', monospace"
                >
                  ${tick.toFixed(0)}
                </text>
              </g>
            ))}

            {/* Curva teórica */}
            <path d={pathTheoric} fill="none" stroke={C.muted} strokeWidth={compact ? "1.5" : "1.8"} strokeDasharray="6,4" opacity="0.65"/>
            {/* Curva real */}
            <path d={pathReal} fill="none" stroke={C.accent} strokeWidth={compact ? "2" : "2.5"}/>
            {/* Curva REM (pronóstico de consultoras) — benchmark externo */}
            {dlrCurve.hasRem && pathRem && (
              <path d={pathRem} fill="none" stroke={C.cat.amber} strokeWidth={compact ? "1.6" : "2"} strokeDasharray="1,5" strokeLinecap="round" opacity="0.95"/>
            )}

            {/* Puntos */}
            {dlrCurve.points.map((p) => {
              const cx = xCoord(p.expiryDays);
              const cy = yCoord(p.price);
              const fill = colorForStatus(p.status);
              return (
                <g key={`pt-${p.ticker}`}>
                  <circle cx={cx} cy={cy} r={compact ? 5 : 7} fill={fill} stroke="#0a0e1a" strokeWidth={compact ? "2" : "2.5"}>
                    <title>
                      {p.ticker}: ${p.price.toFixed(2)} (teórico ${p.priceTheoric.toFixed(2)}, basis {p.basisPct >= 0 ? "+" : ""}{p.basisPct.toFixed(2)}%){p.priceRem != null ? ` · REM $${p.priceRem.toFixed(2)} (${p.basisRemPct >= 0 ? "+" : ""}${p.basisRemPct.toFixed(2)}% vs consenso)` : ""}{p.tnaImplicitaPct != null ? ` · TNA impl ${p.tnaImplicitaPct.toFixed(1)}%${p.teaImplicitaPct != null ? ` / TEA ${p.teaImplicitaPct.toFixed(1)}%` : ""}${p.vsCaucion != null ? ` (vs caución ${p.vsCaucion >= 0 ? "+" : ""}${p.vsCaucion.toFixed(1)}pp)` : ""}` : ""}
                    </title>
                  </circle>
                  <text
                    x={cx}
                    y={SVG_H - PAD_BOTTOM + (compact ? 14 : 18)}
                    textAnchor="middle"
                    fontSize={compact ? 9.5 : 11.5}
                    fill={C.muted}
                    fontFamily="'Roboto Mono', monospace"
                    fontWeight="500"
                  >
                    {p.shortTicker}
                  </text>
                  <text
                    x={cx}
                    y={SVG_H - PAD_BOTTOM + (compact ? 26 : 33)}
                    textAnchor="middle"
                    fontSize={compact ? 9 : 10.5}
                    fill={fill}
                    fontFamily="'Roboto Mono', monospace"
                    fontWeight="600"
                  >
                    {p.status === "ancla" ? "⚓" : (p.basisPct >= 0 ? "+" : "") + p.basisPct.toFixed(2) + "%"}
                  </text>
                </g>
              );
            })}

            {/* Leyenda */}
            <g transform={`translate(${PAD_LEFT + (compact ? 8 : 14)}, ${PAD_TOP + 4})`}>
              <rect x="0" y="0" width={compact ? 170 : 195} height={compact ? 48 : 56} fill="rgba(15, 21, 36, 0.85)" stroke={C.border} strokeWidth="1" rx="3"/>
              <line x1={compact ? 10 : 12} y1={compact ? 16 : 18} x2={compact ? 32 : 38} y2={compact ? 16 : 18} stroke={C.accent} strokeWidth={compact ? "2.5" : "3"}/>
              <circle cx={compact ? 21 : 25} cy={compact ? 16 : 18} r={compact ? 3.5 : 4} fill={C.accent} stroke="#0a0e1a" strokeWidth="1.5"/>
              <text x={compact ? 40 : 46} y={compact ? 19 : 22} fontSize={compact ? 10.5 : 12} fill={C.text} fontWeight="500">Precio real DLR</text>
              <line x1={compact ? 10 : 12} y1={compact ? 35 : 40} x2={compact ? 32 : 38} y2={compact ? 35 : 40} stroke={C.muted} strokeWidth={compact ? "1.8" : "2"} strokeDasharray="5,3" opacity="0.75"/>
              <text x={compact ? 40 : 46} y={compact ? 38 : 44} fontSize={compact ? 10.5 : 12} fill={C.text} fontWeight="500">Curva lisa teórica</text>
            </g>
          </svg>
        </div>

        {/* Tabla compacta de basis — OCULTA en modo compact */}
        {!compact && (
          <div style={{ flex: "0 1 460px", minWidth: 340 }}>
            <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 11.5, fontVariantNumeric: "tabular-nums" }}>
              <thead>
                <tr>
                  {[
                    { h: "DLR", a: "left", c: C.dim },
                    { h: "Real", a: "right", c: C.dim },
                    { h: "TNA impl", a: "right", c: C.cat.teal },
                    { h: "vs Cauc", a: "right", c: C.cat.teal },
                    { h: "REM", a: "right", c: C.cat.amber },
                    { h: "vs REM", a: "right", c: C.cat.amber },
                  ].map((col) => (
                    <th key={col.h} style={{ textAlign: col.a, padding: "6px 7px", color: col.c, fontSize: 9.5, letterSpacing: "0.05em", textTransform: "uppercase", fontWeight: 500, borderBottom: `1px solid ${C.border}` }}>{col.h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {dlrCurve.points.map((p) => (
                  <tr key={`tbl-${p.ticker}`} style={{ borderBottom: `1px solid ${C.border}` }}>
                    <td style={{ padding: "6px 7px", color: C.text, fontWeight: 500 }}>
                      <span style={{ color: colorForStatus(p.status), marginRight: 5, fontSize: 12 }} title="Color = basis interno (vs curva teórica)">●</span>
                      {p.shortTicker}
                    </td>
                    <td style={{ padding: "6px 7px", textAlign: "right", color: C.text, fontFamily: "'Roboto Mono', monospace" }}>{p.price.toFixed(2)}</td>
                    <td style={{ padding: "6px 7px", textAlign: "right", color: C.muted, fontFamily: "'Roboto Mono', monospace" }}>{p.tnaImplicitaPct != null ? `${p.tnaImplicitaPct.toFixed(1)}%` : "—"}</td>
                    <td style={{ padding: "6px 7px", textAlign: "right", color: p.vsCaucion != null ? colorForStatus(p.statusCaucion) : C.dim, fontWeight: 600, fontFamily: "'Roboto Mono', monospace" }}>{p.vsCaucion != null ? `${p.vsCaucion >= 0 ? "+" : ""}${p.vsCaucion.toFixed(1)}` : "—"}</td>
                    <td style={{ padding: "6px 7px", textAlign: "right", color: p.priceRem != null ? C.cat.amber : C.dim, fontFamily: "'Roboto Mono', monospace" }}>{p.priceRem != null ? p.priceRem.toFixed(0) : "—"}</td>
                    <td style={{ padding: "6px 7px", textAlign: "right", color: p.basisRemPct != null ? colorForStatus(p.statusRem) : C.dim, fontWeight: 600, fontFamily: "'Roboto Mono', monospace" }}>{p.basisRemPct != null ? `${p.basisRemPct >= 0 ? "+" : ""}${p.basisRemPct.toFixed(2)}%` : "—"}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Nota explicativa al pie — OCULTA en modo compact */}
      {!compact && (
        <div style={{ marginTop: 14, padding: "10px 14px", background: "rgba(91, 141, 214, 0.06)", borderLeft: `2px solid ${C.accentBorder}`, fontSize: 11, color: C.muted, lineHeight: 1.6 }}>
          <strong style={{ color: C.text }}>Lectura:</strong> la <strong style={{ color: C.text }}>curva lisa teórica</strong> asume devaluación mensual constante entre {anchorLabel}. Un DLR <strong style={{ color: C.green }}>verde</strong> cotiza por debajo de la curva (basis &lt; -0.3%) — hedgear con él captura alfa extra. Un DLR <strong style={{ color: C.red }}>rojo</strong> cotiza encima (basis &gt; +0.3%), se evita como hedge cuando hay alternativa. Las <strong style={{ color: C.accent }}>anclas</strong> ({hasSpotAnchor ? "spot mayorista y último DLR" : "primer y último DLR"}) definen la curva por construcción.{hasSpotAnchor ? " El spot es el valor real del dólar hoy: desde ahí se mide el basis de cada futuro, incluido el primero." : ""}
          {dlrCurve.hasRem && (
            <><br /><strong style={{ color: C.cat.amber }}>REM</strong> = el dólar que pronostican las consultoras (BCRA) para ese mes — <strong>no</strong> es el "teórico" (ese es la curva interna). <strong style={{ color: C.cat.amber }}>vs REM</strong> compara el futuro contra ese pronóstico: <strong style={{ color: C.red }}>rojo</strong> = el mercado pricea MÁS devaluación que el consenso (futuro caro), <strong style={{ color: C.green }}>verde</strong> = menos (futuro barato).</>
          )}
          {dlrCurve.hasCaucion && (
            <><br /><strong style={{ color: C.cat.teal }}>TNA impl</strong> = la tasa anual que pricea cada futuro (vs spot). <strong style={{ color: C.cat.teal }}>vs Cauc</strong> = caución − implícita (en puntos): <strong style={{ color: C.green }}>verde</strong> = la caución rinde más que la implícita → cash-and-carry a favor (futuro barato); <strong style={{ color: C.red }}>rojo</strong> = el futuro pricea más tasa que la caución (caro, lado short).</>
          )}
        </div>
      )}
    </div>
  );
}

function SinteticoDolarModule() {
  // ─── State ──────────────────────────────────────────────
  const [spotMayorista, setSpotMayorista] = useState(null);
  const { remTc: remTcCurve, remIpc: remIpcCurve } = useRemFx(); // REM para el benchmark de la curva DLR
  const caucionRateCurve = useCaucionRate(); // caución para el benchmark "vs caución"
  // Spot MEP (= "casa: bolsa" en dolarapi). Lo usamos en el simulador del
  // modal de detalle para calcular el equivalente USD de la inversion en
  // pesos al MEP de hoy (el FX al que un argentino realmente convierte
  // dolares a pesos para entrar a estos bonos).
  const [spotMep, setSpotMep] = useState(null);
  const [maturityPayments, setMaturityPayments] = useState(() => readStoredMaturityPayments());
  const [activeTab, setActiveTab] = useState("universo"); // "universo" | "cartera"
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [explainerOpen, setExplainerOpen] = useState(false);
  const [refreshing, setRefreshing] = useState(false);
  const [now, setNow] = useState(new Date());
  // Sort: default por días asc (vencimientos mas cercanos primero).
  // Click en header cambia direccion; click en otro header cambia key
  // y resetea a asc.
  const [sortKey, setSortKey] = useState("days");
  const [sortDir, setSortDir] = useState("asc");

  // Multi-horizonte y multi-estrategia (Fase 1):
  // - selectedHorizon: cuál horizonte mostramos en la columna TIR USD principal.
  //   Opciones: "30" | "60" | "90" | "180" | "vto" (default vto = lectura original).
  // - selectedStrategy: "single" | "rolling". Single = un DLR cubre todo el holding.
  //   Rolling = compramos sucesivamente el front-month y dejamos expirar (modelado
  //   simplificado en V1; Fase 2 mejora con curva DLR completa).
  // - expandedBond: ticker del bono cuyo modal de detalle esta abierto (null si nada).
  const [selectedHorizon, setSelectedHorizon] = useState("vto");
  const [selectedStrategy, setSelectedStrategy] = useState("single");
  const [expandedBond, setExpandedBond] = useState(null);

  const handleSort = (key) => {
    if (sortKey === key) {
      setSortDir((d) => (d === "asc" ? "desc" : "asc"));
    } else {
      setSortKey(key);
      setSortDir("asc");
    }
  };

  // Tick periódico para forzar re-evaluación del "today" (cambia al
  // cruzar medianoche → bonos vencidos se filtran solos del universo).
  useEffect(() => {
    const i = setInterval(() => setNow(new Date()), 5 * 60 * 1000);
    return () => clearInterval(i);
  }, []);

  // ─── Hooks de data ──────────────────────────────────────
  // - useUserPositions: para filtrar al tab "Cartera" y mostrar qty
  // - useBondPrices: precio actual de cada Lecap/Boncap (BYMA/data912/MAE)
  // - useFuturePrices: precios DLR live + settle fallback (un único hook
  //   por todo el módulo; ya tiene su propio poller adentro)
  // - useBondEmissions: pagos al vencimiento desde el worker
  //   bond-emissions-sync (Supabase, bond_emissions). El frontend ya no
  //   depende del usuario cargando el pago a mano — eso queda como
  //   override opcional en localStorage para overrides puntuales o
  //   bonos que el worker todavia no descubrio.
  const { positions } = useUserPositions();
  const bondPricesState = useBondPrices();
  const bondPrices = bondPricesState?.prices || {};
  const emissionsState = useBondEmissions();
  const bondEmissions = emissionsState?.emissions || null;

  // ─── Universo: Lecaps + Boncaps con vto futuro ─────────
  // Fuente combinada:
  //   1. BOND_REGISTRY hardcoded (cubre bonos historicos validados y
  //      sirve de fallback si Supabase falla)
  //   2. bond_emissions del worker (Supabase) — capta automaticamente
  //      bonos nuevos sin que tengamos que tocar codigo
  //   3. KNOWN_BONTAMS hardcoded — fuerza el type a "bontam" para los
  //      Bonos Duales TAMAR conocidos. El registry los marca mal como
  //      "boncap" (tasa fija) pero son tasa variable.
  // Si un ticker aparece en multiples fuentes, el orden de prioridad
  // es: KNOWN_BONTAMS > registry > emissions (solo para maturityDate).
  const universeFull = useMemo(() => {
    const today = new Date().toLocaleDateString("en-CA", {
      timeZone: "America/Argentina/Buenos_Aires",
    });
    const byTicker = new Map();
    // Step 1: registry — incluye Lecaps/Boncaps. Si el ticker esta
    // en KNOWN_BONTAMS, override del type a "bontam".
    for (const [ticker, info] of Object.entries(BOND_REGISTRY)) {
      if (!info?.maturityDate || info.maturityDate <= today) continue;
      const isBontam = !!KNOWN_BONTAMS[ticker];
      const type = isBontam ? "bontam" : info.type;
      if (type !== "lecap" && type !== "boncap" && type !== "bontam") continue;
      byTicker.set(ticker, { ticker, ...info, type });
    }
    // Step 2: bond_emissions (agrega los que no estan en registry)
    if (bondEmissions) {
      for (const [ticker, row] of bondEmissions) {
        if (!row?.maturityDate || row.maturityDate <= today) continue;
        if (row.type !== "lecap" && row.type !== "boncap") continue;
        if (!byTicker.has(ticker)) {
          byTicker.set(ticker, {
            ticker,
            type: row.type,
            maturityDate: row.maturityDate,
          });
        }
      }
    }
    // Step 3: BONTAMs que no estan en registry (raro pero posible)
    for (const [ticker, info] of Object.entries(KNOWN_BONTAMS)) {
      if (info.maturityDate <= today) continue;
      if (!byTicker.has(ticker)) {
        byTicker.set(ticker, {
          ticker,
          type: "bontam",
          maturityDate: info.maturityDate,
        });
      }
    }
    return [...byTicker.values()].sort((a, b) =>
      a.maturityDate.localeCompare(b.maturityDate)
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [now, bondEmissions]);

  // Tickers del usuario (bond_ars) — filtro del tab "Cartera".
  const carteraTickers = useMemo(() => {
    const set = new Set();
    for (const p of positions || []) {
      if (p.instrument_type !== "bond_ars") continue;
      const t = String(p.ticker || "").trim().toUpperCase();
      if (t) set.add(t);
    }
    return set;
  }, [positions]);

  const universe = useMemo(() => {
    if (activeTab === "cartera") {
      return universeFull.filter((b) => carteraTickers.has(b.ticker));
    }
    return universeFull;
  }, [universeFull, carteraTickers, activeTab]);

  // ─── DLR futures vivos: useFuturePrices con tickers del registry ─
  const dlrTickers = useMemo(() => DLR_REGISTRY.map((c) => c.ticker), []);
  const futuresState = useFuturePrices(dlrTickers);
  const futurePrices = futuresState.prices || {};

  // ─── Fetch spot mayorista + MEP (api/dolares) ─────────────────
  // Una sola llamada al endpoint, parseamos las dos casas que nos
  // interesan: mayorista (subyacente del DLR) y bolsa (= MEP, el FX
  // efectivo al que un retail argentino convierte USD a pesos y viceversa).
  const fetchSpot = useCallback(async () => {
    try {
      const resp = await fetch("/api/dolares");
      if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
      const fx = await resp.json();
      const may = Array.isArray(fx)
        ? fx.find((d) => (d.casa || "").toLowerCase() === "mayorista")
        : null;
      const mep = Array.isArray(fx)
        ? fx.find((d) => (d.casa || "").toLowerCase() === "bolsa")
        : null;
      if (may?.venta) setSpotMayorista(Number(may.venta));
      if (mep?.venta) setSpotMep(Number(mep.venta));
      setError(null);
    } catch (e) {
      setError(e.message);
    }
  }, []);

  useEffect(() => {
    setLoading(true);
    fetchSpot().finally(() => setLoading(false));
  }, [fetchSpot]);

  // Refresco automático cada 5 min (el spot mayorista no cambia muy
  // rápido; igual el DLR futuro vive con su propio poller dentro de
  // useFuturePrices, que es más agresivo en horario de mercado).
  useEffect(() => {
    const i = setInterval(() => fetchSpot(), 5 * 60 * 1000);
    return () => clearInterval(i);
  }, [fetchSpot]);

  // ─── Filas de la tabla: combinación bono ↔ futuro ──────
  // Hacemos 2 passes:
  //   Pass 1: por cada bono, calcular datos base (M, P, TIR ARS, match DLR
  //           del Single, TIR USD del Single al vto). Resultado: baseRows.
  //   Construccion: curva ARS = (days, tirArs) de todos los baseRows con
  //                 TIR ARS valida (excluye BONTAMs con premium = ruido).
  //                 Lista de futures vivos con precios live + settle.
  //   Pass 2: por cada baseRow, calcular multi-horizonte (5h × 2 modelos
  //           × 2 estrategias) y el peak. Resultado: rows.
  //
  // El useMemo retorna { rows, curveData, futuresLive } porque el modal de
  // detalle también necesita acceso a curveData y futuresLive para el
  // simulador interno.
  const rowsResult = useMemo(() => {
    if (!spotMayorista) return { rows: [], curveData: null, futuresLive: [] };
    const futuresWithDays = DLR_REGISTRY
      .map((c) => ({ ...c, expiryDays: daysToExpiry(c.maturityDate) }))
      .filter((c) => c.expiryDays > 0);

    // ─── Pass 1: cálculos base ────────────────────────────
    const baseRows = universe.map((bond) => {
      const days = daysToMaturity(bond.maturityDate);
      if (days == null || days <= 0) return null;

      // M: pago al vencimiento por 100 VN. Cinco fuentes en orden de
      // prioridad:
      //   (1) Override manual del usuario en el input local
      //   (2) bond_emissions del worker (Supabase, fresco, oficial)
      //   (3) Para BONTAMs: bontam_floor calculado (escenario peor con
      //       tasa fija). Va ANTES que el registry porque los TT26 del
      //       registry tienen un finalPayoff hardcodeado que es exacta-
      //       mente el mismo floor (verificado: diff < 0.20 entre ambos)
      //       pero el bontam_floor deja claro la semantica de "piso
      //       garantizado, el real puede ser mayor si TAMAR supera la fija".
      //   (4) BOND_REGISTRY.finalPayoff hardcoded (mismo dato que usa
      //       el CarryTradeModule — verificado contra rendimientos.co,
      //       cubre todo el universo historico aunque el worker no haya
      //       visto el bono)
      //   (5) Nada → la fila aparece con TIR vacia
      const overrideRaw = maturityPayments[bond.ticker];
      const overrideNum = (overrideRaw === "" || overrideRaw == null)
        ? null
        : Number(overrideRaw);
      const workerPago = bondEmissions?.get(bond.ticker)?.pagoVencimiento;
      const registryPago = Number.isFinite(bond.finalPayoff) ? bond.finalPayoff : null;
      const bontamInfo = KNOWN_BONTAMS[bond.ticker];
      const isBontam = bond.type === "bontam";
      const bontamFloor = (isBontam && bontamInfo)
        ? computeBontamFloor(bontamInfo.temFija, bontamInfo.fechaEmision, bond.maturityDate)
        : null;
      let maturityPayment;
      let maturityPaymentSource;
      if (Number.isFinite(overrideNum) && overrideNum > 0) {
        maturityPayment = overrideNum;
        maturityPaymentSource = "override";
      } else if (Number.isFinite(workerPago) && workerPago > 0) {
        maturityPayment = workerPago;
        maturityPaymentSource = "worker";
      } else if (isBontam && Number.isFinite(bontamFloor) && bontamFloor > 0) {
        maturityPayment = bontamFloor;
        maturityPaymentSource = "bontam_floor";
      } else if (Number.isFinite(registryPago) && registryPago > 0) {
        maturityPayment = registryPago;
        maturityPaymentSource = "registry";
      } else if (Number.isFinite(bontamFloor) && bontamFloor > 0) {
        maturityPayment = bontamFloor;
        maturityPaymentSource = "bontam_floor";
      } else {
        maturityPayment = null;
        maturityPaymentSource = null;
      }

      // P: precio actual del feed (BYMA / data912 / MAE consolidados).
      const bondPriceEntry = bondPrices[bond.ticker];
      const bondPrice = bondPriceEntry?.price != null && bondPriceEntry.price > 0
        ? Number(bondPriceEntry.price)
        : null;
      const bondPriceSource = bondPriceEntry?.source || null;

      const tirArs = computeBondTirTea(maturityPayment, bondPrice, days);
      const arsFactor = (maturityPayment && bondPrice && bondPrice > 0)
        ? maturityPayment / bondPrice
        : null;

      // Match Single: DLR con expiry >= maturity del bono, el más cercano.
      let matchFuture = futuresWithDays
        .filter((c) => c.maturityDate >= bond.maturityDate)
        .sort((a, b) => a.maturityDate.localeCompare(b.maturityDate))[0];
      let matchIsApprox = false;
      if (!matchFuture && futuresWithDays.length > 0) {
        matchFuture = futuresWithDays[futuresWithDays.length - 1];
        matchIsApprox = true;
      }

      let futurePrice = null;
      let futureSource = null;
      if (matchFuture) {
        const fp = futurePrices[matchFuture.ticker];
        if (fp?.price > 0 && !fp.error) {
          futurePrice = Number(fp.price);
          futureSource = "primary";
        } else if (fp?.settlement > 0 && !fp.error) {
          futurePrice = Number(fp.settlement);
          futureSource = "settle";
        }
      }

      // TIR USD coherente con la operativa retail real:
      // USD entra al MEP (no al mayorista, retail no puede acceder),
      // USD sale al FX del futuro (≈ mayorista al expiry por convergencia).
      const fxEntry = (Number.isFinite(spotMep) && spotMep > 0) ? spotMep : spotMayorista;
      const tirUsd = computeSyntheticUsdReturn(arsFactor, days, fxEntry, futurePrice);

      const isBontamAbovePremium = isBontam &&
        Number.isFinite(bondPrice) && Number.isFinite(maturityPayment) &&
        bondPrice > maturityPayment;

      return {
        bondTicker: bond.ticker,
        bondType: bond.type,
        bondMaturity: bond.maturityDate,
        days,
        maturityPayment,
        maturityPaymentSource,
        bondPrice,
        bondPriceSource,
        tirArs,
        arsFactor,
        matchFuture,
        matchFutureTicker: matchFuture?.ticker || null,
        matchFutureMaturity: matchFuture?.maturityDate || null,
        matchIsApprox,
        futurePrice,
        futureSource,
        tirUsd,
        isBontamAbovePremium,
        isBontam,
      };
    }).filter(Boolean);

    // ─── Construcción de la curva ARS ─────────────────────
    // Tomamos (days, tirArs) de los bonos con datos completos. Excluimos
    // BONTAMs con premium porque sus TIR no son comparables (sale del
    // floor, no del precio justo de mercado).
    const curvePoints = baseRows
      .filter((r) => Number.isFinite(r.tirArs) && Number.isFinite(r.days) && !r.isBontamAbovePremium)
      .map((r) => ({ x: r.days, y: r.tirArs }))
      .sort((a, b) => a.x - b.x);
    const curveData = curvePoints.length >= 2
      ? { xs: curvePoints.map((p) => p.x), ys: curvePoints.map((p) => p.y) }
      : null;

    // ─── Lista de futures vivos con precios para Rolling ───
    const futuresLive = futuresWithDays
      .map((f) => {
        const fp = futurePrices[f.ticker];
        let price = null;
        if (fp?.price > 0 && !fp.error) price = Number(fp.price);
        else if (fp?.settlement > 0 && !fp.error) price = Number(fp.settlement);
        return { ...f, price };
      })
      .filter((f) => Number.isFinite(f.price) && f.price > 0)
      .sort((a, b) => a.expiryDays - b.expiryDays);

    // ─── Pass 2: multi-horizonte por bono ─────────────────
    const rows = baseRows.map((r) => {
      const multiTir = computeMultiHorizonTirUsd({
        daysToBondMaturity: r.days,
        maturityPayment: r.maturityPayment,
        bondPrice: r.bondPrice,
        tirArsToday: r.tirArs,
        spot: spotMayorista,
        spotMep,
        curveData,
        futuresList: futuresLive,
      });

      // Peak para la columna principal: usa la combinación seleccionada
      // por el usuario (model = const default, strategy = selectedStrategy).
      // El peak es informativo: muestra el horizonte óptimo aunque el
      // usuario tenga otro horizonte seleccionado.
      const peakConst = findPeakTir(multiTir, selectedStrategy, "const");

      return {
        ...r,
        multiTir,
        peakConst,
      };
    });
    return { rows, curveData, futuresLive };
  }, [universe, maturityPayments, bondEmissions, bondPrices, spotMayorista, futurePrices, selectedStrategy]);
  const rows = rowsResult.rows;
  const curveData = rowsResult.curveData;
  const futuresLive = rowsResult.futuresLive;

  // Curva DLR con detector de basis (info de MERCADO, no depende del bono).
  // Se muestra en el menú principal debajo de la tabla de bonos, siempre
  // visible. El mismo objeto se pasa al modal del bono para mostrar
  // mini-badges de basis junto a cada DLR usado en el hedge.
  const dlrCurve = useMemo(
    () =>
      buildDlrCurve(
        futuresLive,
        0.003,
        Number.isFinite(spotMayorista) && spotMayorista > 0
          ? { ticker: "SPOT", shortTicker: "SPOT", price: spotMayorista, isSpot: true }
          : null,
        (remTcCurve && Object.keys(remTcCurve).length > 0)
          ? (md) => projectREMTC(md, remTcCurve, remIpcCurve || {})
          : null,
        caucionRateCurve
      ),
    [futuresLive, spotMayorista, remTcCurve, remIpcCurve, caucionRateCurve]
  );

  // Sort dinamico: aplica sortKey/sortDir sobre rows. Las filas con
  // valor null/undefined en la columna activa caen al fondo siempre
  // (para no mezclar bonos sin TIR computada entre los buenos).
  const sortedRows = useMemo(() => {
    const getVal = (r, key) => {
      switch (key) {
        case "ticker":  return r.bondTicker || null;
        case "vto":     return r.bondMaturity || null;
        case "days":    return Number.isFinite(r.days) ? r.days : null;
        case "pago":    return Number.isFinite(r.maturityPayment) ? r.maturityPayment : null;
        case "price":   return Number.isFinite(r.bondPrice) ? r.bondPrice : null;
        case "tirArs":  return Number.isFinite(r.tirArs) ? r.tirArs : null;
        case "dlr":     return r.matchFutureTicker || null;
        case "future":  return Number.isFinite(r.futurePrice) ? r.futurePrice : null;
        case "tirUsd": {
          // El sort sobre TIR USD usa el valor del horizonte/estrategia
          // seleccionados (modelo const) — coherente con lo que se muestra.
          const v = r.multiTir?.[selectedStrategy]?.const?.[selectedHorizon];
          return Number.isFinite(v) ? v : null;
        }
        case "peak": {
          const p = r.peakConst;
          return p && Number.isFinite(p.tir) ? p.tir : null;
        }
        default:        return null;
      }
    };
    const arr = [...rows];
    arr.sort((a, b) => {
      const av = getVal(a, sortKey);
      const bv = getVal(b, sortKey);
      // Nulls siempre al fondo (independiente de direccion)
      if (av == null && bv == null) return 0;
      if (av == null) return 1;
      if (bv == null) return -1;
      if (typeof av === "string") {
        return sortDir === "asc" ? av.localeCompare(bv) : bv.localeCompare(av);
      }
      return sortDir === "asc" ? av - bv : bv - av;
    });
    return arr;
  }, [rows, sortKey, sortDir, selectedStrategy, selectedHorizon]);

  // ─── Handlers ──────────────────────────────────────────
  // Override del pago al vencimiento por ticker. Si el usuario borra
  // el input (value = ""), removemos el override completamente — asi
  // el bono vuelve a usar el valor del worker. No persistimos "" como
  // override valido (eso lo distinguimos de null para mostrar el feed).
  const setMaturity = (ticker, value) => {
    const next = { ...maturityPayments };
    if (value === "" || value == null) {
      delete next[ticker];
    } else {
      next[ticker] = value;
    }
    setMaturityPayments(next);
    writeStoredMaturityPayments(next);
  };

  const handleRefresh = async () => {
    setRefreshing(true);
    try {
      await fetchSpot();
      if (typeof futuresState.refresh === "function") futuresState.refresh();
      if (typeof bondPricesState?.refresh === "function") bondPricesState.refresh();
      if (typeof emissionsState?.refetch === "function") emissionsState.refetch();
    } finally {
      setRefreshing(false);
    }
  };

  // ─── Estilos auxiliares de la tabla ────────────────────
  // Paddings reducidos (5px) para match con PositionsTable dense en
  // Dashboard. La tabla tiene 9 columnas y muchos numeros — densidad
  // alta mejora la legibilidad de los rankings.
  const th = {
    padding: "5px 12px",
    fontSize: 9,
    color: C.dim,
    letterSpacing: "0.12em",
    textTransform: "uppercase",
    fontWeight: 600,
    textAlign: "right",
    whiteSpace: "nowrap",
    userSelect: "none",
  };
  const thLeft = { ...th, textAlign: "left" };
  const td = {
    padding: "5px 12px",
    fontSize: 12,
    color: C.text,
    textAlign: "right",
    fontVariantNumeric: "tabular-nums",
    whiteSpace: "nowrap",
  };
  const tdLeft = { ...td, textAlign: "left" };
  const tdDim = { ...td, color: C.muted };

  // Renderer de header sortable: clickeable, con flecha que indica
  // direccion del sort activo. Si no se le pasa sortKey, es un header
  // de display puro (sin click).
  const SortableTh = ({ children, sortKey: key, align = "right" }) => {
    const style = align === "left" ? thLeft : th;
    const isActive = sortKey === key;
    const arrow = isActive ? (sortDir === "asc" ? "▲" : "▼") : "▼";
    return (
      <th
        onClick={() => handleSort(key)}
        style={{ ...style, cursor: "pointer" }}
        title={`Ordenar por ${typeof children === "string" ? children : "esta columna"}`}
      >
        <span style={{ display: "inline-flex", alignItems: "center", gap: 4, justifyContent: align === "right" ? "flex-end" : "flex-start" }}>
          {children}
          <span style={{
            fontSize: 7.5,
            lineHeight: 1,
            color: isActive ? C.accent : C.dim,
            opacity: isActive ? 1 : 0.25,
          }}>
            {arrow}
          </span>
        </span>
      </th>
    );
  };

  return (
    <div className="px-6 py-5 eco-fade-in" style={{ minHeight: "100%" }}>
      {/* Header */}
      <div className="flex items-start justify-between gap-6 mb-5 flex-wrap">
        <div className="flex flex-col gap-1.5">
          <span style={{ fontSize: 9, color: C.dim, letterSpacing: "0.22em", textTransform: "uppercase", fontWeight: 500 }}>
            Analizadores · BETA
          </span>
          <h1 className="eco-display" style={{ fontSize: 24, fontWeight: 700, letterSpacing: "-0.01em", color: C.text, lineHeight: 1.1, margin: 0 }}>
            Sintético Dólar
          </h1>
        </div>
        <div className="flex items-center gap-3 flex-wrap">
          <Metric label="Spot mayorista" value={spotMayorista ? `$${fmtARS(spotMayorista)}` : "—"} color={C.text} />
          <button
            onClick={handleRefresh}
            disabled={refreshing || loading}
            style={{
              padding: "6px 14px",
              fontSize: 10.5,
              fontWeight: 500,
              letterSpacing: "0.10em",
              textTransform: "uppercase",
              background: "transparent",
              border: `1px solid ${C.border}`,
              color: refreshing ? C.dim : C.text,
              cursor: (refreshing || loading) ? "wait" : "pointer",
              transition: "all 120ms ease",
            }}
          >
            {refreshing ? "Actualizando..." : "Actualizar"}
          </button>
        </div>
      </div>

      {/* Tabs: Universo / Cartera. Filtran qué bonos aparecen en la tabla.
          La lógica del cómputo es la misma, solo cambia el filtro. */}
      <div className="flex gap-1 mb-4" style={{ borderBottom: `1px solid ${C.border}` }}>
        {[
          { id: "universo", label: "Universo", count: universeFull.length },
          { id: "cartera", label: "Cartera", count: universeFull.filter((b) => carteraTickers.has(b.ticker)).length },
        ].map((tab) => {
          const isActive = activeTab === tab.id;
          return (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              style={{
                padding: "8px 16px",
                fontSize: 11.5,
                fontWeight: isActive ? 600 : 500,
                letterSpacing: "0.05em",
                color: isActive ? C.text : C.muted,
                background: "transparent",
                border: "none",
                borderBottom: `2px solid ${isActive ? C.accent : "transparent"}`,
                cursor: "pointer",
                transition: "all 120ms ease",
                marginBottom: -1,
              }}
            >
              {tab.label}
              <span style={{ color: C.dim, marginLeft: 6, fontSize: 10.5, fontVariantNumeric: "tabular-nums" }}>
                ({tab.count})
              </span>
            </button>
          );
        })}
      </div>

      {/* Explainer (collapsable) — Manual extendido para cualquier perfil.
          Diseñado para que alguien sin experiencia en finanzas/tecnología
          pueda entender la pantalla y tomar una decisión informada. */}
      <div
        className="mb-4"
        style={{
          backgroundColor: "rgba(56, 189, 248, 0.04)",
          borderLeft: `2px solid ${C.accent}`,
        }}
      >
        <button
          onClick={() => setExplainerOpen((v) => !v)}
          style={{
            width: "100%",
            display: "flex",
            alignItems: "flex-start",
            gap: 8,
            padding: "12px 16px",
            background: "transparent",
            border: "none",
            cursor: "pointer",
            textAlign: "left",
          }}
        >
          <Info size={13} color={C.accent} strokeWidth={1.8} style={{ flexShrink: 0, marginTop: 2 }} />
          <span style={{ fontSize: 11.5, color: C.text, lineHeight: 1.55, fontWeight: 500, flex: 1 }}>
            ¿Qué es esta pantalla y cómo se usa? <span style={{ color: C.dim, fontWeight: 400 }}>· Manual completo (clickeá para abrir)</span>
          </span>
          <ChevronDown
            size={14}
            color={C.muted}
            style={{
              marginTop: 2,
              transform: explainerOpen ? "rotate(180deg)" : "none",
              transition: "transform 150ms ease",
            }}
          />
        </button>
        {explainerOpen && (
          <div style={{ padding: "0 16px 18px 38px", fontSize: 12, color: C.muted, lineHeight: 1.7 }}>

            {/* ── SECCIÓN 1: ¿Qué es esto en una frase? ── */}
            <h4 style={{ color: C.text, fontSize: 12.5, fontWeight: 600, margin: "10px 0 6px 0", letterSpacing: "0.02em" }}>
              ¿Qué hace esta pantalla, en una frase?
            </h4>
            <p style={{ margin: "0 0 10px 0" }}>
              Es un <strong style={{ color: C.text }}>comparador</strong> que te dice: si tenés dólares hoy, qué armado en pesos te puede dar más dólares dentro de un tiempo, cubriéndote del riesgo de devaluación.
            </p>

            {/* ── SECCIÓN 2: El problema concreto ── */}
            <h4 style={{ color: C.text, fontSize: 12.5, fontWeight: 600, margin: "16px 0 6px 0", letterSpacing: "0.02em" }}>
              El problema que resuelve
            </h4>
            <p style={{ margin: "0 0 6px 0" }}>
              Imaginate que tenés USD 1.000 guardados. Tus opciones son:
            </p>
            <ul style={{ margin: "0 0 10px 0", paddingLeft: 20 }}>
              <li>Dejarlos quietos: 0% de rendimiento.</li>
              <li>Plazo fijo en dólares: 2-4% al año (bajo).</li>
              <li>Bonos argentinos en dólares (AL30, GD30): rinden más pero arriesgás default.</li>
              <li><strong style={{ color: C.text }}>El truco de esta pantalla:</strong> pasarlos a pesos, comprar un bono en pesos que rinde alto (~25-30% anual), Y al mismo tiempo "asegurar" el tipo de cambio al que volvés a dólares comprando un contrato de dólar futuro.</li>
            </ul>
            <p style={{ margin: "0 0 10px 0" }}>
              Eso último se llama <strong style={{ color: C.text }}>sintético dólar</strong>. Capturás la tasa alta en pesos pero te cubrís de la devaluación con el futuro. La pregunta clave: <em>¿qué combinación bono + futuro me conviene más hoy?</em> Eso es lo que esta tabla responde.
            </p>

            {/* ── SECCIÓN 3: La tabla columna por columna ── */}
            <h4 style={{ color: C.text, fontSize: 12.5, fontWeight: 600, margin: "16px 0 6px 0", letterSpacing: "0.02em" }}>
              Cómo leer la tabla, columna por columna
            </h4>
            <ul style={{ margin: "0 0 10px 0", paddingLeft: 20 }}>
              <li><strong style={{ color: C.text }}>Bono:</strong> el nombre del bono. Hay tres tipos: <em>LECAP</em> (corto, hasta 1 año), <em>BONCAP</em> (más largo), y <em>DUAL</em> (caso especial — abajo lo explico).</li>
              <li><strong style={{ color: C.text }}>Vto:</strong> la fecha en que el bono devuelve la plata.</li>
              <li><strong style={{ color: C.text }}>Días:</strong> cuántos días faltan a esa fecha.</li>
              <li><strong style={{ color: C.text }}>Vto $:</strong> cuántos pesos te paga el bono al vencimiento por cada $100 invertidos. Si dice "145,29" significa que recibís $145,29 por cada $100 nominales al final.</li>
              <li><strong style={{ color: C.text }}>P actual:</strong> el precio al que cotiza el bono HOY. Si dice "141,60" significa que hoy comprás $100 nominales por $141,60. La diferencia entre "P actual" y "Vto $" es tu ganancia bruta en pesos.</li>
              <li><strong style={{ color: C.text }}>TIR ARS:</strong> rendimiento anualizado del bono en pesos. "Este bono rinde 27% por año en pesos si lo aguantás hasta el final".</li>
              <li><strong style={{ color: C.text }}>DLR match:</strong> el contrato de dólar futuro que se usa para hedgear. Si tiene un <span style={{ color: C.cat.violet }}>⚠</span> amarillo, significa que la cobertura no es perfecta (el futuro vence antes que el bono).</li>
              <li><strong style={{ color: C.text }}>F (futuro):</strong> precio del dólar futuro hoy. Si dice "1.432" significa que el mercado vende un dólar para esa fecha a $1.432.</li>
              <li><strong style={{ color: C.text }}>TIR USD:</strong> <em>la columna más importante.</em> Cuánto rinde el armado completo en dólares anualizado, al horizonte que vos elegiste. <span style={{ color: C.green }}>Verde positivo</span> = ganás dólares. <span style={{ color: C.red }}>Rojo negativo</span> = perdés.</li>
              <li><strong style={{ color: C.text }}>Peak:</strong> el horizonte óptimo para ese bono. Te dice "este rinde mejor si lo aguantás 90 días" o "hasta el vto". Útil porque a veces no conviene esperar al final.</li>
            </ul>

            {/* ── SECCIÓN 4: Los dos selectores ── */}
            <h4 style={{ color: C.text, fontSize: 12.5, fontWeight: 600, margin: "16px 0 6px 0", letterSpacing: "0.02em" }}>
              Los dos selectores arriba: Horizonte y Estrategia
            </h4>
            <p style={{ margin: "0 0 6px 0" }}>
              <strong style={{ color: C.text }}>Horizonte = ¿cuánto tiempo voy a mantener el sintético?</strong> 30/60/90/180 días o "Vto" (hasta el vencimiento del bono). A veces no conviene esperar al final: un bono puede rendir mejor en sus primeros 60 días que aguantado un año entero.
            </p>
            <p style={{ margin: "0 0 6px 0" }}>
              <strong style={{ color: C.text }}>Estrategia = ¿cómo me cubro del dólar?</strong>
            </p>
            <ul style={{ margin: "0 0 8px 0", paddingLeft: 20 }}>
              <li><em>Single hedge:</em> comprás UN solo contrato de futuro que cubra todo el período. Versión simple, una sola operación.</li>
              <li><em>Rolling mensual:</em> comprás el futuro del mes que viene; cuando expira, comprás el del mes siguiente; así hasta cubrir todo. Más activo (una operación por mes) pero suele capturar más ganancia.</li>
            </ul>
            <p style={{ margin: "0 0 10px 0" }}>
              <strong style={{ color: C.text }}>¿Cuándo gana cada una?</strong> Si la curva de futuros está empinada hacia adelante (que es lo normal en Argentina), <strong style={{ color: C.green }}>Rolling suele ganar fácil</strong> porque los futuros cercanos son más baratos. Si la curva está plana, son equivalentes.
            </p>

            {/* ── SECCIÓN 5: El modal de detalle ── */}
            <h4 style={{ color: C.text, fontSize: 12.5, fontWeight: 600, margin: "16px 0 6px 0", letterSpacing: "0.02em" }}>
              Click en un bono → modal de detalle + simulador
            </h4>
            <p style={{ margin: "0 0 6px 0" }}>
              Al hacer click en cualquier fila, se abre una ventana con todo el desglose del bono:
            </p>
            <ul style={{ margin: "0 0 8px 0", paddingLeft: 20 }}>
              <li><strong style={{ color: C.text }}>Tabla Single hedge:</strong> una fila por horizonte, dos columnas de TIR (modelo Const y modelo Curva — abajo los explico), y la columna "DLR usado" que muestra cuál contrato se compra.</li>
              <li><strong style={{ color: C.text }}>Tabla Rolling mensual:</strong> idem, más una columna extra "Camino de DLRs" que muestra exactamente qué contratos comprás y cuántos días cada uno. Ej: <span style={{ color: C.text, fontFamily: "'Roboto Mono', monospace" }}>MAY26 (8d) → JUN26 (32d) → JUL26 (30d)</span>.</li>
              <li><strong style={{ color: C.text }}>Simulador con tu monto:</strong> ingresás cuántos USD vas a invertir y la pantalla te muestra <em>paso a paso</em>: cuántos pesos te dan al spot, cuántos VN del bono comprás, qué futuros tomás, cuánto recibís al final, y la ganancia/pérdida en USD. Cambiás el monto, estrategia, horizonte y modelo y recalcula al instante.</li>
            </ul>
            <p style={{ margin: "0 0 6px 0" }}>
              <strong style={{ color: C.text }}>Los dos modelos del detalle:</strong>
            </p>
            <ul style={{ margin: "0 0 10px 0", paddingLeft: 20 }}>
              <li><em>Const (constante):</em> asume que las tasas de pesos se quedan como están hoy. Escenario base, conservador.</li>
              <li><em>Curva:</em> asume que las tasas se van a comportar como el mercado las descuenta hoy. Más realista. <strong style={{ color: C.text }}>Si los dos coinciden, el cálculo es robusto. Si difieren mucho, estás expuesto a movimientos de tasas.</strong></li>
            </ul>

            {/* ── SECCIÓN 6: Cómo decidir ── */}
            <h4 style={{ color: C.text, fontSize: 12.5, fontWeight: 600, margin: "16px 0 6px 0", letterSpacing: "0.02em" }}>
              Cómo tomar una decisión, paso a paso
            </h4>
            <ol style={{ margin: "0 0 10px 0", paddingLeft: 22 }}>
              <li style={{ marginBottom: 4 }}>Ordená la tabla por <strong style={{ color: C.text }}>Peak</strong> descendente (click en el header). Te aparecen los bonos con mayor potencial arriba.</li>
              <li style={{ marginBottom: 4 }}>Mirá si los top están en <span style={{ color: C.green }}>verde positivo</span>. Si todos están negativos, hoy no es buen día para sintéticos — guardá los dólares.</li>
              <li style={{ marginBottom: 4 }}>Elegí un bono con buen Peak Y horizonte cómodo para vos. Si necesitás la plata en 60 días, no agarres uno con peak "vto" a 300 días.</li>
              <li style={{ marginBottom: 4 }}>Click en el bono → abre el modal. Mirá si Rolling supera a Single por más de 1-2 puntos. Si sí, andá por Rolling; si están parecidos, agarrá Single (menos operaciones).</li>
              <li style={{ marginBottom: 4 }}>Usá el <strong style={{ color: C.text }}>simulador</strong> con tu monto real para ver cuánto te queda al final. Si el número absoluto te cierra, anotá los contratos del "camino DLRs" y andá a comprar.</li>
            </ol>

            {/* ── SECCIÓN 7: DUAL y ⚠ ── */}
            <h4 style={{ color: C.text, fontSize: 12.5, fontWeight: 600, margin: "16px 0 6px 0", letterSpacing: "0.02em" }}>
              Casos especiales: <span style={{ color: C.cat.yellow }}>DUAL</span> y <span style={{ color: C.cat.violet }}>⚠</span>
            </h4>
            <p style={{ margin: "0 0 6px 0" }}>
              <strong style={{ color: C.cat.yellow }}>DUAL:</strong> algunos bonos están marcados con badge amarillo. Son bonos especiales que pagan un <em>piso garantizado</em> pero pueden pagar más si la tasa TAMAR sube. Como TAMAR no se puede predecir, mostramos solo el <strong style={{ color: C.text }}>peor caso</strong>. Si la TIR USD del peor caso ya te cierra, está perfecto. Si no, podés ignorarlos. <strong style={{ color: C.text }}>Cuando el precio del bono cotiza arriba del piso</strong>, las TIRs aparecen en gris atenuado — el mercado descuenta que vas a cobrar más que el piso, pero no podemos cuantificarlo todavía.
            </p>
            <p style={{ margin: "0 0 10px 0" }}>
              <strong style={{ color: C.cat.violet }}>⚠ Triángulo violeta:</strong> significa cobertura aproximada. El futuro usado vence antes que el bono o que el horizonte, así que los últimos días del armado quedan expuestos al spot del momento. Si querés sintéticos 100% cubiertos, evitá esas filas.
            </p>

            {/* ── SECCIÓN 8: Limitaciones honestas ── */}
            <h4 style={{ color: C.text, fontSize: 12.5, fontWeight: 600, margin: "16px 0 6px 0", letterSpacing: "0.02em" }}>
              Limitaciones honestas (qué NO te dice esta pantalla)
            </h4>
            <ul style={{ margin: "0 0 10px 0", paddingLeft: 20 }}>
              <li><strong style={{ color: C.text }}>No predice el dólar.</strong> Te muestra el rendimiento bajo la curva de futuros ACTUAL. Si el dólar pega un salto sorpresivo o cambia la política, los números se mueven.</li>
              <li><strong style={{ color: C.text }}>No incluye comisiones del broker.</strong> Restá ~0.5-1% al año por costos operativos reales.</li>
              <li><strong style={{ color: C.text }}>No incluye impuestos.</strong> Las ganancias por bonos pueden estar gravadas según el régimen tuyo.</li>
              <li><strong style={{ color: C.text }}>Rolling v1 asume que los DLR no se mueven entre rolleos.</strong> Es una primera aproximación; en la próxima versión vamos a modelar el riesgo de basis real.</li>
              <li><strong style={{ color: C.text }}>Para BONTAMs cotizando con prima</strong>, las TIRs mostradas son el peor caso. El real probablemente sea mejor.</li>
            </ul>

            {/* ── SECCIÓN 9: Detalles técnicos (al final) ── */}
            <h4 style={{ color: C.text, fontSize: 12.5, fontWeight: 600, margin: "16px 0 6px 0", letterSpacing: "0.02em" }}>
              Detalles técnicos (para quienes quieran)
            </h4>
            <p style={{ margin: "0 0 6px 0" }}>
              <strong style={{ color: C.text }}>Fórmula básica del sintético al vencimiento:</strong>
            </p>
            <pre style={{ margin: "0 0 8px 0", fontFamily: "'Roboto Mono', monospace", fontSize: 11, color: C.text, background: "rgba(255,255,255,0.03)", padding: "8px 10px", overflowX: "auto" }}>
{`ARS_factor = M / P             (ganancia bruta en pesos)
USD_factor = ARS_factor × Spot / F
TIR_USD    = USD_factor^(365/T) − 1`}
            </pre>
            <p style={{ margin: "0 0 6px 0" }}>
              donde M es el pago al vencimiento, P el precio actual, T los días al vto, Spot el dólar mayorista de hoy, y F el precio del futuro DLR.
            </p>
            <p style={{ margin: "0 0 6px 0" }}>
              <strong style={{ color: C.text }}>Para horizontes intermedios (H &lt; T):</strong> precio del bono al día H se estima como <span style={{ fontFamily: "'Roboto Mono', monospace" }}>M / (1+TIR_ARS)^((T-H)/365)</span>. El modelo "Const" usa la TIR ARS de hoy; el modelo "Curva" interpola la TIR ARS de los bonos con (T-H) días restantes.
            </p>
            <p style={{ margin: "0 0 8px 0" }}>
              <strong style={{ color: C.text }}>Para Rolling:</strong> el FX efectivo se aproxima como promedio ponderado por días de los precios actuales de cada DLR del camino. Hipótesis simplificadora de v1 — se refina en Fase 2.
            </p>
            <p style={{ margin: 0 }}>
              <strong style={{ color: C.text }}>De dónde sale M:</strong> en cascada — primero override manual si lo cargás, después datos del Tesoro actualizados Mi/Ju, después catálogo verificado interno, después el piso calculado para BONTAMs.
            </p>
          </div>
        )}
      </div>

      {error && (
        <div style={{ padding: "10px 14px", background: "rgba(248, 113, 113, 0.08)", border: `1px solid ${C.red}`, color: C.red, fontSize: 11.5, marginBottom: 14 }}>
          Error cargando spot: {error}
        </div>
      )}

      {/* Barra de controles multi-horizonte / multi-estrategia (Fase 1).
          Compacta, alineada a la izquierda. Cada grupo tiene su label dim,
          y los botones son pill-style con borde accent cuando activo. */}
      <div className="mb-3" style={{ display: "flex", gap: 24, flexWrap: "wrap", alignItems: "center", padding: "10px 0" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
          <span style={{ fontSize: 9.5, color: C.dim, letterSpacing: "0.12em", textTransform: "uppercase", fontWeight: 600 }}>
            Horizonte
          </span>
          <div style={{ display: "flex", gap: 2 }}>
            {[
              { id: "30", label: "30d" },
              { id: "60", label: "60d" },
              { id: "90", label: "90d" },
              { id: "180", label: "180d" },
              { id: "vto", label: "Vto" },
            ].map((opt) => {
              const isActive = selectedHorizon === opt.id;
              return (
                <button
                  key={opt.id}
                  onClick={() => setSelectedHorizon(opt.id)}
                  style={{
                    padding: "4px 10px",
                    fontSize: 10.5,
                    fontWeight: isActive ? 600 : 500,
                    letterSpacing: "0.05em",
                    color: isActive ? C.text : C.muted,
                    background: isActive ? "rgba(91, 141, 214, 0.08)" : "transparent",
                    border: `1px solid ${isActive ? C.accentBorder : C.border}`,
                    cursor: "pointer",
                    transition: "all 120ms ease",
                  }}
                >
                  {opt.label}
                </button>
              );
            })}
          </div>
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
          <span style={{ fontSize: 9.5, color: C.dim, letterSpacing: "0.12em", textTransform: "uppercase", fontWeight: 600 }}>
            Estrategia
          </span>
          <div style={{ display: "flex", gap: 2 }}>
            {[
              { id: "single", label: "Single hedge", tooltip: "Un solo DLR cubre todo el holding period (lo que veias antes)." },
              { id: "rolling", label: "Rolling mensual", tooltip: "Compramos sucesivamente el DLR del mes que viene; al expirar, rolleamos al siguiente. FX efectivo = promedio ponderado de precios actuales." },
            ].map((opt) => {
              const isActive = selectedStrategy === opt.id;
              return (
                <button
                  key={opt.id}
                  onClick={() => setSelectedStrategy(opt.id)}
                  title={opt.tooltip}
                  style={{
                    padding: "4px 12px",
                    fontSize: 10.5,
                    fontWeight: isActive ? 600 : 500,
                    letterSpacing: "0.05em",
                    color: isActive ? C.text : C.muted,
                    background: isActive ? "rgba(91, 141, 214, 0.08)" : "transparent",
                    border: `1px solid ${isActive ? C.accentBorder : C.border}`,
                    cursor: "pointer",
                    transition: "all 120ms ease",
                  }}
                >
                  {opt.label}
                </button>
              );
            })}
          </div>
        </div>
        <div style={{ fontSize: 10, color: C.dim, fontStyle: "italic", letterSpacing: "0.03em" }}>
          Click en un bono → detalle con todos los horizontes y modelos.
        </div>
      </div>

      {/* Mi cobertura · escenarios (solo en la tab Cartera = posicion real) */}
      {activeTab === "cartera" && (
        <div style={{ marginBottom: 16 }}>
          <div style={{ fontSize: 13, fontWeight: 600, color: C.text, marginBottom: 2 }}>
            Mi cobertura · escenarios de dólar
          </div>
          <div style={{ fontSize: 11, color: C.muted, marginBottom: 8 }}>
            Valor en USD de tus bonos en pesos (el carry) + tus futuros DLR (la cobertura) bajo distintos saltos del dólar.
          </div>
          <div style={{ background: C.panel, border: `1px solid ${C.border}` }}>
            <HedgeScenarioWidget full />
          </div>
        </div>
      )}

      {/* Tabla */}
      <div style={{ backgroundColor: C.panel, border: `1px solid ${C.border}`, overflow: "auto" }}>
        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12 }}>
          <thead>
            <tr style={{ borderBottom: `1px solid ${C.border}`, background: "rgba(255,255,255,0.02)" }}>
              <SortableTh sortKey="ticker" align="left">Bono</SortableTh>
              <SortableTh sortKey="vto" align="left">Vto</SortableTh>
              <SortableTh sortKey="days">Días</SortableTh>
              <SortableTh sortKey="pago">Vto $ (por 100 VN)</SortableTh>
              <SortableTh sortKey="price">P actual</SortableTh>
              <SortableTh sortKey="tirArs">TIR ARS</SortableTh>
              <SortableTh sortKey="dlr" align="left">DLR match</SortableTh>
              <SortableTh sortKey="future">F (futuro)</SortableTh>
              <SortableTh sortKey="tirUsd">
                TIR USD {selectedHorizon === "vto" ? "vto" : `${selectedHorizon}d`}
              </SortableTh>
              <SortableTh sortKey="peak">Peak</SortableTh>
            </tr>
          </thead>
          <tbody>
            {sortedRows.length === 0 && (
              <tr>
                <td colSpan={10} style={{ padding: 32, textAlign: "center", color: C.dim, fontSize: 12 }}>
                  {loading
                    ? "Cargando..."
                    : activeTab === "cartera"
                    ? "No hay Lecaps / Boncaps en tus posiciones."
                    : "No hay Lecaps / Boncaps con vto futuro en el registry"}
                </td>
              </tr>
            )}
            {sortedRows.map((row) => {
              // matRaw: valor a mostrar en el input. Sale de la MISMA
              // cascada que ya resolvio el calculo (override > worker >
              // registry > bontam_floor). Si la cascada no resuelve, el
              // input queda vacio — no usamos placeholder con un numero
              // porque el usuario lo lee como dato cargado (bug viejo:
              // mostraba "115,5" mientras el calculo usaba el M real del
              // registry, dando la impresion de inconsistencia).
              const override = maturityPayments[row.bondTicker];
              const source = row.maturityPaymentSource;
              const isManual = source === "override";
              const isPrefilled = !isManual && source != null;
              let matRaw;
              if (isManual) {
                matRaw = override; // tal cual lo escribio el usuario
              } else if (isPrefilled && Number.isFinite(row.maturityPayment)) {
                matRaw = row.maturityPayment.toFixed(2);
              } else {
                matRaw = ""; // sin dato → input vacio
              }
              let inputTitle;
              if (isManual) {
                inputTitle = "Override manual. Borrá el valor para volver al valor automático.";
              } else if (source === "worker") {
                inputTitle = "Pago al vto. del catálogo del Tesoro (actualizado Mi/Ju). Editá para anular con un valor manual.";
              } else if (source === "registry") {
                inputTitle = "Pago al vto. del catálogo verificado interno. Editá para anular con un valor manual.";
              } else if (source === "bontam_floor") {
                inputTitle = "Piso garantizado (escenario tasa fija) — el pago real puede ser mayor si TAMAR supera la fija. Editá para forzar un valor.";
              } else {
                inputTitle = "Sin dato — la TIR queda en blanco hasta que cargues el pago al vto. (sale del prospecto del bono).";
              }
              return (
                <tr
                  key={row.bondTicker}
                  onClick={(e) => {
                    // Evitar abrir el modal cuando el click viene del input
                    // o de un span con tooltip help (los maneja el propio elem).
                    const tag = (e.target?.tagName || "").toLowerCase();
                    if (tag === "input" || tag === "button") return;
                    setExpandedBond(row.bondTicker);
                  }}
                  style={{
                    borderBottom: `1px solid ${C.border}`,
                    cursor: "pointer",
                    transition: "background-color 120ms ease",
                  }}
                  onMouseEnter={(e) => { e.currentTarget.style.backgroundColor = "rgba(255,255,255,0.02)"; }}
                  onMouseLeave={(e) => { e.currentTarget.style.backgroundColor = "transparent"; }}
                >
                  <td style={tdLeft}>
                    <span style={{ fontWeight: 600 }}>{row.bondTicker}</span>
                    {row.bondType === "bontam" ? (
                      <span
                        style={{
                          color: C.cat?.yellow || "#fbbf24",
                          marginLeft: 6,
                          fontSize: 10,
                          textTransform: "uppercase",
                          letterSpacing: "0.05em",
                          fontWeight: 600,
                          cursor: "help",
                        }}
                        title="Bono Dual TAMAR — paga al vto el MAX entre tasa fija capitalizada y TAMAR mensual acumulada. El 'Vto $' mostrado es el PISO (escenario tasa fija). Si TAMAR queda arriba del piso, cobrás más; si no, exactamente eso. La TIR USD que ves es la garantizada en el peor caso."
                      >
                        DUAL
                      </span>
                    ) : (
                      <span style={{ color: C.dim, marginLeft: 6, fontSize: 10, textTransform: "uppercase", letterSpacing: "0.05em" }}>
                        {row.bondType}
                      </span>
                    )}
                  </td>
                  <td style={tdLeft}>{row.bondMaturity}</td>
                  <td style={tdDim}>{row.days}</td>
                  <td style={td}>
                    <MoneyInput
                      value={matRaw}
                      onChange={(v) => setMaturity(row.bondTicker, v)}
                      placeholder=""
                      decimals={3}
                      bare
                      style={{
                        width: 78,
                        padding: "3px 6px",
                        background: "transparent",
                        border: `1px solid ${isPrefilled ? C.accentBorder : C.border}`,
                        color: isPrefilled ? C.dim : C.text,
                        fontSize: 11.5,
                        textAlign: "right",
                        fontVariantNumeric: "tabular-nums",
                        fontFamily: "'Roboto Mono', monospace",
                      }}
                    />
                  </td>
                  <td style={td}>
                    {row.bondPrice != null ? (
                      <>
                        {fmtNumber(row.bondPrice, { maxDecimals: 3, minDecimals: 2, smartDecimals: true })}
                        {row.bondPriceSource && (
                          <span style={{ color: C.dim, fontSize: 9.5, marginLeft: 5, letterSpacing: "0.05em", textTransform: "uppercase" }}>
                            {row.bondPriceSource}
                          </span>
                        )}
                      </>
                    ) : <span style={{ color: C.dim }}>—</span>}
                  </td>
                  <td style={td}>
                    {row.tirArs != null ? (
                      <span
                        style={{ color: row.isBontamAbovePremium ? C.muted : C.text, cursor: row.isBontamAbovePremium ? "help" : "default" }}
                        title={row.isBontamAbovePremium
                          ? "El mercado paga prima sobre el piso de tasa fija (descuenta TAMAR > fija). La TIR mostrada es la del peor caso — el bono probablemente pague más al vencimiento."
                          : undefined}
                      >
                        {fmtPct(row.tirArs * 100)}
                      </span>
                    ) : <span style={{ color: C.dim }}>—</span>}
                  </td>
                  <td
                    style={{
                      ...tdLeft,
                      cursor: row.matchIsApprox ? "help" : "default",
                    }}
                    title={row.matchIsApprox
                      ? `Sin DLR que cubra hasta el vto del bono (${row.bondMaturity}). El último futuro disponible expira antes — la TIR USD que ves es aproximada: estás hedgeado solo hasta ese expiry, el resto va al spot de mercado.`
                      : (row.matchFutureMaturity
                          ? `DLR ${row.matchFutureTicker} expira ${row.matchFutureMaturity} — cubre hasta el vto del bono.`
                          : undefined)}
                  >
                    {row.matchFutureTicker ? (
                      <span>
                        <span style={{ fontWeight: 500 }}>{row.matchFutureTicker}</span>
                        {row.matchIsApprox && (
                          <span style={{ color: C.cat.violet, marginLeft: 4, fontSize: 10 }}>
                            ⚠
                          </span>
                        )}
                      </span>
                    ) : <span style={{ color: C.dim }}>—</span>}
                  </td>
                  <td style={td}>
                    {row.futurePrice ? (
                      <>
                        {fmtARS(row.futurePrice)}
                        <span style={{ color: C.dim, fontSize: 9.5, marginLeft: 5, letterSpacing: "0.05em", textTransform: "uppercase" }}>
                          {row.futureSource}
                        </span>
                      </>
                    ) : <span style={{ color: C.dim }}>—</span>}
                  </td>
                  <td style={{ ...td, fontWeight: 600 }}>
                    {(() => {
                      // TIR USD a mostrar: del modelo "const" (default), con
                      // strategy y horizonte seleccionados. El panel de detalle
                      // muestra ambos modelos (const y curve).
                      const tirHere = row.multiTir?.[selectedStrategy]?.const?.[selectedHorizon];
                      if (!Number.isFinite(tirHere)) {
                        return <span style={{ color: C.dim, fontWeight: 400 }}>—</span>;
                      }
                      const formatted = formatTeaWithCap(tirHere);
                      if (row.isBontamAbovePremium) {
                        return (
                          <span
                            style={{ color: C.muted, fontWeight: 500, cursor: "help" }}
                            title="El mercado paga prima sobre el piso de tasa fija. La TIR USD mostrada es la del peor caso — el sintético real probablemente rinda más si TAMAR queda arriba."
                          >
                            {formatted.text}
                          </span>
                        );
                      }
                      if (formatted.isCapped) {
                        return (
                          <span
                            style={{ color: tirHere > 0 ? C.green : C.red, cursor: "help" }}
                            title={`TEA real ≈ ${formatted.raw.toFixed(2)}%. Capeada visualmente: al anualizar un retorno corto da números irrealizables (necesitarías rolear ese ritmo todo el año). Mirá el % del período en el detalle del bono para la decisión real.`}
                          >
                            {formatted.text}
                          </span>
                        );
                      }
                      return (
                        <span style={{ color: tirHere > 0 ? C.green : C.red }}>
                          {formatted.text}
                        </span>
                      );
                    })()}
                  </td>
                  <td style={{ ...td, color: C.muted }}>
                    {(() => {
                      // Peak: horizonte óptimo y TIR pico del bono bajo la
                      // estrategia seleccionada (modelo const). Lectura tipo
                      // "este bono rinde mejor en 90d que aguantado al vto".
                      // Mostramos ADEMÁS el % absoluto del período para que el
                      // usuario entienda que TEA grande con horizonte chico
                      // ≠ más USD reales. Ej: T30A7 Rolling Peak 30d +31.90%
                      // suena más jugoso que Vto +14.03%, pero en USD absolutos
                      // aguantar al vto da MÁS dinero.
                      const peak = row.peakConst;
                      if (!peak || !Number.isFinite(peak.tir)) {
                        return <span style={{ color: C.dim }}>—</span>;
                      }
                      const isCurrentBest = peak.horizon === selectedHorizon;
                      const horizonLabel = peak.horizon === "vto" ? "vto" : `${peak.horizon}d`;
                      const peakFormatted = formatTeaWithCap(peak.tir);
                      // % absoluto del período del peak: (1 + tea)^(días/365) - 1
                      // OJO: usamos efDays = min(horizonteSolicitado, díasAlVto).
                      // Si el horizonte solicitado supera el vto del bono (ej:
                      // Peak "30d" en S29Y6 que vence a 4d), el bono ya está
                      // vencido, así que efDays = 4. Antes calculábamos con
                      // peakDays directo y daba % período irrealmente altos.
                      const peakHorizonReq = peak.horizon === "vto" ? row.days : Number(peak.horizon);
                      const effDays = (Number.isFinite(peakHorizonReq) && Number.isFinite(row.days))
                        ? Math.min(peakHorizonReq, row.days)
                        : null;
                      const pctPeriod = (Number.isFinite(effDays) && effDays > 0 && Number.isFinite(peak.tir))
                        ? Math.pow(1 + peak.tir, effDays / 365) - 1
                        : null;
                      const tooltip = isCurrentBest
                        ? `El horizonte seleccionado YA es el pico para este bono.`
                        : `Mejor TEA anualizada saliendo a ${horizonLabel}. OJO: la TEA alta de un horizonte corto NO significa más USD absolutos. Mirá el detalle del bono para comparar resultados realmente comparables.`;
                      return (
                        <span title={tooltip} style={{ cursor: "help" }}>
                          <span style={{ fontSize: 10.5, color: C.dim, marginRight: 5, letterSpacing: "0.04em" }}>
                            {horizonLabel}
                          </span>
                          <span style={{
                            color: row.isBontamAbovePremium ? C.muted : (peak.tir > 0 ? C.green : C.red),
                            fontWeight: 600,
                          }}>
                            {peakFormatted.text}
                          </span>
                          {pctPeriod != null && !row.isBontamAbovePremium && (
                            <span style={{
                              color: C.dim,
                              fontSize: 9.5,
                              marginLeft: 5,
                              fontWeight: 400,
                              fontStyle: "italic",
                            }}>
                              ({pctPeriod >= 0 ? "+" : ""}{(pctPeriod * 100).toFixed(2)}% real)
                            </span>
                          )}
                        </span>
                      );
                    })()}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {/* Curva DLR + Detector de Basis (componente reusable, también en Dashboard) */}
      <DlrCurveSection dlrCurve={dlrCurve} C={C} />

      {/* Footer */}
      <div style={{ marginTop: 14, fontSize: 10, color: C.dim, letterSpacing: "0.05em", textTransform: "uppercase", fontWeight: 500 }}>
        Fuentes: dolarapi (spot) · Primary (DLR live + settle fallback) · BYMA/data912/MAE (precio bonos) · Tesoro Nacional (pago al vto, actualizado Mi/Ju). La TIR se recalcula sola con cada refresh.
      </div>

      {/* Modal de detalle multi-horizonte + simulador (Fase 1).
          Componente standalone — definido más abajo. Le pasamos la row
          completa, spot, futuresLive y curveData para el simulador. */}
      {expandedBond && (() => {
        const detail = rows.find((r) => r.bondTicker === expandedBond);
        if (!detail) return null;
        // Pasamos al modal la TIR ARS del bono más corto del menú como
        // proxy de tasa de caución / money market. El usuario puede
        // ajustarla en el componente comparativo.
        const candidates = rows
          .filter((r) => Number.isFinite(r.tirArs) && Number.isFinite(r.days) && r.days > 0)
          .sort((a, b) => a.days - b.days);
        const shortestBondTir = candidates.length > 0 ? candidates[0].tirArs : 0.30;
        return (
          <BondDetailModal
            row={detail}
            spotMayorista={spotMayorista}
            spotMep={spotMep}
            futuresLive={futuresLive}
            curveData={curveData}
            selectedHorizon={selectedHorizon}
            selectedStrategy={selectedStrategy}
            shortestBondTir={shortestBondTir}
            dlrCurve={dlrCurve}
            onClose={() => setExpandedBond(null)}
          />
        );
      })()}
    </div>
  );
}

/* ─────────── BondDetailModal (modal de detalle + simulador) ─────────── */

/**
 * Modal que se abre al clickear una fila del Sintético Dólar. Muestra:
 *   - Header con datos base del bono.
 *   - Tabla Single hedge: 5 horizontes × 2 modelos (const/curva) + DLR usado.
 *   - Tabla Rolling mensual: idem + path de DLRs.
 *   - Simulador: input USD → desglose paso a paso del armado del sintético
 *     y resultado final esperado bajo el horizonte/estrategia/modelo elegidos.
 *   - Notas metodológicas.
 *
 * Es componente externo (no inline IIFE) porque el simulador tiene state
 * propio (monto, estrategia/modelo locales del simulador).
 */
function BondDetailModal({ row, spotMayorista, spotMep, futuresLive, curveData, selectedHorizon, selectedStrategy, shortestBondTir, dlrCurve, onClose }) {
  // State del simulador (existente). Defaults: ARS 1.000.000, estrategia/horizonte
  // heredados de la pantalla principal, modelo "const" (escenario base).
  //
  // Currency toggle: por defecto entramos en ARS porque es la operativa
  // real (los bonos peso se compran con pesos; si tenes USD, primero los
  // vendes a MEP y despues comprás). USD queda como opcion para
  // simulaciones tipo "que pasa si entro hoy con X USD".
  // State del simulador. simInputAmount es STRING con formato AR (ej:
  // "1.000.000,00"). Se parsea con parseAmountString() para cálculos.
  const [simInputCurrency, setSimInputCurrency] = useState("ARS");
  const [simInputAmount, setSimInputAmount] = useState("1.000.000");
  const [simStrategy, setSimStrategy] = useState(selectedStrategy || "rolling");
  const [simHorizon, setSimHorizon] = useState(selectedHorizon || "vto");
  const [simModel, setSimModel] = useState("const");
  // Override manual del DLR usado en Single Hedge. null = AUTO (mejor DLR
  // automático según horizonte). String ticker = forzar ese DLR específico.
  // Útil para basis trading: el usuario ve la curva DLR, identifica un DLR
  // barato (basis verde), y lo selecciona acá para simular con ese hedge.
  // Solo aplica a Single Hedge (Rolling cambia DLR mes a mes).
  const [simSingleDlrOverride, setSimSingleDlrOverride] = useState(null);

  // State de la tabla comparativa de estrategias (nueva). Permite al usuario:
  //   - Ajustar la tasa de caución en TNA (default = TNA derivada del bono
  //     más corto del menú; la caución real argentina se cotiza siempre en
  //     TNA, no TEA, así que respetamos la convención del mercado).
  //   - Mover un slider de devaluación fino (0% a +5%, step 0.01) para
  //     explorar escenarios custom en el rango realista. Los escenarios
  //     extremos (+15%, -5%) están como columnas fijas.
  const defaultCaucionTNA = useMemo(() => {
    if (!Number.isFinite(shortestBondTir) || shortestBondTir <= 0) return 35;
    // Convertir TEA → TNA con capitalización diaria
    // TNA = 365 × ((1 + TEA)^(1/365) - 1)
    const tna = 365 * (Math.pow(1 + shortestBondTir, 1 / 365) - 1);
    return Number((tna * 100).toFixed(2));
  }, [shortestBondTir]);
  const [caucionRateInput, setCaucionRateInput] = useState(String(defaultCaucionTNA));
  // String con formato AR ("3,46"). Se parsea con parsePercentString().
  // Acepta negativos (para modelar apreciación del peso).
  const [customDevPercent, setCustomDevPercent] = useState("0");
  // Flag para no sobreescribir el input de devaluación si el usuario ya
  // lo tocó manualmente. Cuando llega el feed de argentinadatos, si el
  // flag es false, aplicamos el valor del feed como default.
  // (La caución NO necesita esto: su default es la TIR ARS del bono más
  // corto, calculado localmente, no viene de un feed externo).
  const [devTouched, setDevTouched] = useState(false);

  // Fetch a argentinadatos para default de devaluación.
  // El hook cachea a nivel módulo: 1 sola request por sesión, compartida.
  const { data: argentinaDatos } = useArgentinaDatos();

  // Default devaluación: último valor de inflación MENSUAL.
  // Es UN número de referencia que el usuario puede modificar manualmente.
  // No prorrateamos por horizonte porque la columna "Custom" de la tabla
  // muestra escenarios fijos (DOLAR PLANO / +15% / -5% / Custom) y el
  // valor que LP pone es el escenario que quiere modelar — su criterio.
  useEffect(() => {
    if (argentinaDatos?.inflacionMensual != null && !devTouched) {
      setCustomDevPercent(formatPercentInput(argentinaDatos.inflacionMensual.toFixed(2)));
    }
  }, [argentinaDatos, devTouched]);

  // Horizontes a mostrar en las tablas Single Hedge y Rolling Mensual del modal.
  // FILTRADO: omitimos los horizontes que exceden el vto del bono. Para un bono
  // a 36 días, no tiene sentido mostrar 60d/90d/180d porque internamente el cap
  // a min(horizon, daysAlVto) hace que esas filas tengan exactamente el mismo
  // número que la fila "Vto", generando 3 filas duplicadas que ensucian la
  // lectura. Para bonos cortos (S29Y6 a 4d), solo queda visible la fila Vto.
  // Para bonos largos (T30A7 a 340d), todas las filas se muestran.
  const HORIZONS_DISPLAY = [
    { id: "30", label: "30 días", days: 30 },
    { id: "60", label: "60 días", days: 60 },
    { id: "90", label: "90 días", days: 90 },
    { id: "180", label: "180 días", days: 180 },
    { id: "vto", label: `Vto (${row.days}d)`, days: row.days },
  ].filter((h) => h.id === "vto" || (Number.isFinite(h.days) && h.days < row.days));

  // Si simHorizon heredado de la pantalla principal ya no es válido (ej: pantalla
  // en "90d", click en S29Y6 a 4d → "90" no aparece más en HORIZONS_DISPLAY),
  // resetear a "vto" para que el botón quede seleccionado correctamente.
  useEffect(() => {
    const validIds = HORIZONS_DISPLAY.map(h => h.id);
    if (!validIds.includes(simHorizon)) {
      setSimHorizon("vto");
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [row.days]);

  // ─── Cálculo del simulador ──────────────────────────────
  // MODELO: operativa retail real argentina.
  //   - Día 0: el inversor vende USD a MEP (no al mayorista, retail no
  //     puede acceder). Si entra con ARS directamente, ya tiene los
  //     pesos. Capital ARS = arsCapital.
  //   - Día 0: compra bono peso + futuro DLR (bono en garantía).
  //   - Día H: vende el bono → ARS final. Cierra futuro → P&L embebido
  //     en el F_hedge efectivo.
  //   - Día H: con esos pesos compra MEP de nuevo. Asumimos convergencia
  //     MEP_expiry ≈ F_hedge (que ≈ mayorista_expiry por convergencia
  //     del futuro). Eso da: USD_final = ARS_final / F_hedge.
  //
  // El número resultante refleja el rendimiento que efectivamente
  // captura un inversor retail argentino, incluyendo el alfa del gap
  // MEP/mayorista del lado de entrada. Es la TIR USD operativamente real.
  //
  // Coincide con la TIR USD de la tabla principal (que también usa MEP
  // entrada / F_hedge salida) y con la columna "S. DLR (con MEP)" de
  // la comparativa de estrategias.
  const sim = useMemo(() => {
    const amount = parseAmountString(simInputAmount);
    if (!Number.isFinite(amount) || amount <= 0) return null;
    if (!Number.isFinite(spotMayorista) || spotMayorista <= 0) return null;
    if (!Number.isFinite(row.bondPrice) || row.bondPrice <= 0) return null;
    if (!Number.isFinite(row.maturityPayment) || row.maturityPayment <= 0) return null;

    // FX de entrada: MEP (operativa retail). Fallback al mayorista si
    // el feed dolarapi no responde.
    const fxEntry = (Number.isFinite(spotMep) && spotMep > 0) ? spotMep : spotMayorista;
    const mepIsFallback = !(Number.isFinite(spotMep) && spotMep > 0);

    // Horizonte efectivo (cap al vto del bono)
    const horizonValue = simHorizon === "vto" ? row.days : Number(simHorizon);
    const effH = Math.min(horizonValue, row.days);
    const daysRemaining = row.days - effH;

    // FX efectivo del hedge.
    let fxEffective = null;
    let dlrInfo = null;
    if (simStrategy === "rolling") {
      const r = computeRollingFxOut(spotMayorista, futuresLive, effH);
      if (r && Number.isFinite(r.fxEffective) && r.fxEffective > 0) {
        fxEffective = r.fxEffective;
        dlrInfo = { type: "rolling", path: r.dlrPath, isApprox: r.isApprox };
      }
    } else {
      // Single Hedge. Si hay override manual, usar ese DLR específico.
      // Si no, usar el "best automatic" (DLR más cercano al horizonte).
      let chosen = null;
      if (simSingleDlrOverride) {
        const manual = futuresLive.find((f) => f.ticker === simSingleDlrOverride);
        if (manual && Number.isFinite(manual.price) && manual.price > 0) {
          // Marcamos isApprox si el DLR vence ANTES del horizonte efectivo
          // (LP eligió un DLR que no cubre todo el plazo del bono — el
          // cálculo igual usa ese precio pero la cobertura es parcial).
          const isApprox = manual.expiryDays < effH;
          chosen = { ticker: manual.ticker, price: manual.price, expiryDays: manual.expiryDays, isApprox, isManual: true };
        }
      }
      if (!chosen) {
        const best = findBestSingleHedgeForHorizon(futuresLive, effH);
        if (best && Number.isFinite(best.price) && best.price > 0) {
          chosen = { ...best, isManual: false };
        }
      }
      if (chosen) {
        fxEffective = chosen.price;
        dlrInfo = { type: "single", ticker: chosen.ticker, price: chosen.price, expiryDays: chosen.expiryDays, isApprox: chosen.isApprox, isManual: chosen.isManual };
      }
    }
    if (!Number.isFinite(fxEffective) || fxEffective <= 0) return null;

    // Day 0: capital inicial.
    let arsCapital, usdOriginal;
    if (simInputCurrency === "USD") {
      // Entra con USD nominales, los vende al MEP (operativa real retail).
      usdOriginal = amount;
      arsCapital = amount * fxEntry;
    } else {
      arsCapital = amount;
      usdOriginal = null;
    }

    // USD equivalente del capital inicial al MEP.
    const usdEquivalentEntry = arsCapital / fxEntry;

    // VN del bono comprado
    const bondVN = (arsCapital * 100) / row.bondPrice;

    // TIR ARS según modelo (al horizonte H)
    const tirArsConst = Number.isFinite(row.tirArs) ? row.tirArs : null;
    const tirArsCurve = curveData
      ? interpolateLinear(curveData.xs, curveData.ys, daysRemaining)
      : null;
    const tirArsUsed = simModel === "curve" ? tirArsCurve : tirArsConst;
    if (!Number.isFinite(tirArsUsed)) return null;

    // Precio del bono al horizonte H
    const priceAtH = (effH === row.days)
      ? row.maturityPayment
      : computeBondPriceAtHorizon(row.maturityPayment, daysRemaining, tirArsUsed);

    // ARS recibidos al vender el bono al día H
    const arsFromBond = (bondVN * priceAtH) / 100;

    // USD final al FX del hedge (asumimos convergencia MEP_expiry ≈ F_hedge).
    const usdFinal = arsFromBond / fxEffective;

    // Profit USD: rendimiento operativamente real para retail.
    const usdProfit = usdFinal - usdEquivalentEntry;
    const usdPct = usdEquivalentEntry !== 0 ? usdProfit / usdEquivalentEntry : 0;

    // Profit ARS: ganancia bruta en pesos.
    const arsProfit = arsFromBond - arsCapital;
    const arsPct = arsCapital !== 0 ? arsProfit / arsCapital : 0;

    // TIR USD anualizada (coincide con la tabla principal y la comparativa).
    const tirUsdAnnualized = effH > 0
      ? Math.pow(usdFinal / usdEquivalentEntry, 365 / effH) - 1
      : null;

    return {
      simInputCurrency, amount,
      arsCapital, usdEquivalentEntry, usdOriginal,
      fxEntry, mepIsFallback, spotMep, spotMayorista,
      bondVN, priceAtH, arsFromBond,
      fxEffective, dlrInfo,
      usdFinal, usdProfit, usdPct,
      arsProfit, arsPct,
      tirUsdAnnualized,
      effH, daysRemaining, tirArsUsed,
      modelLabel: simModel === "curve" ? "curva" : "const",
    };
  }, [simInputAmount, simInputCurrency, simStrategy, simHorizon, simModel, simSingleDlrOverride, row, spotMayorista, spotMep, futuresLive, curveData]);

  // ─── Comparativa de estrategias (nueva sección) ──────────
  // [...] La comparativa REUTILIZA el ARS al horizonte H que ya calculó
  // el simulador (sim.arsFromBond), porque ese número considera el precio
  // del bono al horizonte (interpolado con el modelo elegido), NO el M
  // del vto. Si la comparativa usara M directo, sobreestimaría el
  // rendimiento cuando LP elige horizonte != vto (bug detectado en
  // captura de Rolling 30d donde simulador daba +31.50% pero comparativa
  // daba +37.99% por usar M en lugar de priceAtH).
  const scenarios = useMemo(() => {
    if (!sim) return null;
    const amount = parseAmountString(simInputAmount);
    if (!Number.isFinite(amount) || amount <= 0) return null;
    const MEP_hoy = (Number.isFinite(spotMep) && spotMep > 0) ? spotMep : spotMayorista;
    if (!Number.isFinite(MEP_hoy) || MEP_hoy <= 0) return null;
    const Spot_may = spotMayorista;
    const F_hedge = sim.fxEffective;
    const days = sim.effH; // horizonte efectivo del simulador
    if (!Number.isFinite(F_hedge) || F_hedge <= 0 || days <= 0) return null;

    // Capital inicial (común para todas las estrategias). Reutilizamos
    // los números del simulador para evitar inconsistencias.
    const usdIn = sim.usdEquivalentEntry;
    const arsIn = sim.arsCapital;
    if (!Number.isFinite(usdIn) || usdIn <= 0) return null;

    // Tasa de caución (input en TNA decimal). Default desde defaultCaucionTNA.
    const caucionTNA = parsePercentString(caucionRateInput) / 100;
    const caucionTNAvalid = Number.isFinite(caucionTNA) ? Math.max(0, caucionTNA) : 0.35;
    // TEA derivada (capitalización diaria), para mostrar como info.
    const caucionTEA = Math.pow(1 + caucionTNAvalid / 365, 365) - 1;

    // ARS al horizonte H para el bono = lo que ya calculó el simulador
    // (precio interpolado al horizonte, según modelo elegido). NO usar
    // M directo porque se rompe cuando horizonte != vto.
    const ARS_at_H_bono = sim.arsFromBond;
    // Caución: capitalización diaria sobre N días.
    //   factor = (1 + TNA/365)^N
    // (Asume rolear todos los días, que es lo típico de la caución bursátil
    // a 1 día. Si se usa cauciones a plazo fijo más largo el factor sería
    // lineal: 1 + TNA × N/365. Diferencia chica para horizontes cortos.)
    const factorCaucion = Math.pow(1 + caucionTNAvalid / 365, days);
    const ARS_at_H_caucion = arsIn * factorCaucion;

    // Definición de los escenarios de MEP_expiry
    const scenarioDefs = [
      { id: "plano", label: "Dólar plano", subLabel: "MEP al expiry = hoy", MEP_exp: MEP_hoy },
      { id: "curva", label: "Curva implícita", subLabel: `MEP al expiry: $${(MEP_hoy * F_hedge / Spot_may).toFixed(2)}`, MEP_exp: MEP_hoy * (F_hedge / Spot_may) },
      { id: "stress", label: "Devaluación +15%", subLabel: `MEP al expiry: $${(MEP_hoy * 1.15).toFixed(2)}`, MEP_exp: MEP_hoy * 1.15 },
      { id: "baja", label: "Dólar baja -5%", subLabel: `MEP al expiry: $${(MEP_hoy * 0.95).toFixed(2)}`, MEP_exp: MEP_hoy * 0.95 },
      { id: "custom", label: `Custom: ${parsePercentString(customDevPercent) >= 0 ? "+" : ""}${parsePercentString(customDevPercent).toFixed(2)}%`, subLabel: `MEP al expiry: $${(MEP_hoy * (1 + parsePercentString(customDevPercent) / 100)).toFixed(2)}`, MEP_exp: MEP_hoy * (1 + parsePercentString(customDevPercent) / 100) },
    ];

    // Calcular celdas
    const computeCell = (usdFinal) => {
      if (!Number.isFinite(usdFinal) || usdFinal <= 0) return null;
      const profit = usdFinal - usdIn;
      const pct = usdIn !== 0 ? profit / usdIn : 0;
      const tea = days > 0 ? Math.pow(usdFinal / usdIn, 365 / days) - 1 : 0;
      return { usdFinal, profit, pct, tea };
    };

    const rows = scenarioDefs.map((s) => {
      const cells = {
        sintetico: computeCell(ARS_at_H_bono / F_hedge),
        bonoSolo: computeCell(ARS_at_H_bono / s.MEP_exp),
        usd: computeCell(usdIn),
        caucion: computeCell(ARS_at_H_caucion / s.MEP_exp),
      };
      // Encontrar ganador (mayor TEA) entre las 4 estrategias
      let winner = null;
      let bestTea = -Infinity;
      for (const [key, cell] of Object.entries(cells)) {
        if (cell && Number.isFinite(cell.tea) && cell.tea > bestTea) {
          bestTea = cell.tea;
          winner = key;
        }
      }
      return { scenario: s, cells, winner };
    });

    return { rows, usdIn, arsIn, MEP_hoy, F_hedge, days, caucionTNA: caucionTNAvalid, caucionTEA };
  }, [sim, simInputAmount, simInputCurrency, caucionRateInput, customDevPercent, row, spotMayorista, spotMep]);

  // Texto explicativo dinámico debajo de la tabla
  const explanation = useMemo(() => {
    if (!scenarios) return null;
    const winners = scenarios.rows.map(r => r.winner);
    const wins = winners.reduce((acc, w) => { acc[w] = (acc[w] || 0) + 1; return acc; }, {});
    const dominant = Object.entries(wins).sort((a, b) => b[1] - a[1])[0];

    const sinteticoTea = scenarios.rows[0].cells.sintetico?.tea;
    const sinteticoPct = scenarios.rows[0].cells.sintetico?.pct;
    const bonoBajaTea = scenarios.rows[3].cells.bonoSolo?.tea;
    const bonoBajaPct = scenarios.rows[3].cells.bonoSolo?.pct;
    const bonoStressTea = scenarios.rows[2].cells.bonoSolo?.tea;
    const bonoStressPct = scenarios.rows[2].cells.bonoSolo?.pct;
    const days = scenarios.days;

    // Helper para formatear TEA con cap visual + agregar % período cuando aplique.
    // Si la TEA está capeada (horizonte corto la infla a >+99% o <-99%), agregamos
    // el % absoluto del período entre paréntesis para que el lector tenga el dato
    // realista de cuánto ganaría/perdería en ese horizonte concreto.
    const fmtTea = (tea, pct) => {
      if (!Number.isFinite(tea)) return "—";
      const f = formatTeaWithCap(tea);
      if (f.isCapped && Number.isFinite(pct)) {
        const pctStr = `${pct >= 0 ? "+" : ""}${(pct * 100).toFixed(2)}%`;
        return `${f.text} TEA (${pctStr} real en ${days}d)`;
      }
      return `${f.text} TEA`;
    };

    if (dominant && dominant[0] === "sintetico" && dominant[1] >= 3) {
      return {
        title: "El Sintético DLR domina hoy",
        body: `Te asegura ${fmtTea(sinteticoTea, sinteticoPct)} en USD sin importar lo que pase con el dólar. Bono peso solo te gana únicamente si el dólar baja (escenario -5%: ${fmtTea(bonoBajaTea, bonoBajaPct)}), pero te hundís si sube fuerte (+15%: ${fmtTea(bonoStressTea, bonoStressPct)}). Si querés rentabilidad USD asegurada, S. DLR es la elección clara hoy.`,
      };
    } else if (dominant && dominant[0] === "bonoSolo") {
      return {
        title: "Bono peso solo es el favorito hoy",
        body: `Asumiendo que el dólar se queda quieto o cae, el bono peso solo gana al Sintético. Pero ojo: pierde fuerte si el dólar sube (+15%: ${fmtTea(bonoStressTea, bonoStressPct)}). Si querés evitar ese downside, el Sintético DLR es un seguro razonable (${fmtTea(sinteticoTea, sinteticoPct)} fijo).`,
      };
    } else {
      return {
        title: "Resultados mixtos según escenario",
        body: `No hay un ganador único. Si tu hipótesis es que el dólar va a estar quieto o caer, conviene Bono peso solo. Si pensás que va a devaluar, conviene Sintético DLR. El sintético asegura ${fmtTea(sinteticoTea, sinteticoPct)} sin importar el escenario.`,
      };
    }
  }, [scenarios]);

  // ─── Helpers de render ──────────────────────────────────
  // Renderer de TEA con cap visual a ±99,9% y tooltip explicativo cuando
  // el horizonte corto la hace explotar (ej: S29Y6 a 4d con +2.1% absoluto
  // = +573% TEA anualizada — matematicamente correcto, operativamente irrealizable).
  const renderTirCell = (v) => {
    if (!Number.isFinite(v)) {
      return <span style={{ color: C.dim }}>—</span>;
    }
    const formatted = formatTeaWithCap(v);
    const color = row.isBontamAbovePremium
      ? C.muted
      : (v > 0 ? C.green : C.red);
    const fontWeight = row.isBontamAbovePremium ? 500 : 600;
    if (formatted.isCapped) {
      return (
        <span
          style={{ color, fontWeight, cursor: "help" }}
          title={`TEA real ≈ ${formatted.raw.toFixed(2)}%. Capeada visualmente porque al anualizar un retorno corto da números irrealizables. Mirá el % absoluto del período para la decisión real.`}
        >
          {formatted.text}
        </span>
      );
    }
    return (
      <span style={{ color, fontWeight }}>{formatted.text}</span>
    );
  };
  // Mini-badge de basis para mostrar al lado de un DLR usado en hedge.
  // Recibe ticker, devuelve un span con dot coloreado + tooltip explicativo.
  // Si dlrCurve no tiene info de ese ticker (ej: DLR ancla o sin datos),
  // devuelve null para no agregar nada visual.
  const basisBadge = (ticker) => {
    if (!dlrCurve || !dlrCurve.byTicker) return null;
    const point = dlrCurve.byTicker.get(ticker);
    if (!point) return null;
    const colorFor = (s) => {
      if (s === "barato") return C.green;
      if (s === "caro") return C.red;
      if (s === "ancla") return C.accent;
      return C.muted;
    };
    const color = colorFor(point.status);
    const tooltip = point.status === "ancla"
      ? `${ticker}: ancla de la curva DLR (basis por construcción = 0)`
      : `${ticker}: basis ${point.basisPct >= 0 ? "+" : ""}${point.basisPct.toFixed(2)}% vs curva lisa (precio real $${point.price.toFixed(2)}, teórico $${point.priceTheoric.toFixed(2)}). ${point.status === "barato" ? "Hedgear con este DLR captura alfa extra." : point.status === "caro" ? "Hedgear con este DLR tiene prima — evitar si hay alternativa." : "Cotiza alineado con la curva lisa."}`;
    return (
      <span
        title={tooltip}
        style={{ color, marginLeft: 4, fontSize: 11, cursor: "help", fontWeight: 700 }}
      >
        ●
      </span>
    );
  };
  const renderRollingPath = (h) => {
    const rp = row.multiTir?.rollingPaths?.[h];
    if (!rp || !Array.isArray(rp.dlrPath)) return <span style={{ color: C.dim }}>—</span>;
    return (
      <span style={{ fontSize: 10.5, color: C.muted, fontVariantNumeric: "tabular-nums" }}>
        {rp.dlrPath.map((seg, idx) => (
          <span key={idx}>
            {idx > 0 && <span style={{ color: C.dim, margin: "0 4px" }}>→</span>}
            <span style={{ color: C.text }}>{seg.ticker.replace("DLR", "")}</span>
            {basisBadge(seg.ticker)}
            <span style={{ color: C.dim, fontSize: 9.5, marginLeft: 3 }}>({seg.days}d)</span>
            {seg.isApprox && <span style={{ color: C.cat.violet, marginLeft: 2 }}>⚠</span>}
          </span>
        ))}
      </span>
    );
  };
  const thStyle = {
    padding: "8px 12px",
    fontSize: 9.5,
    color: C.dim,
    letterSpacing: "0.12em",
    textTransform: "uppercase",
    fontWeight: 600,
    textAlign: "right",
    whiteSpace: "nowrap",
    borderBottom: `1px solid ${C.border}`,
  };
  const thLeftStyle = { ...thStyle, textAlign: "left" };
  const tdStyle = {
    padding: "8px 12px",
    fontSize: 12,
    color: C.text,
    textAlign: "right",
    fontVariantNumeric: "tabular-nums",
    whiteSpace: "nowrap",
  };
  const tdLeftStyle = { ...tdStyle, textAlign: "left", color: C.muted };

  // Estilos compactos para los toggle del simulador (similar a la barra
  // de la tabla principal pero mas chico).
  const simToggleBtn = (active) => ({
    padding: "3px 10px",
    fontSize: 10,
    fontWeight: active ? 600 : 500,
    letterSpacing: "0.04em",
    color: active ? C.text : C.muted,
    background: active ? "rgba(91, 141, 214, 0.08)" : "transparent",
    border: `1px solid ${active ? C.accentBorder : C.border}`,
    cursor: "pointer",
    transition: "all 120ms ease",
  });

  // Estilos helper para la tabla comparativa de estrategias
  const scenarioHeaderStyle = () => ({
    padding: "8px 10px",
    textAlign: "left",
    borderBottom: `2px solid ${C.border}`,
    background: C.panel,
    fontWeight: 500,
    color: C.dim,
    fontSize: 10,
    letterSpacing: "0.05em",
    textTransform: "uppercase",
    verticalAlign: "top",
  });
  const scenarioCellLabelStyle = () => ({
    padding: "8px 10px",
    background: C.panel,
    borderRight: `1px solid ${C.border}`,
    verticalAlign: "middle",
  });
  const scenarioCellStyle = (isWinner) => ({
    padding: "8px 10px",
    textAlign: "left",
    background: isWinner ? "rgba(34, 197, 94, 0.10)" : "transparent",
    borderLeft: isWinner ? `2px solid ${C.green}` : `1px solid ${C.border}`,
    borderRight: isWinner ? `2px solid ${C.green}` : "none",
    verticalAlign: "middle",
  });

  return (
    <div
      onClick={onClose}
      style={{
        position: "fixed",
        inset: 0,
        background: "rgba(0,0,0,0.6)",
        backdropFilter: "blur(2px)",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        zIndex: 1000,
        padding: 20,
      }}
    >
      <div
        onClick={(e) => e.stopPropagation()}
        style={{
          background: C.panel,
          border: `1px solid ${C.border}`,
          maxWidth: 920,
          width: "100%",
          maxHeight: "92vh",
          overflow: "auto",
          boxShadow: "0 20px 60px rgba(0,0,0,0.5)",
        }}
      >
        {/* Header */}
        <div style={{
          padding: "18px 22px",
          borderBottom: `1px solid ${C.border}`,
          display: "flex",
          justifyContent: "space-between",
          alignItems: "flex-start",
          gap: 16,
        }}>
          <div>
            <div style={{ display: "flex", alignItems: "baseline", gap: 10 }}>
              <h2 style={{ fontSize: 18, fontWeight: 700, color: C.text, margin: 0, letterSpacing: "-0.01em" }}>
                {row.bondTicker}
              </h2>
              {row.bondType === "bontam" ? (
                <span style={{ color: C.cat?.yellow || "#fbbf24", fontSize: 10, textTransform: "uppercase", letterSpacing: "0.05em", fontWeight: 600 }}>
                  DUAL
                </span>
              ) : (
                <span style={{ color: C.dim, fontSize: 10, textTransform: "uppercase", letterSpacing: "0.05em" }}>
                  {row.bondType}
                </span>
              )}
            </div>
            <div style={{ marginTop: 4, fontSize: 11, color: C.muted, fontVariantNumeric: "tabular-nums" }}>
              Vto {row.bondMaturity} · {row.days} días
              {Number.isFinite(row.maturityPayment) && (
                <> · Pago al vto: <span style={{ color: C.text }}>{fmtNumber(row.maturityPayment, { minDecimals: 2, maxDecimals: 2 })}</span></>
              )}
              {Number.isFinite(row.bondPrice) && (
                <> · Precio: <span style={{ color: C.text }}>{fmtNumber(row.bondPrice, { minDecimals: 2, maxDecimals: 3, smartDecimals: true })}</span></>
              )}
              {Number.isFinite(row.tirArs) && (
                <> · TIR ARS: <span style={{ color: C.text }}>{fmtPct(row.tirArs * 100)}</span></>
              )}
            </div>
          </div>
          <button
            onClick={onClose}
            style={{
              background: "transparent",
              border: `1px solid ${C.border}`,
              color: C.muted,
              cursor: "pointer",
              padding: "4px 12px",
              fontSize: 11,
              letterSpacing: "0.05em",
            }}
          >
            Cerrar ✕
          </button>
        </div>

        {/* BONTAM warning */}
        {row.isBontamAbovePremium && (
          <div style={{ padding: "10px 22px", background: "rgba(250, 204, 21, 0.06)", borderBottom: `1px solid ${C.border}`, fontSize: 11, color: C.muted, lineHeight: 1.55 }}>
            <strong style={{ color: C.cat.yellow }}>Bono Dual con prima:</strong> el precio actual cotiza ARRIBA del piso de tasa fija. El mercado descuenta que TAMAR &gt; fija en promedio. Las TIRs USD mostradas son las del PEOR CASO. El payoff real probablemente sea mayor.
          </div>
        )}

        {/* Tabla Single hedge */}
        <div style={{ padding: "16px 22px" }}>
          <div style={{ display: "flex", alignItems: "baseline", gap: 10, marginBottom: 8 }}>
            <h3 style={{ fontSize: 12, fontWeight: 600, color: C.text, margin: 0, letterSpacing: "0.04em", textTransform: "uppercase" }}>
              Single hedge
            </h3>
            <span style={{ fontSize: 10.5, color: C.dim }}>
              Un solo DLR que cubre el horizonte. La columna "DLR usado" muestra cuál.
            </span>
          </div>
          <table style={{ width: "100%", borderCollapse: "collapse" }}>
            <thead>
              <tr>
                <th style={thLeftStyle}>Horizonte</th>
                <th style={thStyle}>TIR USD (const)</th>
                <th style={thStyle}>TIR USD (curva)</th>
                <th style={thLeftStyle}>DLR usado</th>
              </tr>
            </thead>
            <tbody>
              {HORIZONS_DISPLAY.map((h) => {
                const sh = row.multiTir?.singleHedges?.[h.id];
                return (
                  <tr key={`single-${h.id}`} style={{ borderBottom: `1px solid ${C.border}` }}>
                    <td style={tdLeftStyle}>{h.label}</td>
                    <td style={tdStyle}>{renderTirCell(row.multiTir?.single?.const?.[h.id])}</td>
                    <td style={tdStyle}>{renderTirCell(row.multiTir?.single?.curve?.[h.id])}</td>
                    <td style={{ ...tdLeftStyle, fontSize: 10.5 }}>
                      {sh ? (
                        <>
                          <span style={{ color: C.text }}>{sh.ticker.replace("DLR", "")}</span>
                          {basisBadge(sh.ticker)}
                          <span style={{ color: C.dim, fontSize: 9.5, marginLeft: 3 }}>({sh.expiryDays}d)</span>
                          {sh.isApprox && <span style={{ color: C.cat.violet, marginLeft: 2 }}>⚠</span>}
                        </>
                      ) : <span style={{ color: C.dim }}>—</span>}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>

        {/* Tabla Rolling mensual */}
        <div style={{ padding: "0 22px 16px 22px" }}>
          <div style={{ display: "flex", alignItems: "baseline", gap: 10, marginBottom: 8 }}>
            <h3 style={{ fontSize: 12, fontWeight: 600, color: C.text, margin: 0, letterSpacing: "0.04em", textTransform: "uppercase" }}>
              Rolling mensual
            </h3>
            <span style={{ fontSize: 10.5, color: C.dim }}>
              Compramos sucesivamente cada DLR mensual; al expirar, rolleamos al siguiente.
            </span>
          </div>
          <table style={{ width: "100%", borderCollapse: "collapse" }}>
            <thead>
              <tr>
                <th style={thLeftStyle}>Horizonte</th>
                <th style={thStyle}>TIR USD (const)</th>
                <th style={thStyle}>TIR USD (curva)</th>
                <th style={thLeftStyle}>Camino de DLRs</th>
              </tr>
            </thead>
            <tbody>
              {HORIZONS_DISPLAY.map((h) => (
                <tr key={`rolling-${h.id}`} style={{ borderBottom: `1px solid ${C.border}` }}>
                  <td style={tdLeftStyle}>{h.label}</td>
                  <td style={tdStyle}>{renderTirCell(row.multiTir?.rolling?.const?.[h.id])}</td>
                  <td style={tdStyle}>{renderTirCell(row.multiTir?.rolling?.curve?.[h.id])}</td>
                  <td style={tdLeftStyle}>{renderRollingPath(h.id)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* ─── SIMULADOR ─── */}
        <div style={{
          padding: "16px 22px",
          borderTop: `1px solid ${C.border}`,
          background: "rgba(91, 141, 214, 0.03)",
        }}>
          <div style={{ display: "flex", alignItems: "baseline", gap: 10, marginBottom: 12, flexWrap: "wrap" }}>
            <h3 style={{ fontSize: 12, fontWeight: 600, color: C.text, margin: 0, letterSpacing: "0.04em", textTransform: "uppercase" }}>
              Simulador con tu monto
            </h3>
            <span style={{ fontSize: 10.5, color: C.dim }}>
              Cambiá monto, estrategia, horizonte y modelo. Recalcula al instante.
            </span>
          </div>

          {/* Controles del simulador */}
          <div style={{ display: "flex", gap: 20, flexWrap: "wrap", alignItems: "center", marginBottom: 16, padding: "10px 14px", background: C.panel, border: `1px solid ${C.border}` }}>
            <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
              <span style={{ fontSize: 10, color: C.dim, letterSpacing: "0.1em", textTransform: "uppercase", fontWeight: 600 }}>Entrás con</span>
              {/* Toggle ARS/USD. La conversión visual usa spot mayorista
                  (consistente con el modelo del cálculo). Es solo un
                  ajuste de display para que el usuario tenga un valor
                  inicial razonable al cambiar de moneda. */}
              <div style={{ display: "flex", border: `1px solid ${C.accentBorder}` }}>
                <button
                  onClick={() => {
                    if (simInputCurrency === "USD") {
                      const fx = spotMayorista || 1;
                      const amountNum = parseAmountString(simInputAmount);
                      setSimInputAmount(formatAmountInput(String(Math.round(amountNum * fx))));
                    }
                    setSimInputCurrency("ARS");
                  }}
                  style={{
                    padding: "4px 10px",
                    background: simInputCurrency === "ARS" ? C.accent : "transparent",
                    border: "none",
                    color: simInputCurrency === "ARS" ? "#fff" : C.muted,
                    fontSize: 11,
                    fontWeight: 600,
                    cursor: "pointer",
                    fontFamily: "'Roboto', sans-serif",
                    letterSpacing: "0.02em",
                  }}
                >
                  ARS
                </button>
                <button
                  onClick={() => {
                    if (simInputCurrency === "ARS") {
                      const fx = spotMayorista || 1;
                      const amountNum = parseAmountString(simInputAmount);
                      // Convertir y formatear con 2 decimales (USD usa decimales)
                      const usdValue = (amountNum / fx).toFixed(2).replace(".", ",");
                      setSimInputAmount(formatAmountInput(usdValue));
                    }
                    setSimInputCurrency("USD");
                  }}
                  style={{
                    padding: "4px 10px",
                    background: simInputCurrency === "USD" ? C.accent : "transparent",
                    border: "none",
                    color: simInputCurrency === "USD" ? "#fff" : C.muted,
                    fontSize: 11,
                    fontWeight: 600,
                    cursor: "pointer",
                    fontFamily: "'Roboto', sans-serif",
                    letterSpacing: "0.02em",
                  }}
                >
                  USD
                </button>
              </div>
              <MoneyInput
                value={simInputAmount}
                onChange={setSimInputAmount}
                emit="ar"
                bare
                style={{
                  width: simInputCurrency === "ARS" ? 160 : 120,
                  padding: "5px 10px",
                  background: "transparent",
                  border: `1px solid ${C.accentBorder}`,
                  color: C.text,
                  fontSize: 13,
                  fontWeight: 600,
                  textAlign: "right",
                  fontVariantNumeric: "tabular-nums",
                  fontFamily: "'Roboto Mono', monospace",
                }}
              />
            </div>
            <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
              <span style={{ fontSize: 10, color: C.dim, letterSpacing: "0.1em", textTransform: "uppercase", fontWeight: 600 }}>Horizonte</span>
              {HORIZONS_DISPLAY.map((h) => (
                <button key={`sim-h-${h.id}`} onClick={() => setSimHorizon(h.id)} style={simToggleBtn(simHorizon === h.id)}>
                  {h.id === "vto" ? "Vto" : `${h.id}d`}
                </button>
              ))}
            </div>
            <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
              <span style={{ fontSize: 10, color: C.dim, letterSpacing: "0.1em", textTransform: "uppercase", fontWeight: 600 }}>Estrategia</span>
              <button onClick={() => setSimStrategy("single")} style={simToggleBtn(simStrategy === "single")}>Single</button>
              <button onClick={() => setSimStrategy("rolling")} style={simToggleBtn(simStrategy === "rolling")}>Rolling</button>
            </div>
            <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
              <span style={{ fontSize: 10, color: C.dim, letterSpacing: "0.1em", textTransform: "uppercase", fontWeight: 600 }}>Modelo</span>
              <button onClick={() => setSimModel("const")} style={simToggleBtn(simModel === "const")}>Const</button>
              <button onClick={() => setSimModel("curve")} style={simToggleBtn(simModel === "curve")}>Curva</button>
            </div>
            {/* Dropdown DLR para override manual (solo aplica a Single Hedge).
                Sirve para basis trading: ves la curva DLR, identificás un DLR
                barato (verde), y lo elegís acá para simular con ese hedge.
                IMPORTANTE: el precio del DLR afecta DIRECTAMENTE el USD final
                (USD = ARS_final / F_hedge). Un DLR con precio más bajo da MÁS
                USD final pero puede no cubrir el horizonte (expira antes).
                El basis (verde/rojo) indica posición vs curva lisa, no precio
                absoluto — útil para detectar dónde está alineado el mercado. */}
            {simStrategy === "single" && (
              <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
                <span style={{ fontSize: 10, color: C.dim, letterSpacing: "0.1em", textTransform: "uppercase", fontWeight: 600 }}>DLR</span>
                <select
                  value={simSingleDlrOverride || "AUTO"}
                  onChange={(e) => setSimSingleDlrOverride(e.target.value === "AUTO" ? null : e.target.value)}
                  style={{
                    backgroundColor: C.deep,
                    border: `1px solid ${simSingleDlrOverride ? C.accent : C.border}`,
                    color: C.text,
                    padding: "5px 10px",
                    fontSize: 11.5,
                    fontWeight: 500,
                    letterSpacing: "0.02em",
                    cursor: "pointer",
                    outline: "none",
                    fontFamily: "'Roboto Mono', monospace",
                    minWidth: 200,
                  }}
                  title="Cambiá el DLR del hedge para simular distintas coberturas. El precio del DLR afecta directamente el USD final: más bajo = más USD, más alto = menos USD."
                >
                  <option value="AUTO">AUTO (por horizonte)</option>
                  {futuresLive
                    .filter((f) => Number.isFinite(f.price) && f.price > 0)
                    .map((f) => {
                      const cp = dlrCurve && dlrCurve.byTicker ? dlrCurve.byTicker.get(f.ticker) : null;
                      const tag = cp
                        ? (cp.status === "barato" ? " ●barato"
                          : cp.status === "caro" ? " ●caro"
                          : cp.status === "ancla" ? " ⚓"
                          : "")
                        : "";
                      return (
                        <option key={f.ticker} value={f.ticker}>
                          {f.ticker.replace("DLR", "")} ({f.expiryDays}d) — ${f.price.toFixed(2)}{tag}
                        </option>
                      );
                    })}
                </select>
              </div>
            )}
          </div>

          {/* Resultado del simulador */}
          {sim ? (
            <div style={{ background: C.panel, border: `1px solid ${C.border}`, padding: "14px 18px", fontSize: 12, lineHeight: 1.7, color: C.text, fontVariantNumeric: "tabular-nums" }}>
              {/* Pasos */}
              <div style={{ marginBottom: 14 }}>
                {sim.simInputCurrency === "USD" ? (
                  <div style={{ color: C.muted, marginBottom: 2 }}>
                    <span style={{ color: C.dim, marginRight: 8, fontSize: 10 }}>1.</span>
                    Entrás con <strong style={{ color: C.text }}>USD {fmtARS(sim.amount)}</strong>, los vendés al <strong style={{ color: C.text }}>MEP ($ {fmtARS(sim.fxEntry)})</strong> → recibís <strong style={{ color: C.text }}>$ {fmtARS(sim.arsCapital)}</strong>.
                    {sim.mepIsFallback && (
                      <span style={{ color: "#eab308", fontSize: 10.5, fontStyle: "italic" }}>
                        {" "}⚠ MEP no disponible, usando mayorista (subestima el resultado).
                      </span>
                    )}
                  </div>
                ) : (
                  <div style={{ color: C.muted, marginBottom: 2 }}>
                    <span style={{ color: C.dim, marginRight: 8, fontSize: 10 }}>1.</span>
                    Entrás con <strong style={{ color: C.text }}>$ {fmtARS(sim.arsCapital)} ARS</strong>. Equivalen a <strong style={{ color: C.text }}>USD {fmtARS(sim.usdEquivalentEntry)}</strong> al MEP de hoy ($ {fmtARS(sim.fxEntry)}).
                    {sim.mepIsFallback && (
                      <span style={{ color: "#eab308", fontSize: 10.5, fontStyle: "italic" }}>
                        {" "}⚠ MEP no disponible, usando mayorista (subestima el resultado).
                      </span>
                    )}
                  </div>
                )}
                <div style={{ color: C.muted, marginBottom: 2 }}>
                  <span style={{ color: C.dim, marginRight: 8, fontSize: 10 }}>2.</span>
                  Comprás <strong style={{ color: C.text }}>{fmtARS(sim.bondVN)}</strong> VN de <strong style={{ color: C.text }}>{row.bondTicker}</strong> al precio <strong style={{ color: C.text }}>{fmtNumber(row.bondPrice, { minDecimals: 2, maxDecimals: 3 })}</strong> por 100 VN.
                </div>
                {sim.dlrInfo?.type === "single" && (
                  <div style={{ color: C.muted, marginBottom: 2 }}>
                    <span style={{ color: C.dim, marginRight: 8, fontSize: 10 }}>3.</span>
                    Hedgeás con futuro <strong style={{ color: C.text }}>{sim.dlrInfo.ticker.replace("DLR", "DLR/")}</strong> a <strong style={{ color: C.text }}>$ {fmtARS(sim.dlrInfo.price)}</strong>
                    {basisBadge(sim.dlrInfo.ticker)}
                    {sim.dlrInfo.isManual && (
                      <span style={{ color: C.accent, marginLeft: 6, fontSize: 10.5, fontStyle: "italic" }}>
                        (manual)
                      </span>
                    )}
                    {sim.dlrInfo.isApprox && (
                      <span style={{ color: "#eab308", marginLeft: 6, fontSize: 10.5 }}>
                        ⚠ DLR vence en {sim.dlrInfo.expiryDays}d, ANTES del horizonte ({sim.effH}d) — cobertura parcial
                      </span>
                    )}
                    .
                  </div>
                )}
                {sim.dlrInfo?.type === "rolling" && (
                  <div style={{ color: C.muted, marginBottom: 2 }}>
                    <span style={{ color: C.dim, marginRight: 8, fontSize: 10 }}>3.</span>
                    Hedgeás con rolling mensual: {sim.dlrInfo.path.map((seg, idx) => (
                      <span key={idx}>
                        {idx > 0 && <span style={{ color: C.dim }}> → </span>}
                        <strong style={{ color: C.text }}>{seg.ticker.replace("DLR", "")}</strong>
                        <span style={{ color: C.dim }}> {seg.days}d</span>
                      </span>
                    ))}
                    {sim.dlrInfo.isApprox && <span style={{ color: C.cat.violet, marginLeft: 4 }}>⚠ aprox</span>}
                  </div>
                )}
                <div style={{ color: C.muted, marginBottom: 2 }}>
                  <span style={{ color: C.dim, marginRight: 8, fontSize: 10 }}>4.</span>
                  Después de <strong style={{ color: C.text }}>{sim.effH} días</strong>{sim.daysRemaining > 0 ? ` (le quedarían ${sim.daysRemaining}d al bono)` : " (al vto del bono)"}, el bono vale <strong style={{ color: C.text }}>{fmtNumber(sim.priceAtH, { minDecimals: 2, maxDecimals: 3 })}</strong> por 100 VN (modelo {sim.modelLabel}).
                </div>
                <div style={{ color: C.muted, marginBottom: 2 }}>
                  <span style={{ color: C.dim, marginRight: 8, fontSize: 10 }}>5.</span>
                  Vendés el bono → recibís <strong style={{ color: C.text }}>$ {fmtARS(sim.arsFromBond)}</strong>.
                </div>
                <div style={{ color: C.muted }}>
                  <span style={{ color: C.dim, marginRight: 8, fontSize: 10 }}>6.</span>
                  Convertís pesos a USD al FX efectivo del hedge (<strong style={{ color: C.text }}>$ {fmtARS(sim.fxEffective)}</strong>, ≈ mayorista al expiry por convergencia del futuro) → <strong style={{ color: C.text }}>USD {fmtARS(sim.usdFinal)}</strong>.
                </div>
              </div>

              {/* Resultado bottom-line en doble columna ARS / USD */}
              <div style={{
                padding: "14px 16px",
                background: sim.usdProfit >= 0 ? "rgba(34, 197, 94, 0.08)" : "rgba(248, 113, 113, 0.08)",
                border: `1px solid ${sim.usdProfit >= 0 ? C.green : C.red}`,
                display: "grid",
                gridTemplateColumns: "1fr 1fr 1fr",
                gap: 14,
                alignItems: "center",
              }}>
                {/* Columna ARS */}
                <div>
                  <div style={{ fontSize: 9.5, color: C.dim, letterSpacing: "0.1em", textTransform: "uppercase", fontWeight: 600 }}>
                    Resultado ARS · {sim.effH}d
                  </div>
                  <div style={{ fontSize: 15, fontWeight: 700, color: sim.arsProfit >= 0 ? C.green : C.red, marginTop: 2 }}>
                    {sim.arsProfit >= 0 ? "+" : ""}$ {fmtARS(sim.arsProfit)}
                  </div>
                  <div style={{ fontSize: 11, color: C.muted, marginTop: 1 }}>
                    {sim.arsPct >= 0 ? "+" : ""}{fmtPct(sim.arsPct * 100)} bruto en pesos
                  </div>
                </div>
                {/* Columna USD */}
                <div>
                  <div style={{ fontSize: 9.5, color: C.dim, letterSpacing: "0.1em", textTransform: "uppercase", fontWeight: 600 }}>
                    Resultado USD · {sim.effH}d
                  </div>
                  <div style={{ fontSize: 15, fontWeight: 700, color: sim.usdProfit >= 0 ? C.green : C.red, marginTop: 2 }}>
                    {sim.usdProfit >= 0 ? "+" : ""}USD {fmtARS(sim.usdProfit)}
                  </div>
                  <div style={{ fontSize: 11, color: C.muted, marginTop: 1 }}>
                    {sim.usdPct >= 0 ? "+" : ""}{fmtPct(sim.usdPct * 100)} sobre tu USD inicial
                  </div>
                </div>
                {/* Columna TIR */}
                <div style={{ textAlign: "right" }}>
                  <div style={{ fontSize: 9.5, color: C.dim, letterSpacing: "0.1em", textTransform: "uppercase", fontWeight: 600 }}>
                    TIR USD anualizada
                  </div>
                  {(() => {
                    const teaFmt = formatTeaWithCap(sim.tirUsdAnnualized);
                    return (
                      <div
                        style={{
                          fontSize: 17,
                          fontWeight: 700,
                          color: sim.tirUsdAnnualized > 0 ? C.green : C.red,
                          marginTop: 2,
                          cursor: teaFmt.isCapped ? "help" : "default",
                        }}
                        title={teaFmt.isCapped
                          ? `TEA real ≈ ${teaFmt.raw.toFixed(2)}%. Capeada por horizonte corto. Para entender la ganancia real mirá los USD ganados/perdidos en absoluto.`
                          : undefined}
                      >
                        {teaFmt.text}
                      </div>
                    );
                  })()}
                  <div style={{ fontSize: 11, color: C.muted, marginTop: 1 }}>
                    USD final: <strong style={{ color: C.text }}>{fmtARS(sim.usdFinal)}</strong>
                  </div>
                </div>
              </div>

              {/* Descomposición educativa del USD profit:
                  alfa del bono (TIR ARS / MEP) + alfa del gap MEP↔F_hedge.
                  Le explica al usuario por qué el USD profit NO es simplemente
                  el ARS profit dividido por un FX. Hay dos componentes. */}
              {(() => {
                const arsProfit = sim.arsProfit;
                const MEP = sim.fxEntry;
                const F = sim.fxEffective;
                const arsFromBond = sim.arsFromBond;
                if (!Number.isFinite(arsProfit) || !Number.isFinite(MEP) || !Number.isFinite(F) || !Number.isFinite(arsFromBond)) return null;
                // Componente 1: ARS profit valuado al MEP entrada (rendimiento puro del bono en USD).
                const usdAlfaBono = arsProfit / MEP;
                // Componente 2: alfa del gap MEP vs F_hedge.
                //   arsFromBond / F_hedge - arsFromBond / MEP = arsFromBond × (MEP - F) / (MEP × F)
                const usdAlfaGap = arsFromBond * (MEP - F) / (MEP * F);
                const totalCheck = usdAlfaBono + usdAlfaGap;
                const gapSign = F < MEP ? "favorable" : (F > MEP ? "negativo" : "nulo");
                const gapColor = F < MEP ? C.green : (F > MEP ? C.red : C.muted);
                return (
                  <div style={{
                    marginTop: 14,
                    padding: "10px 14px",
                    background: "rgba(91, 141, 214, 0.06)",
                    borderLeft: `2px solid ${C.accentBorder}`,
                    fontSize: 11,
                    color: C.muted,
                    lineHeight: 1.6,
                  }}>
                    <div style={{ fontSize: 10, color: C.dim, letterSpacing: "0.1em", textTransform: "uppercase", fontWeight: 600, marginBottom: 5 }}>
                      ¿De dónde salen los USD {fmtARS(sim.usdProfit)}?
                    </div>
                    <div>
                      <span style={{ color: C.text, fontWeight: 600 }}>1) Rendimiento del bono en USD:</span> ARS profit ($ {fmtARS(arsProfit)}) ÷ MEP entrada ($ {fmtARS(MEP)}) = <strong style={{ color: C.text }}>USD {fmtARS(usdAlfaBono)}</strong>
                    </div>
                    <div>
                      <span style={{ color: C.text, fontWeight: 600 }}>2) Alfa del gap MEP vs F_hedge</span> <span style={{ color: gapColor }}>({gapSign})</span>:
                      el F_hedge ($ {fmtARS(F)}) está {F < MEP ? "más BARATO" : (F > MEP ? "más CARO" : "igual")} que el MEP de hoy ($ {fmtARS(MEP)}), gap de $ {(MEP - F).toFixed(2)}.
                      Eso suma <strong style={{ color: gapColor }}>{usdAlfaGap >= 0 ? "+" : ""}USD {fmtARS(usdAlfaGap)}</strong> al armado.
                    </div>
                    <div style={{ marginTop: 4, paddingTop: 4, borderTop: `1px solid ${C.border}` }}>
                      <strong style={{ color: C.text }}>Total:</strong> USD {fmtARS(usdAlfaBono)} + USD {fmtARS(usdAlfaGap)} = <strong style={{ color: sim.usdProfit >= 0 ? C.green : C.red }}>{sim.usdProfit >= 0 ? "+" : ""}USD {fmtARS(sim.usdProfit)}</strong>
                    </div>
                  </div>
                );
              })()}
            </div>
          ) : (
            <div style={{ padding: "14px 18px", background: C.panel, border: `1px solid ${C.border}`, fontSize: 12, color: C.muted }}>
              No se puede simular: faltan datos (monto, precio del bono, spot, MEP o futuro).
            </div>
          )}
        </div>

        {/* ═══════════════════════════════════════════════════════════ */}
        {/* SECCIÓN: COMPARATIVA DE ESTRATEGIAS                          */}
        {/* ═══════════════════════════════════════════════════════════ */}
        {scenarios && (
          <div style={{ padding: "20px 22px 18px 22px", borderTop: `1px solid ${C.border}` }}>
            <h3 style={{ margin: 0, marginBottom: 4, fontSize: 13, color: C.text, fontWeight: 600, letterSpacing: "0.02em", textTransform: "uppercase" }}>
              Comparativa de estrategias
            </h3>
            <p style={{ margin: 0, marginBottom: 14, fontSize: 11, color: C.muted, lineHeight: 1.5 }}>
              ¿Qué te conviene HOY con tu capital? El Sintético DLR aparece <strong style={{ color: C.text }}>plano</strong> en todos los escenarios (eso es lo que hace el hedge: protege contra cualquier movimiento del dólar). Bono peso solo y Caución son sensibles al dólar.
            </p>

            {/* Controles: caución + slider */}
            <div style={{ display: "flex", gap: 18, flexWrap: "wrap", alignItems: "center", marginBottom: 12, padding: "8px 12px", background: C.panel, border: `1px solid ${C.border}` }}>
              <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                <span style={{ fontSize: 10, color: C.dim, letterSpacing: "0.1em", textTransform: "uppercase", fontWeight: 600 }}>
                  Tasa caución
                </span>
                <input
                  type="text"
                  inputMode="decimal"
                  value={caucionRateInput}
                  onChange={(e) => setCaucionRateInput(formatPercentInput(e.target.value))}
                  style={{
                    width: 78,
                    padding: "4px 8px",
                    background: "transparent",
                    border: `1px solid ${C.accentBorder}`,
                    color: C.text,
                    fontSize: 12,
                    fontWeight: 600,
                    textAlign: "right",
                    fontVariantNumeric: "tabular-nums",
                    fontFamily: "'Roboto Mono', monospace",
                  }}
                />
                <span style={{ fontSize: 10, color: C.dim }}>% TNA</span>
                {scenarios && Number.isFinite(scenarios.caucionTEA) && (
                  <span style={{ fontSize: 10, color: C.muted, fontStyle: "italic" }}>
                    → {(scenarios.caucionTEA * 100).toFixed(2)}% TEA
                  </span>
                )}
              </div>
              <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                <span style={{ fontSize: 10, color: C.dim, letterSpacing: "0.1em", textTransform: "uppercase", fontWeight: 600 }}>
                  Devaluación
                </span>
                <input
                  type="text"
                  inputMode="decimal"
                  value={customDevPercent}
                  onChange={(e) => {
                    setDevTouched(true);
                    setCustomDevPercent(formatPercentInput(e.target.value));
                  }}
                  style={{
                    width: 78,
                    padding: "4px 8px",
                    background: "transparent",
                    border: `1px solid ${C.accentBorder}`,
                    color: C.text,
                    fontSize: 12,
                    fontWeight: 600,
                    textAlign: "right",
                    fontVariantNumeric: "tabular-nums",
                    fontFamily: "'Roboto Mono', monospace",
                  }}
                />
                <span style={{ fontSize: 10, color: C.dim }}>%</span>
                {spotMep > 0 && (
                  <span style={{ fontSize: 10, color: C.muted, fontStyle: "italic" }}>
                    → MEP $ {(spotMep * (1 + parsePercentString(customDevPercent) / 100)).toFixed(2)}
                  </span>
                )}
              </div>
            </div>

            {/* Tabla */}
            <div style={{ overflowX: "auto", border: `1px solid ${C.border}` }}>
              <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 11, fontVariantNumeric: "tabular-nums" }}>
                <thead>
                  <tr style={{ background: C.panel }}>
                    <th style={scenarioHeaderStyle()}>Estrategia</th>
                    {scenarios.rows.map((r) => (
                      <th key={`hdr-${r.scenario.id}`} style={scenarioHeaderStyle()}>
                        <div style={{ fontSize: 11, fontWeight: 600, color: C.text }}>{r.scenario.label}</div>
                        <div style={{ fontSize: 9, fontWeight: 400, color: C.dim, marginTop: 2 }}>{r.scenario.subLabel}</div>
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {[
                    { key: "sintetico", label: "Sintético DLR", sublabel: "bono peso + Fut DLR" },
                    { key: "bonoSolo", label: "Bono peso", sublabel: "sin hedge" },
                    { key: "usd", label: "Quedarte en USD", sublabel: "no hacer nada" },
                    { key: "caucion", label: "Caución ARS", sublabel: `${(scenarios.caucionTNA * 100).toFixed(1)}% TNA` },
                  ].map((strat) => (
                    <tr key={`row-${strat.key}`} style={{ borderTop: `1px solid ${C.border}` }}>
                      <td style={scenarioCellLabelStyle()}>
                        <div style={{ fontSize: 11, fontWeight: 600, color: C.text }}>{strat.label}</div>
                        <div style={{ fontSize: 9, color: C.dim, marginTop: 1 }}>{strat.sublabel}</div>
                      </td>
                      {scenarios.rows.map((r) => {
                        const cell = r.cells[strat.key];
                        const isWinner = r.winner === strat.key;
                        const teaFormatted = cell ? formatTeaWithCap(cell.tea) : null;
                        return (
                          <td key={`${strat.key}-${r.scenario.id}`} style={scenarioCellStyle(isWinner)}>
                            {cell ? (
                              <>
                                <div
                                  style={{
                                    fontSize: 12,
                                    fontWeight: 600,
                                    color: cell.tea >= 0 ? (isWinner ? C.green : C.text) : C.red,
                                    cursor: teaFormatted.isCapped ? "help" : "default",
                                  }}
                                  title={teaFormatted.isCapped
                                    ? `TEA real ≈ ${teaFormatted.raw.toFixed(2)}%. Capeada porque al anualizar un retorno extremo de un horizonte corto da números irrealizables. Mirá el % del período abajo para la decisión real.`
                                    : undefined}
                                >
                                  {teaFormatted.text}
                                </div>
                                <div style={{
                                  fontSize: 9,
                                  color: cell.pct >= 0 ? C.muted : C.red,
                                  marginTop: 1,
                                  opacity: 0.85,
                                }}>
                                  {cell.pct >= 0 ? "+" : ""}{(cell.pct * 100).toFixed(2)}% en {scenarios.days}d
                                </div>
                              </>
                            ) : (
                              <span style={{ color: C.dim }}>—</span>
                            )}
                          </td>
                        );
                      })}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            {/* Texto explicativo dinámico */}
            {explanation && (
              <div style={{
                marginTop: 12,
                padding: "10px 14px",
                background: "rgba(91, 141, 214, 0.08)",
                borderLeft: `3px solid ${C.accent}`,
              }}>
                <div style={{
                  fontSize: 11,
                  fontWeight: 600,
                  color: C.accent,
                  letterSpacing: "0.04em",
                  textTransform: "uppercase",
                  marginBottom: 4,
                }}>
                  {explanation.title}
                </div>
                <div style={{ fontSize: 11.5, color: C.text, lineHeight: 1.55 }}>
                  {explanation.body}
                </div>
              </div>
            )}

            {/* Leyenda */}
            <div style={{ marginTop: 10, fontSize: 9.5, color: C.dim, lineHeight: 1.5 }}>
              Cada celda muestra: <strong style={{ color: C.muted }}>TEA</strong> (rendimiento anualizado, comparable entre bonos) y, en chico, el % absoluto del período. <strong style={{ color: C.green }}>Verde</strong> = mejor estrategia del escenario.
              <br />
              <strong style={{ color: C.muted }}>Supuesto del Sintético DLR:</strong> al expiry, MEP converge al precio mayorista (que el futuro replica). En la realidad el gap MEP/mayorista no se cierra del todo, hay un riesgo residual de ±1-3 puntos sobre el resultado del armado.
            </div>
          </div>
        )}

        {/* Notas metodológicas + glosario */}
        <div style={{ padding: "12px 22px 18px 22px", borderTop: `1px solid ${C.border}`, fontSize: 10.5, color: C.muted, lineHeight: 1.6 }}>
          <div style={{ marginBottom: 6, fontWeight: 600, color: C.text, textTransform: "uppercase", letterSpacing: "0.05em", fontSize: 10 }}>
            Modelos del simulador
          </div>
          <strong style={{ color: C.text }}>Const:</strong> asume que la TIR ARS de hoy se mantiene hasta el horizonte. Escenario base, conservador.
          <br />
          <strong style={{ color: C.text }}>Curva:</strong> usa la curva LECAP/BONCAP actual para inferir qué TIR ARS tendrá el bono al horizonte. Más realista donde la curva está bien poblada.
          <br />
          <strong style={{ color: C.text }}>Rolling V1:</strong> asume cada DLR mantiene su precio actual hasta expirar. La Fase 2 va a refinar esto modelando la curva DLR completa y los roll costs reales.
          <br />
          <strong style={{ color: C.text }}>Cálculo operativo retail:</strong> USD inicial al MEP de hoy (operativa real, ya que retail no puede acceder al mayorista), USD final al FX del hedge (≈ mayorista al expiry por convergencia del futuro). Asumimos MEP_expiry ≈ mayorista_expiry — riesgo residual de ±1-3 puntos por movimientos del gap. Coincide con la TIR USD de la tabla principal y con la columna "S. DLR (con MEP)" de la comparativa.

          <div style={{ marginTop: 14, marginBottom: 6, fontWeight: 600, color: C.text, textTransform: "uppercase", letterSpacing: "0.05em", fontSize: 10 }}>
            Glosario rápido
          </div>
          <strong style={{ color: C.text }}>MEP:</strong> Dólar bolsa. El FX al que un inversor retail argentino convierte ARS↔USD (vía compra/venta de bonos como AL30/GD30).
          <br />
          <strong style={{ color: C.text }}>Spot mayorista:</strong> El FX del mercado interbancario (MAE/A3). Solo accesible a bancos y operadores mayoristas. El futuro DLR converge a este precio al expiry.
          <br />
          <strong style={{ color: C.text }}>Sintético DLR:</strong> Estrategia que combina un bono peso + futuros DLR para replicar un instrumento USD. Vendés MEP → comprás bono → ponés bono en garantía → comprás futuro DLR. Al expiry vendés bono y cerrás futuro, recibiendo USD.
          <br />
          <strong style={{ color: C.text }}>Caución ARS:</strong> Préstamo de pesos garantizado con bonos (típicamente 1-7 días, roleable). Se cotiza en TNA, no TEA. La tasa lineal sobre el período es ~ TNA × días/365.
          <br />
          <strong style={{ color: C.text }}>Curva implícita (en la comparativa):</strong> Escenario donde el dólar termina exactamente donde dice la curva de futuros DLR del mercado. Esa "predicción" del mercado se calcula sobre el ratio del futuro / mayorista de hoy.
          <br />
          <strong style={{ color: C.text }}>TEA:</strong> Tasa Efectiva Anual. Lo que rendiría tu inversión proyectada a 365 días con capitalización. Sirve para comparar entre activos de plazos distintos.
          <br />
          <strong style={{ color: C.text }}>TNA:</strong> Tasa Nominal Anual. Sin capitalizar. Es el formato estándar de cotización de caución, plazo fijo, etc.
          <br />
          <strong style={{ color: C.text }}>% del período (chiquito en cada celda):</strong> lo que efectivamente recibís al final del horizonte real (los días de la inversión), sobre el capital inicial. <em>El que importa para entender cuánta plata real ganás.</em>
          <br />
          <strong style={{ color: C.text }}>TEA (grande en cada celda):</strong> el rendimiento del período, anualizado y capitalizado. <em>Útil para comparar entre opciones de plazos distintos, pero NO es lo que recibís realmente en 37 días.</em>
        </div>
      </div>
    </div>
  );
}

/* ─────────── Futuros vs Caución Module ─────────── */

const DLR_PRICES_LS_KEY = "ecoflow:dlrPrices";
const DLR_PRICES_TS_LS_KEY = "ecoflow:dlrPricesUpdatedAt";
const CAUCION_LS_KEY = "ecoflow:caucionRate";
const CAUCION_MODE_LS_KEY = "ecoflow:caucionMode";  // "auto" | "manual"

/** Lee precios de DLR desde localStorage. Devuelve {} si no hay nada. */
function readStoredDlrPrices() {
  if (typeof window === "undefined") return {};
  try {
    const raw = window.localStorage.getItem(DLR_PRICES_LS_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch {
    return {};
  }
}

function readStoredDlrTimestamp() {
  if (typeof window === "undefined") return null;
  try {
    const raw = window.localStorage.getItem(DLR_PRICES_TS_LS_KEY);
    return raw ? new Date(raw) : null;
  } catch {
    return null;
  }
}

function readStoredCaucion() {
  if (typeof window === "undefined") return null;
  try {
    const raw = window.localStorage.getItem(CAUCION_LS_KEY);
    return raw ? parseFloat(raw) : null;
  } catch {
    return null;
  }
}

/** Lee el modo de caución persistido. Default: "auto" si nunca se eligió. */
function readStoredCaucionMode() {
  if (typeof window === "undefined") return "auto";
  try {
    const raw = window.localStorage.getItem(CAUCION_MODE_LS_KEY);
    return raw === "manual" ? "manual" : "auto";
  } catch {
    return "auto";
  }
}

/**
 * Extrae la tasa de caución de "1 día" de la respuesta de A3 Mercados.
 *
 * La API devuelve un array de operaciones de cauciones agrupadas por plazo.
 * Cada entrada tiene `codigoPlazo` (string), `ultimatasa` (decimal),
 * `volumenAcumulado`, `moneda`, etc. Para el carry trade nos interesa el
 * plazo más corto disponible (idealmente "001" = 1 día) en pesos ($).
 *
 * Estrategia:
 *   1. Filtrar solo cauciones en pesos.
 *   2. Buscar plazo "001" (1d) — fuente preferida.
 *   3. Si no hay 1d, tomar el plazo más corto disponible.
 *   4. Devolver la `ultimatasa` (TNA) de esa entrada.
 *
 * Devuelve { rate, plazo, volumen } o null si no hay datos parseables.
 */
function extractCaucion1d(a3Data) {
  if (!Array.isArray(a3Data) || a3Data.length === 0) return null;

  // Filtrar pesos. La API puede usar "$" o "ARS" según el campo.
  const pesos = a3Data.filter((c) => {
    const m = (c.moneda || "").trim();
    return m === "$" || m.toUpperCase() === "ARS";
  });
  if (pesos.length === 0) return null;

  // Preferir plazo "001"
  let target = pesos.find((c) => (c.codigoPlazo || c.plazo || "").trim() === "001");

  // Si no, tomar el plazo más corto (parseInt del codigoPlazo)
  if (!target) {
    const sorted = [...pesos].sort((a, b) => {
      const pa = parseInt((a.codigoPlazo || a.plazo || "999"), 10) || 999;
      const pb = parseInt((b.codigoPlazo || b.plazo || "999"), 10) || 999;
      return pa - pb;
    });
    target = sorted[0];
  }

  const rate = target?.ultimatasa ?? target?.tasaPP ?? null;
  if (rate == null || isNaN(rate) || rate <= 0) return null;

  return {
    rate: parseFloat(rate),
    plazo: (target.plazo || target.codigoPlazo || "").trim(),
    volumen: target.volumenAcumulado ?? null,
  };
}

/** Devuelve el precio efectivo de un contrato: stored si hay, sino el seed. */
function priceForContract(contract, storedPrices) {
  const stored = storedPrices[contract.ticker];
  if (stored != null && stored > 0) return stored;
  return contract.priceSeed;
}

/** Color del spread vs caución: positivo (futuro caro) = rojo, negativo (barato) = verde. */
function spreadColor(spreadPct) {
  if (spreadPct == null || isNaN(spreadPct)) return C.muted;
  if (spreadPct < -2) return "#4ADE80";  // barato fuerte
  if (spreadPct < 0)  return "#A3E635";  // barato leve
  if (spreadPct < 2)  return "#FACC15";  // neutro
  if (spreadPct < 5)  return "#FB923C";  // caro leve
  return "#F87171";                       // caro fuerte
}

function FuturosVsCaucionModule() {
  // ─── State ──────────────────────────────────────────────
  const [spotMayorista, setSpotMayorista] = useState(null);
  const [remTc, setRemTc] = useState({});
  const [storedPrices, setStoredPrices] = useState(() => readStoredDlrPrices());
  const [pricesUpdatedAt, setPricesUpdatedAt] = useState(() => readStoredDlrTimestamp());

  // Caución: doble fuente. `caucionAuto` viene de A3 Mercados (preferido).
  // `caucionManual` es el override que persiste en localStorage. El modo
  // dicta cuál se muestra. Si A3 falla, caemos automáticamente a manual
  // (o a 32 default si nunca se editó).
  const [caucionAuto, setCaucionAuto] = useState(null);          // { rate, plazo, volumen } | null
  const [caucionManual, setCaucionManual] = useState(() => readStoredCaucion() ?? 32);
  const [caucionMode, setCaucionMode] = useState(() => readStoredCaucionMode());

  const [editorOpen, setEditorOpen] = useState(false);
  const [editorBuffer, setEditorBuffer] = useState({});
  const [editorCaucion, setEditorCaucion] = useState(String(readStoredCaucion() ?? 32));
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState(null);
  const [lastFetch, setLastFetch] = useState(null);
  const [now, setNow] = useState(new Date());
  const [intervalMode, setIntervalMode] = useState(isActiveMarketWindow() ? "active" : "idle");

  // Calculadora manual
  const [calcSpot, setCalcSpot] = useState("");
  const [calcFuturo, setCalcFuturo] = useState("");
  const [calcDays, setCalcDays] = useState("");

  // Explicación didáctica (cerrada por default, los users que ya saben no la abren)
  const [explainerOpen, setExplainerOpen] = useState(false);

  // Tasa de caución efectiva: la que se usa en cálculos y se muestra como KPI.
  // Si el modo es auto y A3 respondió, usamos auto. Sino caemos a manual.
  const caucionRate = (caucionMode === "auto" && caucionAuto?.rate != null)
    ? caucionAuto.rate
    : caucionManual;

  // Tick para "now" en el StatusPill
  useEffect(() => {
    const i = setInterval(() => {
      setNow(new Date());
      setIntervalMode(isActiveMarketWindow() ? "active" : "idle");
    }, 1000);
    return () => clearInterval(i);
  }, []);

  // ─── Estrategia de fetching ─────────────────────────────
  //
  // Hay 3 fuentes con cadencias muy distintas:
  //   - Spot mayorista (dolarapi):  cambia intra-día → refrescar periódico
  //   - REM tipo de cambio (BCRA):  publicación mensual → fetch único al cargar
  //   - Caución A3 (snapshot):      cambia solo con redeploy → fetch único al cargar
  //
  // Por eso separamos:
  //   * fetchInitial()  → trae todo. Se usa al montar el módulo y en refresh manual.
  //   * fetchSpotOnly() → solo dólar mayorista. Se dispara por el timer cada 15 min.
  //
  // Esto evita gastar tiempo y bandwidth llamando endpoints que nunca cambian
  // entre fetches, y respeta los límites de las fuentes externas.

  /** Trae solamente el spot mayorista. Para uso del timer periódico. */
  const fetchSpotOnly = async () => {
    try {
      const fxRes = await fetch("/api/dolares");
      if (fxRes.ok) {
        const fx = await fxRes.json();
        const may = fx.find((d) => (d.casa || "").toLowerCase() === "mayorista");
        if (may?.venta) setSpotMayorista(may.venta);
      }
      setError(null);
      setLastFetch(new Date());
    } catch (e) {
      console.warn("spot refresh failed", e);
    }
  };

  /** Fetch inicial / refresh manual: trae todas las fuentes. */
  const fetchInitial = async (isManual = false) => {
    if (isManual) setRefreshing(true);
    else if (spotMayorista == null) setLoading(true);

    try {
      // 1) FX → buscamos casa "mayorista"
      const fxRes = await fetch("/api/dolares");
      if (fxRes.ok) {
        const fx = await fxRes.json();
        const may = fx.find((d) => (d.casa || "").toLowerCase() === "mayorista");
        if (may?.venta) setSpotMayorista(may.venta);
        else if (spotMayorista == null) setSpotMayorista(DLR_SPOT_SEED);
      } else if (spotMayorista == null) {
        setSpotMayorista(DLR_SPOT_SEED);
      }

      // 2) REM tipo de cambio (publicación mensual — fetch único)
      try {
        const remRes = await fetch("/api/bcra-rem?type=tipo_cambio");
        if (remRes.ok) {
          const remData = await remRes.json();
          const map = {};
          (remData.datos || []).forEach((d) => {
            const per = d["período"] ?? d.periodo;
            // Solo períodos con fecha mensual real (el API mete agregados anuales
            // "2026"/"2027" y "próx. 12 meses" que ensucian el mapa).
            if (per && /^\d{4}-\d{2}-\d{2}/.test(String(per)) && d.mediana != null) map[String(per).slice(0, 7)] = d.mediana;
          });
          setRemTc(map);
        }
      } catch (e) { console.warn("REM tipo_cambio failed", e); }

      // 3) Caución desde snapshot estático A3 (cambia solo con redeploy)
      try {
        const cauRes = await fetch("/api/a3-cauciones");
        if (cauRes.ok) {
          const cauData = await cauRes.json();
          const parsed = extractCaucion1d(cauData);
          if (parsed) {
            // Capturamos el timestamp del snapshot para mostrar "actualizado hace X"
            const snapshotAt = cauRes.headers.get("X-Snapshot-Generated-At")
              || cauRes.headers.get("x-snapshot-generated-at");
            setCaucionAuto({
              ...parsed,
              snapshotAt: snapshotAt ? new Date(snapshotAt) : null,
            });
          }
        } else {
          // 404/500 → no rompemos, dejamos caer al manual
          console.warn("A3 cauciones devolvió", cauRes.status);
        }
      } catch (e) { console.warn("A3 cauciones failed", e); }

      setError(null);
      setLastFetch(new Date());
    } catch (e) {
      setError(e.message || "Error al cargar datos");
      if (spotMayorista == null) setSpotMayorista(DLR_SPOT_SEED);
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  };

  // Alias para el botón Refresh manual del header (mantiene API esperada)
  const fetchAll = fetchInitial;

  // Mount: traer todo
  useEffect(() => { fetchInitial(); /* eslint-disable-next-line */ }, []);

  // Timer periódico: solo refrescar el spot mayorista
  useEffect(() => {
    let timeoutId;
    const schedule = () => {
      const ms = getRefreshIntervalMs();
      timeoutId = setTimeout(() => { fetchSpotOnly(); schedule(); }, ms);
    };
    schedule();
    return () => clearTimeout(timeoutId);
    // eslint-disable-next-line
  }, [intervalMode]);

  // ─── Procesamiento de contratos ────────────────────────
  const spot = spotMayorista ?? DLR_SPOT_SEED;

  const contracts = useMemo(() => {
    return DLR_REGISTRY
      .map((c) => {
        const days = daysToExpiry(c.maturityDate);
        const price = priceForContract(c, storedPrices);
        if (days <= 0) return null;
        return {
          ...c,
          price,
          days,
          tna: implicitTNA(price, spot, days),
          tem: implicitTEM(price, spot, days),
          tea: implicitTEA(price, spot, days),
        };
      })
      .filter(Boolean);
  }, [storedPrices, spot]);

  // Tasa forward entre contratos consecutivos (devaluación implícita mes a mes)
  const contractsWithForward = useMemo(() => {
    return contracts.map((c, i) => {
      if (i === 0) {
        // Primer contrato: forward vs spot (= TEM implícita ajustada al spread temporal)
        const dF = c.days;
        const fwd = dF > 0 ? Math.pow(c.price / spot, 30 / dF) - 1 : null;
        return { ...c, forwardTEM: fwd };
      }
      const prev = contracts[i - 1];
      const dGap = c.days - prev.days;
      if (dGap <= 0) return { ...c, forwardTEM: null };
      const fwd = Math.pow(c.price / prev.price, 30 / dGap) - 1;
      return { ...c, forwardTEM: fwd };
    });
  }, [contracts, spot]);

  // KPI: Devaluación REM como TNA implícita (proyectada al horizonte del ultimo contrato del REM)
  const remDevTNA = useMemo(() => {
    if (!spot || Object.keys(remTc).length === 0) return null;
    // Tomamos el ultimo periodo del REM disponible
    const sortedKeys = Object.keys(remTc).sort();
    if (!sortedKeys.length) return null;
    const lastKey = sortedKeys[sortedKeys.length - 1];
    const fxFuturo = remTc[lastKey];
    if (!fxFuturo) return null;
    // Calcular días desde hoy hasta el ultimo dia del periodo
    const [yr, mo] = lastKey.split("-").map(Number);
    const targetDate = new Date(yr, mo, 0); // último día del mes
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const days = Math.max(1, Math.round((targetDate - today) / 86400000));
    return implicitTNA(fxFuturo, spot, days);
  }, [remTc, spot]);

  // TNA implícita promedio de los contratos cortos (los primeros 3)
  const tnaProm = useMemo(() => {
    const slice = contractsWithForward.slice(0, 3).filter((c) => c.tna != null);
    if (!slice.length) return null;
    return slice.reduce((acc, c) => acc + c.tna, 0) / slice.length;
  }, [contractsWithForward]);

  const isStale = lastFetch && (now - lastFetch) / 1000 > (intervalMode === "active" ? 1080 : 2100);

  // ─── Editor de precios ─────────────────────────────────
  const openEditor = () => {
    // Inicializar buffer con valores actuales
    const buf = {};
    contracts.forEach((c) => {
      buf[c.ticker] = String(c.price);
    });
    setEditorBuffer(buf);
    setEditorCaucion(String(caucionRate));
    setEditorOpen(true);
  };

  const closeEditor = () => {
    setEditorOpen(false);
    setEditorBuffer({});
  };

  const saveEditor = () => {
    // Parse y filtrar valores válidos
    const newPrices = {};
    Object.entries(editorBuffer).forEach(([ticker, val]) => {
      const parsed = parseFloat(String(val).replace(",", "."));
      if (parsed > 0) newPrices[ticker] = parsed;
    });
    setStoredPrices(newPrices);
    const ts = new Date();
    setPricesUpdatedAt(ts);
    if (typeof window !== "undefined") {
      window.localStorage.setItem(DLR_PRICES_LS_KEY, JSON.stringify(newPrices));
      window.localStorage.setItem(DLR_PRICES_TS_LS_KEY, ts.toISOString());
    }
    // Caución → guardar como manual y cambiar modo
    const cau = parseFloat(String(editorCaucion).replace(",", "."));
    if (cau > 0) {
      setCaucionManual(cau);
      setCaucionMode("manual");
      if (typeof window !== "undefined") {
        window.localStorage.setItem(CAUCION_LS_KEY, String(cau));
        window.localStorage.setItem(CAUCION_MODE_LS_KEY, "manual");
      }
    }
    setEditorOpen(false);
  };

  /** Vuelve al modo auto (usar el valor de A3). */
  const switchToAutoCaucion = () => {
    setCaucionMode("auto");
    if (typeof window !== "undefined") {
      window.localStorage.setItem(CAUCION_MODE_LS_KEY, "auto");
    }
  };

  const resetSeed = () => {
    setStoredPrices({});
    setPricesUpdatedAt(null);
    if (typeof window !== "undefined") {
      window.localStorage.removeItem(DLR_PRICES_LS_KEY);
      window.localStorage.removeItem(DLR_PRICES_TS_LS_KEY);
    }
    closeEditor();
  };

  // Calculadora manual
  const calcSpotN = parseFloat(String(calcSpot).replace(/\./g, "").replace(",", "."));
  const calcFuturoN = parseFloat(String(calcFuturo).replace(/\./g, "").replace(",", "."));
  const calcDaysN = parseInt(calcDays, 10);
  const calcTNA = implicitTNA(calcFuturoN, calcSpotN, calcDaysN);
  const calcTEM = implicitTEM(calcFuturoN, calcSpotN, calcDaysN);
  const calcTEA = implicitTEA(calcFuturoN, calcSpotN, calcDaysN);

  return (
    <div className="px-6 py-5 eco-fade-in" style={{ minHeight: "100%" }}>
      {/* Header */}
      <div className="flex items-start justify-between gap-6 mb-5 flex-wrap">
        <div className="flex flex-col gap-1.5">
          <span style={{ fontSize: 9, color: C.dim, letterSpacing: "0.22em", textTransform: "uppercase", fontWeight: 500 }}>
            Analizadores · Futuros vs Caución
          </span>
          <h1 className="eco-display" style={{ fontSize: 24, fontWeight: 700, letterSpacing: "-0.01em", color: C.text, lineHeight: 1.1, margin: 0 }}>
            Dólar Futuro · Tasa Implícita
          </h1>
          <p style={{ fontSize: 11.5, color: C.muted, letterSpacing: "0.005em", maxWidth: 720, margin: "4px 0 0 0", lineHeight: 1.5 }}>
            Curva de contratos DLR (Matba-Rofex) y devaluación que están descontando. Compará contra caución pesos y proyección REM para detectar arbitrajes.
          </p>
        </div>
        <div className="flex items-center gap-2.5 flex-shrink-0">
          <StatusPill error={error} loading={loading || refreshing} isStale={isStale} lastFetch={lastFetch} now={now} />
          <RefreshButton onClick={() => fetchAll(true)} spinning={refreshing} />
        </div>
      </div>

      {/* Error inline */}
      {error && (
        <div className="flex items-start gap-3 p-4 mb-5" style={{ backgroundColor: "rgba(248,113,113,0.08)", border: `1px solid rgba(248,113,113,0.25)` }}>
          <AlertTriangle size={16} color={C.red} strokeWidth={1.8} />
          <div className="flex flex-col gap-0.5">
            <span style={{ fontSize: 12, color: C.text, fontWeight: 500 }}>No se pudieron cargar los datos</span>
            <span style={{ fontSize: 11, color: C.muted }}>{error}</span>
          </div>
        </div>
      )}

      {/* KPIs comparativos */}
      <SectionLabel>Indicadores de Referencia</SectionLabel>
      <div className="grid grid-cols-2 md:grid-cols-4 gap-3 mb-5">
        <KpiCard
          label="Spot Mayorista"
          value={spotMayorista ? `$${fmtARS(spotMayorista)}` : "—"}
          sub="BCRA A 3500"
          color={C.cat.cyan}
        />
        <CaucionKpi
          rate={caucionRate}
          mode={caucionMode}
          auto={caucionAuto}
          onSwitchToAuto={switchToAutoCaucion}
          now={now}
        />
        <KpiCard
          label="Dev. REM Implícita"
          value={remDevTNA != null ? fmtPct(remDevTNA * 100) : "—"}
          sub="TNA proyección REM"
          color={C.cat.emerald}
        />
        <KpiCard
          label="Tasa Implícita Prom."
          value={tnaProm != null ? fmtPct(tnaProm * 100) : "—"}
          sub="TNA · 3 contratos cortos"
          color={C.cat.violet}
        />
      </div>

      {/* Leyenda de los chips de estado del KPI Caución 1d.
          Aparece como un callout sutil para que el usuario entienda qué
          significa cada estado sin tener que pasar el mouse por el chip. */}
      <div
        className="flex items-start gap-2 mb-5 px-4 py-2.5"
        style={{
          backgroundColor: "rgba(246, 247, 246, 0.025)",
          borderLeft: `2px solid ${C.faint}`,
        }}
      >
        <Info size={12} color={C.dim} strokeWidth={1.8} style={{ flexShrink: 0, marginTop: 3 }} />
        <p style={{ fontSize: 11, color: C.muted, margin: 0, lineHeight: 1.6, letterSpacing: "0.005em" }}>
          <span style={{ color: C.dim, fontSize: 10, letterSpacing: "0.10em", textTransform: "uppercase", fontWeight: 500 }}>Caución 1d:</span>{" "}
          <ChipInline color={C.green} bg="rgba(74, 222, 128, 0.10)" border="rgba(74, 222, 128, 0.30)">Auto</ChipInline> tasa de A3 Mercados (snapshot reciente).{" "}
          <ChipInline color={C.cat.violet} bg="rgba(167, 139, 250, 0.10)" border="rgba(167, 139, 250, 0.30)">Manual</ChipInline> override del usuario o sin datos disponibles (feriado, fuera de horario, snapshot no actualizado).{" "}
          <ChipInline color={C.yellow} bg="rgba(250, 204, 21, 0.10)" border="rgba(250, 204, 21, 0.30)">Viejo</ChipInline> snapshot con más de 24 horas — pendiente de actualización.
        </p>
      </div>

      {/* Editor de precios — barra superior */}
      <div
        className="flex flex-wrap items-center justify-between gap-3 mb-3 px-4 py-2.5"
        style={{
          backgroundColor: C.panel,
          borderLeft: `2px solid ${C.cat.violet}`,
        }}
      >
        <div className="flex items-center gap-3 flex-wrap">
          <span style={{ fontSize: 10, color: C.dim, letterSpacing: "0.18em", textTransform: "uppercase", fontWeight: 500 }}>
            Precios
          </span>
          {pricesUpdatedAt ? (
            <span style={{ fontSize: 11, color: C.muted }}>
              Editados {timeAgo(pricesUpdatedAt, now)} · {pricesUpdatedAt.toLocaleString("es-AR", { day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit" })}
            </span>
          ) : (
            <span style={{ fontSize: 11, color: C.muted }}>
              Datos seed · {DLR_SEED_DATE}
            </span>
          )}
        </div>
        <div className="flex items-center gap-2">
          {pricesUpdatedAt && (
            <button
              onClick={resetSeed}
              style={{
                fontSize: 10,
                color: C.muted,
                backgroundColor: "transparent",
                border: `1px solid ${C.border}`,
                padding: "5px 10px",
                cursor: "pointer",
                letterSpacing: "0.10em",
                textTransform: "uppercase",
                fontWeight: 500,
              }}
            >
              Reset seed
            </button>
          )}
          <button
            onClick={editorOpen ? closeEditor : openEditor}
            style={{
              fontSize: 10,
              color: editorOpen ? C.cat.violet : C.text,
              backgroundColor: editorOpen ? "rgba(167,139,250,0.10)" : C.cat.violet,
              border: `1px solid ${C.cat.violet}`,
              padding: "5px 12px",
              cursor: "pointer",
              letterSpacing: "0.10em",
              textTransform: "uppercase",
              fontWeight: 600,
            }}
          >
            <Pencil size={10} strokeWidth={2} style={{ display: "inline-block", marginRight: 6, verticalAlign: -1 }} />
            {editorOpen ? "Cancelar" : "Editar precios"}
          </button>
        </div>
      </div>

      {/* Editor expandido */}
      {editorOpen && (
        <PriceEditor
          contracts={contracts}
          buffer={editorBuffer}
          setBuffer={setEditorBuffer}
          caucion={editorCaucion}
          setCaucion={setEditorCaucion}
          onSave={saveEditor}
          onCancel={closeEditor}
        />
      )}

      {/* Callout — explicación de la tabla */}
      <div
        className="flex items-start gap-2 mb-3 px-4 py-3"
        style={{
          backgroundColor: "rgba(56, 189, 248, 0.04)",
          borderLeft: `2px solid ${C.accent}`,
        }}
      >
        <Info size={13} color={C.accent} strokeWidth={1.8} style={{ flexShrink: 0, marginTop: 2 }} />
        <p style={{ fontSize: 11.5, color: C.muted, margin: 0, lineHeight: 1.55, letterSpacing: "0.005em" }}>
          La <span style={{ color: C.text, fontWeight: 500 }}>TNA implícita</span> es la devaluación anualizada que descuenta cada contrato vs el mayorista actual ($
          {spotMayorista ? fmtARS(spotMayorista) : "—"}). La <span style={{ color: C.text, fontWeight: 500 }}>Forward TEM</span> es la devaluación esperada mes a mes entre dos contratos consecutivos.{" "}
          <span style={{ color: C.green, fontWeight: 500 }}>vs Caución negativo</span> = futuro barato (vender futuro + colocar pesos en caución captura el spread).{" "}
          <span style={{ color: C.red, fontWeight: 500 }}>vs Caución positivo</span> = futuro caro (mercado descuenta más devaluación que la tasa pesos).
        </p>
      </div>

      {/* Tabla de contratos */}
      <SectionLabel>Curva de Futuros DLR</SectionLabel>
      <div style={{ backgroundColor: C.panel, borderTop: `2px solid ${C.cat.cyan}`, padding: "10px 14px" }}>
        {loading && contracts.length === 0 ? (
          <div className="flex items-center justify-center py-12">
            <Loader2 size={18} color={C.accent} className="eco-spin" strokeWidth={1.8} />
          </div>
        ) : (
          <div style={{ overflowX: "auto" }}>
            <table style={{ width: "100%", borderCollapse: "collapse", minWidth: 980 }}>
              <thead>
                <tr style={{ borderBottom: `1px solid ${C.border}` }}>
                  <Th align="left">Contrato</Th>
                  <Th align="right">Vto</Th>
                  <Th align="right">Días</Th>
                  <Th align="right">Precio</Th>
                  <Th align="right">TNA</Th>
                  <Th align="right">TEM</Th>
                  <Th align="right">TEA</Th>
                  <Th align="right">Forward TEM</Th>
                  <Th align="right" emphasized>vs Caución</Th>
                </tr>
              </thead>
              <tbody>
                {contractsWithForward.map((c) => {
                  const tnaPct = c.tna != null ? c.tna * 100 : null;
                  const spreadVsCaucion = (tnaPct != null && caucionRate) ? (tnaPct - caucionRate) : null;
                  const sColor = spreadColor(spreadVsCaucion);
                  return (
                    <tr key={c.ticker} className="eco-table-row" style={{ borderBottom: `1px solid ${C.border}` }}>
                      <Td align="left">
                        <span style={{ color: C.cat.cyan, fontWeight: 600, fontSize: 13 }}>{c.displayTicker}</span>
                      </Td>
                      <Td align="right" mono>{formatDate(c.maturityDate)}</Td>
                      <Td align="right" mono><span style={{ color: C.muted }}>{c.days}</span></Td>
                      <Td align="right" mono>${fmtARS(c.price)}</Td>
                      <Td align="right" mono>
                        <span style={{ color: C.text, fontWeight: 500 }}>
                          {tnaPct != null ? fmtPct(tnaPct) : "—"}
                        </span>
                      </Td>
                      <Td align="right" mono>
                        <span style={{ color: C.muted }}>
                          {c.tem != null ? fmtPct(c.tem * 100) : "—"}
                        </span>
                      </Td>
                      <Td align="right" mono>
                        <span style={{ color: C.muted }}>
                          {c.tea != null ? fmtPct(c.tea * 100) : "—"}
                        </span>
                      </Td>
                      <Td align="right" mono>
                        <span style={{ color: C.cat.emerald }}>
                          {c.forwardTEM != null ? fmtPct(c.forwardTEM * 100) : "—"}
                        </span>
                      </Td>
                      <Td align="right" mono>
                        <span style={{ color: sColor, fontWeight: 600 }}>
                          {spreadVsCaucion != null ? `${spreadVsCaucion >= 0 ? "+" : ""}${fmtPct(spreadVsCaucion)}` : "—"}
                        </span>
                      </Td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Curva de tasas implícitas */}
      <div className="mt-7">
        <div
          className="flex items-start gap-2 mb-3 px-4 py-3"
          style={{
            backgroundColor: "rgba(167, 139, 250, 0.04)",
            borderLeft: `2px solid ${C.cat.violet}`,
          }}
        >
          <Info size={13} color={C.cat.violet} strokeWidth={1.8} style={{ flexShrink: 0, marginTop: 2 }} />
          <p style={{ fontSize: 11.5, color: C.muted, margin: 0, lineHeight: 1.55, letterSpacing: "0.005em" }}>
            Cada punto es la <span style={{ color: C.text, fontWeight: 500 }}>TNA implícita</span> de un contrato. Si la curva está{" "}
            <span style={{ color: C.green, fontWeight: 500 }}>por debajo</span> de la línea de caución, el futuro está descontando menos devaluación que la tasa pesos —
            arbitraje clásico: vender futuro y colocar caución. Si está <span style={{ color: C.red, fontWeight: 500 }}>por encima</span>, el mercado descuenta salto cambiario o crisis de pesos.
          </p>
        </div>
        <SectionLabel>Curva de Tasas Implícitas</SectionLabel>
        <ImplicitRatesChart
          contracts={contractsWithForward}
          caucion={caucionRate}
          remDevTNA={remDevTNA}
        />
      </div>

      {/* Calculadora manual */}
      <div className="mt-7">
        <SectionLabel>Calculadora de Tasa Implícita</SectionLabel>
        <div style={{ backgroundColor: C.panel, borderTop: `2px solid ${C.cat.pink}`, padding: "16px 18px" }}>
          <CardHeader icon={Calculator} iconColor={C.cat.pink} label="Probá tu propio escenario" />
          <p style={{ fontSize: 11, color: C.muted, marginTop: -4, marginBottom: 14 }}>
            Ingresá Spot, Futuro y días al vencimiento. Útil para evaluar contratos no listados o escenarios hipotéticos.
          </p>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-3 mb-4">
            <CalcInput label="Spot (ARS)" value={calcSpot} onChange={setCalcSpot} placeholder={fmtARS(spot)} />
            <CalcInput label="Futuro (ARS)" value={calcFuturo} onChange={setCalcFuturo} placeholder="ej. 1500" />
            <CalcInput label="Días al Vto" value={calcDays} onChange={setCalcDays} placeholder="ej. 90" type="number" />
          </div>
          <div className="grid grid-cols-3 gap-3" style={{ paddingTop: 14, borderTop: `1px solid ${C.border}` }}>
            <CalcOutput label="TNA implícita" value={calcTNA != null ? fmtPct(calcTNA * 100) : "—"} color={C.cat.cyan} />
            <CalcOutput label="TEM implícita" value={calcTEM != null ? fmtPct(calcTEM * 100) : "—"} color={C.cat.emerald} />
            <CalcOutput label="TEA implícita" value={calcTEA != null ? fmtPct(calcTEA * 100) : "—"} color={C.cat.violet} />
          </div>
        </div>
      </div>

      {/* Bloque didáctico expandible — explica las fórmulas usadas */}
      <div className="mt-7" style={{ backgroundColor: C.panel, borderTop: `2px solid ${C.cat.cyan}` }}>
        <button
          onClick={() => setExplainerOpen((v) => !v)}
          style={{
            width: "100%",
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            padding: "12px 16px",
            backgroundColor: "transparent",
            border: "none",
            cursor: "pointer",
            color: C.text,
            textAlign: "left",
          }}
        >
          <div className="flex items-center gap-2.5">
            <BookOpenCheckIcon />
            <div className="flex flex-col">
              <span style={{ fontSize: 9, color: C.dim, letterSpacing: "0.18em", textTransform: "uppercase", fontWeight: 500 }}>
                Cómo se calcula
              </span>
              <span style={{ fontSize: 13, color: C.text, fontWeight: 500, marginTop: 2 }}>
                Tasas implícitas: TNA, TEM y TEA explicadas paso a paso
              </span>
            </div>
          </div>
          <ChevronDown
            size={16}
            color={C.muted}
            strokeWidth={1.6}
            style={{
              transform: explainerOpen ? "rotate(180deg)" : "rotate(0deg)",
              transition: "transform 0.2s ease",
            }}
          />
        </button>

        {explainerOpen && (
          <div style={{ padding: "4px 18px 18px", borderTop: `1px solid ${C.border}` }}>
            <CalcExplainer />
          </div>
        )}
      </div>

      {/* Footer estandarizado (componente compartido). */}
      <DataSourcesFooter
        lastUpdated={lastFetch}
        intervalMode={intervalMode}
        activeIntervalLabel="15 min"
        marginTop={28}
      />
    </div>
  );
}

/* ─────────── Subcomponentes Futuros vs Caución ─────────── */

function KpiCard({ label, value, sub, color }) {
  return (
    <div
      style={{
        backgroundColor: C.panel,
        borderTop: `2px solid ${color}`,
        padding: "10px 14px",
        display: "flex",
        flexDirection: "column",
        gap: 2,
      }}
    >
      <div style={{ fontSize: 9, color: C.dim, letterSpacing: "0.18em", textTransform: "uppercase", fontWeight: 500 }}>
        {label}
      </div>
      <div className="eco-mono" style={{ fontSize: 18, color: C.text, fontWeight: 600, letterSpacing: "-0.005em", lineHeight: 1.1 }}>
        {value}
      </div>
      {sub && (
        <div style={{ fontSize: 10, color: C.muted, marginTop: 2 }}>
          {sub}
        </div>
      )}
    </div>
  );
}

/**
 * KPI especializado de Caución 1d. Muestra el origen (A3 vs manual) en el
 * subtítulo y un mini-botón "auto" cuando el usuario está en override manual
 * pero hay un valor de A3 disponible al cual volver.
 */
/**
 * Chip pequeño usado en leyendas inline (ej. la guía de estados del
 * KPI Caución 1d). Mantiene el mismo estilo visual que los chips
 * reales del CaucionKpi para que el usuario pueda asociar cada uno
 * con su estado correspondiente.
 */
/**
 * Icono "BookOpenCheck" — un ícono SVG inline (no usamos lucide-react acá
 * porque lucide no exporta este icono específico en versiones viejas).
 * Mantiene el mismo grosor de stroke que el resto del set.
 */
function BookOpenCheckIcon({ size = 14, color = "currentColor" }) {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke={color}
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      style={{ flexShrink: 0, color: C.cat.cyan }}
    >
      <path d="M12 21V7" />
      <path d="m16 12 2 2 4-4" />
      <path d="M22 6V4a1 1 0 0 0-1-1h-5a4 4 0 0 0-4 4 4 4 0 0 0-4-4H3a1 1 0 0 0-1 1v13a1 1 0 0 0 1 1h6a3 3 0 0 1 3 3 3 3 0 0 1 3-3h6a1 1 0 0 0 1-1v-1.3" />
    </svg>
  );
}

/**
 * Bloque didáctico que explica paso a paso cómo se calculan las tasas
 * implícitas. Se renderiza dentro de un panel colapsable. Está pensado
 * para que un usuario sin background financiero entienda qué significa
 * cada columna de la tabla y la diferencia conceptual entre TNA, TEM y
 * TEA. Usa un ejemplo concreto con valores realistas para que se pueda
 * seguir paso a paso con calculadora en mano.
 */
function CalcExplainer() {
  return (
    <div style={{ fontSize: 12, color: C.muted, lineHeight: 1.65, letterSpacing: "0.005em" }}>
      <p style={{ margin: "10px 0 4px" }}>
        Toda <strong style={{ color: C.text, fontWeight: 600 }}>tasa implícita</strong> de un futuro de dólar
        parte de tres datos: el precio del contrato (<ExplainerVar>F</ExplainerVar>), el dólar spot de hoy
        (<ExplainerVar>S</ExplainerVar>) y los días que faltan hasta el vencimiento.
      </p>

      <ExplainerSection title="TNA — Tasa Nominal Anual" color={C.cat.cyan}>
        <ExplainerFormula>
          TNA = ( F / S − 1 ) × ( 365 / días )
        </ExplainerFormula>
        <p style={{ margin: "6px 0" }}>
          Mide cuánto subió el dólar entre hoy y el vencimiento, anualizado de forma <em>lineal</em>.
          Es la métrica más usada en mercado porque la <strong style={{ color: C.text }}>caución también
          se cotiza en TNA</strong>, y permite comparar directamente.
        </p>
        <ExplainerExample
          rows={[
            ["Datos", "F = 1.474 · S = 1.391 · días = 91"],
            ["Subió el dólar", "1.474 / 1.391 − 1 = 5,97%"],
            ["Anualizado", "5,97% × (365 / 91) = 23,93%"],
          ]}
        />
        <p style={{ margin: "8px 0 0", color: C.dim, fontSize: 11 }}>
          Lectura: <em>"si el dólar siguiera subiendo a este ritmo todo el año, cerraría 23,93% más arriba"</em>.
        </p>
      </ExplainerSection>

      <ExplainerSection title="TEM — Tasa Efectiva Mensual" color={C.cat.emerald}>
        <ExplainerFormula>
          TEM = ( F / S )<sup>30 / días</sup> − 1
        </ExplainerFormula>
        <p style={{ margin: "6px 0" }}>
          Mide cuánto sube el dólar <em>cada mes</em>, asumiendo capitalización compuesta. Sirve para
          comparar contra <strong style={{ color: C.text }}>inflación mensual</strong> y contra el
          crawling-peg del BCRA (~2% mensual).
        </p>
        <ExplainerExample
          rows={[
            ["Ratio futuro/spot", "1.474 / 1.391 = 1,0597"],
            ["Elevado a 30/días", "1,0597 ^ (30 / 91) = 1,0193"],
            ["Resta 1", "1,0193 − 1 = 1,93%"],
          ]}
        />
        <p style={{ margin: "8px 0 0", color: C.dim, fontSize: 11 }}>
          Lectura: <em>"al ritmo de subir 1,93% mes a mes, el dólar llega al precio del futuro en 91 días"</em>.
        </p>
      </ExplainerSection>

      <ExplainerSection title="TEA — Tasa Efectiva Anual" color={C.cat.violet}>
        <ExplainerFormula>
          TEA = ( F / S )<sup>365 / días</sup> − 1
        </ExplainerFormula>
        <p style={{ margin: "6px 0" }}>
          Igual que la TEM pero anualizada. Es la TNA "compuesta". Siempre va a ser un poco más alta que la
          TNA porque incluye el efecto de capitalización. Para el mismo ejemplo: TEA ≈ 26,17% vs TNA = 23,93%.
        </p>
      </ExplainerSection>

      <div
        style={{
          marginTop: 16,
          padding: "10px 14px",
          backgroundColor: "rgba(56, 189, 248, 0.04)",
          borderLeft: `2px solid ${C.accent}`,
        }}
      >
        <span style={{ fontSize: 10, color: C.dim, letterSpacing: "0.18em", textTransform: "uppercase", fontWeight: 600 }}>
          Forward TEM
        </span>
        <p style={{ margin: "6px 0 0", fontSize: 11.5, lineHeight: 1.6 }}>
          La columna <strong style={{ color: C.text }}>Forward TEM</strong> de la tabla aplica la fórmula
          de TEM pero entre <em>dos contratos consecutivos</em> (en vez de spot vs futuro). Te dice qué
          devaluación implícita está descontando el mercado <strong style={{ color: C.text }}>mes a mes</strong>:
          ej. cuánto sube de mayo a junio, de junio a julio, etc. Útil para detectar saltos cambiarios
          esperados en alguna ventana específica.
        </p>
      </div>
    </div>
  );
}

/** Variable inline en el explicador (F, S, días). */
function ExplainerVar({ children }) {
  return (
    <span
      style={{
        fontFamily: "'JetBrains Mono', monospace",
        color: C.text,
        backgroundColor: C.deep,
        padding: "1px 6px",
        fontSize: 11,
        fontWeight: 600,
      }}
    >
      {children}
    </span>
  );
}

/** Una sección dentro del explicador (TNA / TEM / TEA). */
function ExplainerSection({ title, color, children }) {
  return (
    <div style={{ marginTop: 18 }}>
      <div
        style={{
          fontSize: 10,
          color,
          letterSpacing: "0.18em",
          textTransform: "uppercase",
          fontWeight: 700,
          marginBottom: 8,
          paddingBottom: 6,
          borderBottom: `1px solid ${C.border}`,
        }}
      >
        {title}
      </div>
      {children}
    </div>
  );
}

/** Caja con la fórmula matemática destacada. */
function ExplainerFormula({ children }) {
  return (
    <div
      style={{
        fontFamily: "'JetBrains Mono', monospace",
        fontSize: 13,
        color: C.text,
        backgroundColor: C.deep,
        padding: "10px 14px",
        margin: "6px 0",
        textAlign: "center",
        letterSpacing: "0.02em",
      }}
    >
      {children}
    </div>
  );
}

/** Tabla mini con un ejemplo paso a paso. */
function ExplainerExample({ rows }) {
  return (
    <div
      style={{
        backgroundColor: "rgba(246, 247, 246, 0.02)",
        padding: "8px 12px",
        marginTop: 6,
        fontSize: 11.5,
      }}
    >
      <div style={{ fontSize: 9, color: C.dim, letterSpacing: "0.14em", textTransform: "uppercase", fontWeight: 500, marginBottom: 6 }}>
        Ejemplo · DLR/JUL26
      </div>
      <table style={{ borderCollapse: "collapse", width: "100%" }}>
        <tbody>
          {rows.map(([label, value], i) => (
            <tr key={i}>
              <td style={{ padding: "3px 12px 3px 0", color: C.muted, verticalAlign: "top", whiteSpace: "nowrap" }}>
                {label}
              </td>
              <td style={{ padding: "3px 0", color: C.text, fontFamily: "'JetBrains Mono', monospace", fontSize: 11 }}>
                {value}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

function ChipInline({ color, bg, border, children }) {
  return (
    <span
      style={{
        fontSize: 8,
        color,
        backgroundColor: bg,
        border: `1px solid ${border}`,
        padding: "1px 5px",
        letterSpacing: "0.10em",
        fontWeight: 600,
        textTransform: "uppercase",
        verticalAlign: "1px",
        whiteSpace: "nowrap",
      }}
    >
      {children}
    </span>
  );
}

function CaucionKpi({ rate, mode, auto, onSwitchToAuto, now }) {
  const isAuto = mode === "auto" && auto?.rate != null;

  // Calcular antigüedad del snapshot. Si tiene >24h, marca como "viejo".
  const snapshotAt = auto?.snapshotAt;
  let snapshotAge = null;     // string "hace X" o null
  let snapshotStale = false;  // true si > 24h
  if (snapshotAt && now) {
    const diffMs = now - snapshotAt;
    snapshotAge = timeAgo(snapshotAt, now);
    snapshotStale = diffMs > 24 * 60 * 60 * 1000;
  }

  const subText = isAuto
    ? (snapshotAge
        ? `A3 · plazo ${auto.plazo || "1d"} · ${snapshotAge}`
        : `A3 Mercados · plazo ${auto.plazo || "1d"}`)
    : (auto?.rate != null ? "Manual · override activo" : "Manual · sin datos A3");

  return (
    <div
      style={{
        backgroundColor: C.panel,
        borderTop: `2px solid ${C.cat.yellow}`,
        padding: "10px 14px",
        display: "flex",
        flexDirection: "column",
        gap: 2,
        position: "relative",
      }}
    >
      <div className="flex items-center justify-between gap-2">
        <div style={{ fontSize: 9, color: C.dim, letterSpacing: "0.18em", textTransform: "uppercase", fontWeight: 500 }}>
          Caución 1d
        </div>
        {/* Indicador del origen (chip mini) — verde auto, amarillo si snapshot viejo, violeta manual */}
        {isAuto ? (
          <span
            title={snapshotStale
              ? "Snapshot con más de 24hs · pendiente de actualización"
              : "Tasa desde snapshot A3 Mercados"}
            style={{
              fontSize: 8,
              color: snapshotStale ? C.yellow : C.green,
              backgroundColor: snapshotStale ? "rgba(250, 204, 21, 0.10)" : "rgba(74, 222, 128, 0.10)",
              border: `1px solid ${snapshotStale ? "rgba(250, 204, 21, 0.30)" : "rgba(74, 222, 128, 0.30)"}`,
              padding: "1px 5px",
              letterSpacing: "0.10em",
              fontWeight: 600,
              textTransform: "uppercase",
            }}
          >
            {snapshotStale ? "Viejo" : "Auto"}
          </span>
        ) : (
          <span
            title="Override manual activo"
            style={{
              fontSize: 8,
              color: C.cat.violet,
              backgroundColor: "rgba(167, 139, 250, 0.10)",
              border: `1px solid rgba(167, 139, 250, 0.30)`,
              padding: "1px 5px",
              letterSpacing: "0.10em",
              fontWeight: 600,
              textTransform: "uppercase",
            }}
          >
            Manual
          </span>
        )}
      </div>
      <div className="eco-mono" style={{ fontSize: 18, color: C.text, fontWeight: 600, letterSpacing: "-0.005em", lineHeight: 1.1 }}>
        {rate != null ? fmtPct(rate) : "—"}
      </div>
      <div className="flex items-center justify-between gap-2" style={{ marginTop: 2 }}>
        <span style={{ fontSize: 10, color: C.muted }}>{subText}</span>
        {/* Botón "Volver a auto" — solo visible si hay override y existe valor de A3 */}
        {!isAuto && auto?.rate != null && (
          <button
            onClick={onSwitchToAuto}
            style={{
              fontSize: 9,
              color: C.green,
              backgroundColor: "transparent",
              border: `1px solid rgba(74, 222, 128, 0.30)`,
              padding: "2px 7px",
              cursor: "pointer",
              letterSpacing: "0.08em",
              textTransform: "uppercase",
              fontWeight: 600,
            }}
          >
            ← Auto ({fmtPct(auto.rate)})
          </button>
        )}
      </div>
    </div>
  );
}

function PriceEditor({ contracts, buffer, setBuffer, caucion, setCaucion, onSave, onCancel }) {
  const updateField = (ticker, val) => {
    setBuffer((prev) => ({ ...prev, [ticker]: val }));
  };

  return (
    <div
      style={{
        backgroundColor: C.deep,
        border: `1px solid ${C.cat.violet}`,
        padding: "16px 18px",
        marginBottom: 14,
      }}
    >
      <div style={{ fontSize: 10, color: C.cat.violet, letterSpacing: "0.18em", textTransform: "uppercase", fontWeight: 600, marginBottom: 4 }}>
        Editor de precios manual
      </div>
      <p style={{ fontSize: 11, color: C.muted, margin: "0 0 14px 0", lineHeight: 1.5 }}>
        Copiá los precios del visor MtR (columna "Ajuste Ant." o "Últ.") y pegá acá. Se guardan en tu navegador.
      </p>

      {/* Grilla de precios DLR */}
      <div
        className="grid gap-3 mb-4"
        style={{ gridTemplateColumns: "repeat(auto-fill, minmax(160px, 1fr))" }}
      >
        {contracts.map((c) => (
          <div key={c.ticker} className="flex flex-col gap-1">
            <label style={{ fontSize: 10, color: C.dim, letterSpacing: "0.10em", textTransform: "uppercase", fontWeight: 500 }}>
              {c.displayTicker}
            </label>
            <MoneyInput
              value={buffer[c.ticker] ?? ""}
              onChange={(v) => updateField(c.ticker, v)}
              decimals={2}
              placeholder={String(c.priceSeed)}
              bare
              style={{
                backgroundColor: C.bg,
                border: `1px solid ${C.border}`,
                color: C.text,
                fontSize: 13,
                padding: "6px 10px",
                width: "100%",
              }}
            />
          </div>
        ))}
      </div>

      {/* Caución */}
      <div
        className="grid gap-3 mb-4"
        style={{
          gridTemplateColumns: "minmax(160px, 1fr) 1fr",
          paddingTop: 14,
          borderTop: `1px solid ${C.border}`,
        }}
      >
        <div className="flex flex-col gap-1">
          <label style={{ fontSize: 10, color: C.dim, letterSpacing: "0.10em", textTransform: "uppercase", fontWeight: 500 }}>
            Caución 1d (TNA %)
          </label>
          <input
            type="text"
            value={caucion}
            onChange={(e) => setCaucion(e.target.value)}
            placeholder="32"
            style={{
              backgroundColor: C.bg,
              border: `1px solid ${C.border}`,
              color: C.text,
              fontFamily: "'JetBrains Mono', monospace",
              fontSize: 13,
              padding: "6px 10px",
              outline: "none",
              width: "100%",
            }}
          />
        </div>
      </div>

      {/* Botones */}
      <div className="flex justify-end gap-2">
        <button
          onClick={onCancel}
          style={{
            fontSize: 11,
            color: C.muted,
            backgroundColor: "transparent",
            border: `1px solid ${C.border}`,
            padding: "7px 14px",
            cursor: "pointer",
            letterSpacing: "0.10em",
            textTransform: "uppercase",
            fontWeight: 500,
          }}
        >
          Cancelar
        </button>
        <button
          onClick={onSave}
          style={{
            fontSize: 11,
            color: C.bg,
            backgroundColor: C.cat.violet,
            border: `1px solid ${C.cat.violet}`,
            padding: "7px 16px",
            cursor: "pointer",
            letterSpacing: "0.10em",
            textTransform: "uppercase",
            fontWeight: 700,
          }}
        >
          Guardar
        </button>
      </div>
    </div>
  );
}

function CalcInput({ label, value, onChange, placeholder, type = "text" }) {
  return (
    <div className="flex flex-col gap-1">
      <label style={{ fontSize: 10, color: C.dim, letterSpacing: "0.18em", textTransform: "uppercase", fontWeight: 500 }}>
        {label}
      </label>
      <input
        type={type}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
        style={{
          backgroundColor: C.deep,
          border: `1px solid ${C.border}`,
          color: C.text,
          fontFamily: "'JetBrains Mono', monospace",
          fontSize: 14,
          padding: "8px 12px",
          outline: "none",
          width: "100%",
        }}
      />
    </div>
  );
}

function CalcOutput({ label, value, color }) {
  return (
    <div className="flex flex-col gap-1">
      <span style={{ fontSize: 9, color: C.dim, letterSpacing: "0.18em", textTransform: "uppercase", fontWeight: 500 }}>
        {label}
      </span>
      <span className="eco-mono" style={{ fontSize: 20, color, fontWeight: 600, letterSpacing: "-0.005em", lineHeight: 1.1 }}>
        {value}
      </span>
    </div>
  );
}

/* ─────────── Curva de Tasas Implícitas (gráfico) ─────────── */

function ImplicitRatesChart({ contracts, caucion, remDevTNA }) {
  if (!contracts || contracts.length === 0) {
    return (
      <div style={{ backgroundColor: C.panel, borderTop: `2px solid ${C.cat.violet}`, padding: 24, textAlign: "center" }}>
        <span style={{ fontSize: 12, color: C.muted }}>Sin datos para construir el gráfico.</span>
      </div>
    );
  }

  // Datos del scatter: x = días, y = TNA implícita (%)
  const scatterData = contracts
    .filter((c) => c.tna != null)
    .map((c) => ({
      x: c.days,
      y: c.tna * 100,
      ticker: c.displayTicker,
      maturityDate: c.maturityDate,
    }));

  if (scatterData.length === 0) {
    return (
      <div style={{ backgroundColor: C.panel, borderTop: `2px solid ${C.cat.violet}`, padding: 24, textAlign: "center" }}>
        <span style={{ fontSize: 12, color: C.muted }}>Sin tasas calculables — verificar spot y precios.</span>
      </div>
    );
  }

  const minX = 0;
  const maxX = Math.max(...scatterData.map((d) => d.x)) + 30;
  const allY = [
    ...scatterData.map((d) => d.y),
    caucion,
    remDevTNA != null ? remDevTNA * 100 : null,
  ].filter((v) => v != null && !isNaN(v));
  const minY = Math.min(...allY) - 3;
  const maxY = Math.max(...allY) + 3;
  const yDomain = [Math.floor(minY / 2) * 2, Math.ceil(maxY / 2) * 2];

  // Línea de la curva (los mismos puntos del scatter, conectados)
  const curveLine = [...scatterData].sort((a, b) => a.x - b.x);

  const renderDot = (props) => {
    const { cx, cy, payload } = props;
    if (cx == null || cy == null) return null;
    return (
      <g>
        <circle cx={cx} cy={cy} r={4.5} fill={C.cat.cyan} stroke={C.bg} strokeWidth={1.5} />
        <text
          x={cx}
          y={cy - 10}
          textAnchor="middle"
          fill={C.cat.cyan}
          fontSize={9}
          fontFamily="'JetBrains Mono', monospace"
          fontWeight={600}
          style={{ pointerEvents: "none", userSelect: "none" }}
        >
          {payload.ticker.replace("DLR/", "")}
        </text>
      </g>
    );
  };

  const tooltipContent = ({ active, payload }) => {
    if (!active || !payload || !payload.length) return null;
    const pt = payload.find((p) => p.payload && p.payload.ticker);
    if (!pt) return null;
    const data = pt.payload;
    return (
      <div
        style={{
          backgroundColor: C.deep,
          border: `1px solid ${C.borderStrong}`,
          padding: "9px 12px",
          fontSize: 11,
          fontFamily: "'JetBrains Mono', monospace",
          boxShadow: "0 4px 12px rgba(0, 0, 0, 0.5)",
          minWidth: 180,
        }}
      >
        <div style={{ color: C.cat.cyan, fontWeight: 700, marginBottom: 6 }}>
          {data.ticker}
        </div>
        <div style={{ color: C.muted, fontSize: 10, marginBottom: 6 }}>
          Vto: {data.maturityDate} · {data.x}d
        </div>
        <div style={{ color: C.text, display: "flex", justifyContent: "space-between", gap: 16 }}>
          <span style={{ color: C.muted }}>TNA implícita</span>
          <span style={{ color: C.text, fontWeight: 600 }}>{fmtPct(data.y)}</span>
        </div>
        {caucion != null && (
          <div
            style={{
              fontSize: 10,
              marginTop: 6,
              paddingTop: 6,
              borderTop: `1px solid ${C.border}`,
              display: "flex",
              justifyContent: "space-between",
              gap: 16,
              color: C.muted,
            }}
          >
            <span>vs Caución</span>
            <span style={{ color: spreadColor(data.y - caucion), fontWeight: 600 }}>
              {data.y - caucion >= 0 ? "+" : ""}{fmtPct(data.y - caucion)}
            </span>
          </div>
        )}
      </div>
    );
  };

  return (
    <div style={{ backgroundColor: C.panel, borderTop: `2px solid ${C.cat.violet}`, padding: "14px 14px 18px" }}>
      <div style={{ width: "100%", height: 420 }}>
        <ResponsiveContainer width="100%" height="100%">
          <ComposedChart margin={{ top: 24, right: 70, bottom: 50, left: 60 }}>
            <CartesianGrid strokeDasharray="3 3" stroke={C.border} opacity={0.4} />
            <XAxis
              dataKey="x"
              type="number"
              domain={[minX, maxX]}
              tickFormatter={(v) => `${v}d`}
              stroke={C.muted}
              style={{ fontSize: 10, fontFamily: "'JetBrains Mono', monospace" }}
              tickLine={{ stroke: C.border }}
              height={40}
            >
              <Label
                value="Días al vencimiento"
                position="insideBottom"
                offset={-30}
                style={{ fill: C.dim, fontSize: 11, fontFamily: "'Roboto', sans-serif", letterSpacing: "0.04em" }}
              />
            </XAxis>
            <YAxis
              type="number"
              domain={yDomain}
              tickFormatter={(v) => `${fmtPct(v)}`}
              stroke={C.muted}
              style={{ fontSize: 10, fontFamily: "'JetBrains Mono', monospace" }}
              tickLine={{ stroke: C.border }}
              width={60}
            >
              <Label
                value="TNA implícita"
                angle={-90}
                position="insideLeft"
                offset={5}
                style={{ textAnchor: "middle", fill: C.dim, fontSize: 11, fontFamily: "'Roboto', sans-serif", letterSpacing: "0.04em" }}
              />
            </YAxis>
            <RechartsTooltip
              content={tooltipContent}
              cursor={{ stroke: C.borderStrong, strokeDasharray: "3 3", strokeWidth: 1 }}
              isAnimationActive={false}
              wrapperStyle={{ outline: "none" }}
            />

            {/* Línea horizontal: caución actual */}
            {caucion != null && (
              <ReferenceLine
                y={caucion}
                stroke={C.cat.yellow}
                strokeWidth={1.5}
                strokeDasharray="6 4"
                label={{
                  value: `Caución ${fmtPct(caucion)}`,
                  position: "right",
                  fill: C.cat.yellow,
                  fontSize: 10,
                  fontFamily: "'JetBrains Mono', monospace",
                  fontWeight: 600,
                }}
              />
            )}

            {/* Línea horizontal: dev. REM */}
            {remDevTNA != null && (
              <ReferenceLine
                y={remDevTNA * 100}
                stroke={C.cat.emerald}
                strokeWidth={1.5}
                strokeDasharray="6 4"
                label={{
                  value: `REM ${fmtPct(remDevTNA * 100)}`,
                  position: "right",
                  fill: C.cat.emerald,
                  fontSize: 10,
                  fontFamily: "'JetBrains Mono', monospace",
                  fontWeight: 600,
                }}
              />
            )}

            {/* Curva uniendo los puntos */}
            <Line
              data={curveLine}
              type="monotone"
              dataKey="y"
              xAxisId={0}
              yAxisId={0}
              stroke={C.cat.cyan}
              strokeWidth={1.5}
              strokeOpacity={0.4}
              dot={false}
              activeDot={false}
              isAnimationActive={false}
              connectNulls
            />

            {/* Scatter de los contratos */}
            <Scatter
              data={scatterData}
              dataKey="y"
              xAxisId={0}
              yAxisId={0}
              shape={renderDot}
              isAnimationActive={false}
              name="DLR"
            />
          </ComposedChart>
        </ResponsiveContainer>
      </div>

      {/* Leyenda inferior */}
      <div className="flex items-center justify-center gap-5 mt-3 px-1" style={{ flexWrap: "wrap", fontSize: 10, color: C.muted, fontFamily: "'Roboto', sans-serif", letterSpacing: "0.04em" }}>
        <div className="flex items-center gap-2">
          <div style={{ width: 8, height: 8, borderRadius: "50%", backgroundColor: C.cat.cyan }} />
          <span>Contratos DLR</span>
        </div>
        <div className="flex items-center gap-2">
          <div style={{ width: 14, height: 1, borderTop: `2px dashed ${C.cat.yellow}` }} />
          <span>Caución 1d</span>
        </div>
        <div className="flex items-center gap-2">
          <div style={{ width: 14, height: 1, borderTop: `2px dashed ${C.cat.emerald}` }} />
          <span>REM proyectado</span>
        </div>
      </div>
    </div>
  );
}

/* ─────────── Helpers compartidos ─────────── */

function typeColor(type) {
  switch (type) {
    case "lecap": return C.cat.cyan;
    case "boncap": return C.cat.lime;
    case "dual": return C.cat.violet;
    case "cer": return C.cat.pink;
    default: return C.text;
  }
}


function typeLabel(type) {
  switch (type) {
    case "lecap": return "Lecap";
    case "boncap": return "Boncap";
    case "dual": return "Dual";
    case "cer": return "CER";
    default: return type;
  }
}

function formatDate(iso) {
  if (!iso) return "—";
  const d = new Date(iso + "T00:00:00");
  return d.toLocaleDateString("es-AR", { day: "2-digit", month: "short", year: "2-digit" }).replace(/\./g, "");
}
